        if not texto or not texto.strip():
            raise ValueError("Texto não pode ser vazio")
        self.autor = autor
        self.texto = texto
        self.removido = False
        self.respostas = []

    def adicionar_resposta(self, autor: str, texto: str) -> "Comentario":
        if not autor or not autor.strip():
            raise ValueError("Autor não pode ser vazio")
        if not texto or not texto.strip():
            raise ValueError("Texto não pode ser vazio")
        resposta = Comentario(autor, texto)
        self.respostas.append(resposta)
        return resposta

    def remover(self) -> None:
        self.removido = True
        self.texto = ""
        self.autor = ""

    def contar_descendentes(self) -> int:
        total = 0
        for resposta in self.respostas:
            total += 1
            total += resposta.contar_descendentes()
        return total

def ordenar_livros(livros):
    if not isinstance(livros, list):
        raise ValueError("Entrada deve ser uma lista")
    for livro in livros:
        if not isinstance(livro, dict):
            raise ValueError("Cada livro deve ser um dicionário")
        chaves_esperadas = {"titulo", "autor", "ano"}
        if set(livro.keys()) != chaves_esperadas:
            raise ValueError("Dicionário deve conter exatamente as chaves: titulo, autor, ano")
        if not isinstance(livro["ano"], int):
            raise ValueError("Ano deve ser um inteiro")
    return sorted(livros, key=lambda l: (l["ano"], l["autor"].lower(), l["titulo"].lower()))

def processar_atendimento(operacoes):
    if not isinstance(operacoes, list):
        raise ValueError("Operações deve ser uma lista")

    fila = []
    contador_chegada = 0
    resultados = []

    for op in operacoes:
        if not isinstance(op, str):
            raise ValueError("Operação deve ser string")

        partes = op.strip().split()
        if not partes:
            raise ValueError("Operação vazia")

        comando = partes[0]

        if comando == "CHEGADA":
            if len(partes) != 3:
                raise ValueError("CHEGADA requer nome e prioridade")
            nome = partes[1]
            try:
                prioridade = int(partes[2])
            except ValueError:
                raise ValueError("Prioridade deve ser inteiro")
            if prioridade not in (1, 2, 3):
                raise ValueError("Prioridade deve ser 1, 2 ou 3")
            if not nome:
                raise ValueError("Nome não pode ser vazio")
            fila.append((prioridade, contador_chegada, nome))
            contador_chegada += 1
            # Mantém ordenado por prioridade e ordem de chegada
            fila.sort(key=lambda x: (x[0], x[1]))

        elif comando == "ATENDER":
            if len(partes) != 1:
                raise ValueError("ATENDER não aceita parâmetros")
            if not fila:
                raise ValueError("Fila vazia")
            _, _, nome = fila.pop(0)
            resultados.append(nome)

        elif comando == "PROXIMO":
            if len(partes) != 1:
                raise ValueError("PROXIMO não aceita parâmetros")
            if not fila:
                raise ValueError("Fila vazia")
            _, _, nome = fila[0]
            resultados.append(nome)

        else:
            raise ValueError(f"Comando desconhecido: {comando}")

    return resultados

def percurso_em_espiral(matriz):
    if not isinstance(matriz, list) or len(matriz) == 0:
        raise ValueError("matriz vazia")
    ncols = None
    for linha in matriz:
        if not isinstance(linha, list):
            raise ValueError("linha nao e lista")
        if ncols is None:
            ncols = len(linha)
            if ncols == 0:
                raise ValueError("matriz vazia")
        elif len(linha) != ncols:
            raise ValueError("linhas com tamanhos diferentes")
    topo, base = 0, len(matriz) - 1
    esq, dir = 0, ncols - 1
    res = []
    while topo <= base and esq <= dir:
        for c in range(esq, dir + 1):
            res.append(matriz[topo][c])
        topo += 1
        for r in range(topo, base + 1):
            res.append(matriz[r][dir])
        dir -= 1
        if topo <= base:
            for c in range(dir, esq - 1, -1):
                res.append(matriz[base][c])
            base -= 1
        if esq <= dir:
            for r in range(base, topo - 1, -1):
                res.append(matriz[r][esq])
            esq += 1
    return res

class MatrizDiagonais:
    def __init__(self, matriz: list[list[int]]) -> None:
        if not matriz:
            raise ValueError("Matriz vazia")
        n = len(matriz)
        if any(len(linha) != n for linha in matriz):
            raise ValueError("Matriz nao quadrada")
        self._matriz = matriz
        self._n = n

    def diagonal_principal(self) -> list[int]:
        return [self._matriz[i][i] for i in range(self._n)]

    def diagonal_secundaria(self) -> list[int]:
        return [self._matriz[i][self._n - 1 - i] for i in range(self._n)]

    def soma_diagonais(self) -> int:
        total = 0
        for i in range(self._n):
            total += self._matriz[i][i]
            total += self._matriz[i][self._n - 1 - i]
        if self._n % 2 == 1:
            centro = self._n // 2
            total -= self._matriz[centro][centro]
        return total

    def produto_diagonais(self) -> int:
        prod = 1
        for i in range(self._n):
            prod *= self._matriz[i][i]
            prod *= self._matriz[i][self._n - 1 - i]
        if self._n % 2 == 1:
            centro = self._n // 2
            prod //= self._matriz[centro][centro]
        return prod

def ordenar_produtos(produtos):
    if produtos is None:
        raise ValueError("Lista de produtos não pode ser nula")

    chaves_obrigatorias = {'nome', 'preco', 'categoria'}

    for i, produto in enumerate(produtos):
        if not isinstance(produto, dict):
            raise ValueError(f"Elemento no índice {i} não é um dicionário")
        if not chaves_obrigatorias.issubset(produto.keys()):
            faltando = chaves_obrigatorias - produto.keys()
            raise ValueError(f"Produto no índice {i} não tem as chaves: {faltando}")

    return sorted(produtos, key=lambda p: (p['categoria'], -p['preco'], p['nome']))

def soma_divisores_proprios(n: int) -> int:
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n deve ser um inteiro positivo")
    if n == 1:
        return 0
    soma = 1
    limite = int(n ** 0.5)
    for d in range(2, limite + 1):
        if n % d == 0:
            soma += d
            outro = n // d
            if outro != d:
                soma += outro
    return soma

class ConsultaOrdenacao:
    def __init__(self, dados):
        self.dados = dados

    def aplicar(self, filtros, ordenacao, pagina, tamanho_pagina):
        if not isinstance(pagina, int) or pagina <= 0:
            raise ValueError("pagina deve ser inteiro positivo")
        if not isinstance(tamanho_pagina, int) or tamanho_pagina <= 0:
            raise ValueError("tamanho_pagina deve ser inteiro positivo")

        resultado = self.dados
        if filtros:
            for campo, valor in filtros.items():
                resultado = [item for item in resultado if item.get(campo) == valor]

        if ordenacao:
            for chave in reversed(ordenacao):
                reverso = chave.startswith("-")
                campo = chave[1:] if reverso else chave
                resultado = sorted(resultado, key=lambda x: x.get(campo), reverse=reverso)

        inicio = (pagina - 1) * tamanho_pagina
        fim = inicio + tamanho_pagina
        return resultado[inicio:fim]

import re
from collections import defaultdict


def analisar_palavras(texto):
    if not isinstance(texto, str):
        raise ValueError("O argumento deve ser uma string")

    # Extrai palavras: sequências de letras (A-Z, a-z)
    palavras = re.findall(r"[A-Za-z]+", texto)

    # Identifica palíndromos (ignorando maiúsculas/minúsculas)
    palindromos = []
    for p in palavras:
        if p.lower() == p.lower()[::-1]:
            palindromos.append(p)

    # Agrupa anagramas
    grupos = defaultdict(list)
    for p in palavras:
        chave = "".join(sorted(p.lower()))
        grupos[chave].append(p)

    anagramas = []
    for grupo in grupos.values():
        if len(grupo) >= 2:
            anagramas.append(grupo)

    # Palavras que não são palíndromos nem estão em grupos de anagramas
    palavras_em_anagramas = set()
    for grupo in anagramas:
        for p in grupo:
            palavras_em_anagramas.add(p)

    outras = []
    for p in palavras:
        if p not in palindromos and p not in palavras_em_anagramas:
            outras.append(p)

    return {
        "palindromos": palindromos,
        "anagramas": anagramas,
        "outras": outras
    }

def calcular_frete(uf, peso, valor):
    uf = uf.upper().strip()
    ufs_sul_sudeste = {"PR", "SC", "RS", "SP", "RJ", "ES", "MG"}
    ufs_norte_nordeste_centro = {
        "AC", "AP", "AM", "PA", "RO", "RR", "TO",
        "AL", "BA", "CE", "MA", "PB", "PE", "PI", "RN", "SE",
        "DF", "GO", "MT", "MS"
    }
    todas_ufs = ufs_sul_sudeste | ufs_norte_nordeste_centro

    if uf not in todas_ufs:
        raise ValueError("UF inválida")
    if peso <= 0:
        raise ValueError("Peso deve ser positivo")
    if valor < 0:
        raise ValueError("Valor não pode ser negativo")

    if valor > 500:
        return 0.0

    if uf in ufs_sul_sudeste:
        return round(peso * 10.0, 2)
    else:
        return round(peso * 15.0, 2)

def calcular_salario(horas_trabalhadas: float, valor_hora: float) -> float:
    if horas_trabalhadas < 0:
        raise ValueError("horas_trabalhadas não pode ser negativo")
    if valor_hora <= 0:
        raise ValueError("valor_hora deve ser positivo")

    horas_normais = min(horas_trabalhadas, 160)
    horas_extras = max(horas_trabalhadas - 160, 0)

    salario_normal = horas_normais * valor_hora
    salario_extra = horas_extras * valor_hora * 1.5

    return salario_normal + salario_extra

def calcular_horario_final(hora: int, minuto: int, duracao: int) -> tuple[int, int]:
    if not isinstance(hora, int) or not isinstance(minuto, int) or not isinstance(duracao, int):
        raise ValueError("Todos os argumentos devem ser inteiros")
    if not 0 <= hora <= 23:
        raise ValueError("Hora deve estar entre 0 e 23")
    if not 0 <= minuto <= 59:
        raise ValueError("Minuto deve estar entre 0 e 59")

    total_minutos = hora * 60 + minuto + duracao
    total_minutos %= 24 * 60
    if total_minutos < 0:
        total_minutos += 24 * 60

    hora_final = total_minutos // 60
    minuto_final = total_minutos % 60
    return (hora_final, minuto_final)

class SequenciaAritmetica:
    def __init__(self, primeiro: int, razao: int) -> None:
        self._atual = primeiro
        self._razao = razao

    def proximo(self) -> int:
        termo = self._atual
        self._atual += self._razao
        return termo

    def pular(self, n: int) -> int:
        if n < 0:
            raise ValueError("n deve ser não-negativo")
        self._atual += n * self._razao
        return self._atual

def calcular_histograma(itens, min_count=1):
    if not isinstance(min_count, int):
        raise TypeError("min_count deve ser um inteiro")
    if min_count < 1:
        raise ValueError("min_count deve ser >= 1")

    contagens = {}
    for item in itens:
        try:
            hash(item)
        except TypeError:
            raise TypeError(f"Item não-hashable encontrado: {item!r}")
        contagens[item] = contagens.get(item, 0) + 1

    return {item: count for item, count in contagens.items() if count >= min_count}

def velocidade_media(distancia: float, tempo: float) -> float:
    if distancia < 0:
        raise ValueError("Distância não pode ser negativa")
    if tempo <= 0:
        raise ValueError("Tempo deve ser maior que zero")
    return distancia / tempo

class CaixaSupermercado:
    def __init__(self):
        self._itens = {}

    def adicionar_item(self, nome: str, preco_unitario: float, quantidade: int) -> None:
        if preco_unitario <= 0 or quantidade <= 0:
            raise ValueError("Preço e quantidade devem ser positivos")
        subtotal = preco_unitario * quantidade
        if nome in self._itens:
            qtd_atual, sub_atual = self._itens[nome]
            self._itens[nome] = (qtd_atual + quantidade, sub_atual + subtotal)
        else:
            self._itens[nome] = (quantidade, subtotal)

    def fechar_compra(self) -> dict:
        if not self._itens:
            raise ValueError("Nenhum item na compra")
        itens_ordenados = sorted(
            [(nome, qtd, sub) for nome, (qtd, sub) in self._itens.items()],
            key=lambda x: x[0]
        )
        total_bruto = sum(sub for _, _, sub in itens_ordenados)
        desconto = total_bruto * 0.1 if total_bruto > 100 else 0.0
        total_liquido = total_bruto - desconto
        quantidade_total = sum(qtd for _, qtd, _ in itens_ordenados)
        return {
            'itens': itens_ordenados,
            'total_bruto': total_bruto,
            'desconto': desconto,
            'total_liquido': total_liquido,
            'quantidade_total_itens': quantidade_total
        }

def normalizar_registros(registros):
    if not isinstance(registros, list):
        raise TypeError("registros deve ser uma lista")
    normalizados = []
    for reg in registros:
        if not isinstance(reg, dict):
            raise TypeError("cada registro deve ser um dicionário")
        novo = {}
        for chave, valor in reg.items():
            chave_norm = str(chave).strip().lower()
            if isinstance(valor, str):
                valor_norm = valor.strip()
                if chave_norm == 'email':
                    valor_norm = valor_norm.lower()
            else:
                valor_norm = valor
            if chave_norm == 'idade':
                try:
                    valor_norm = int(valor_norm)
                except (ValueError, TypeError):
                    raise ValueError(f"idade inválida: {valor}")
            novo[chave_norm] = valor_norm
        normalizados.append(novo)
    return normalizados


def ordenar_registros(registros):
    if not isinstance(registros, list):
        raise TypeError("registros deve ser uma lista")
    return sorted(registros, key=lambda r: (r.get('idade', 0), str(r.get('nome', '')).lower()))

def tabela_com_totais(matriz):
    if not matriz:
        raise ValueError("matriz vazia")
    n_cols = len(matriz[0])
    for linha in matriz:
        if len(linha) != n_cols:
            raise ValueError("linhas com tamanhos diferentes")

    resultado = []
    for linha in matriz:
        total_linha = sum(linha)
        resultado.append(linha + [total_linha])

    totais_coluna = []
    for j in range(n_cols):
        soma = sum(matriz[i][j] for i in range(len(matriz)))
        totais_coluna.append(soma)
    totais_coluna.append(sum(totais_coluna))
    resultado.append(totais_coluna)

    return resultado

def _eh_bissexto(ano):
    return ano % 4 == 0 and (ano % 100 != 0 or ano % 400 == 0)

def _dias_no_mes(mes, ano):
    if mes == 2:
        return 29 if _eh_bissexto(ano) else 28
    if mes in {1, 3, 5, 7, 8, 10, 12}:
        return 31
    return 30

def _validar_data(data):
    if not isinstance(data, tuple) or len(data) != 3:
        raise ValueError("Data deve ser uma tupla de 3 inteiros")
    dia, mes, ano = data
    if not all(isinstance(x, int) and x > 0 for x in data):
        raise ValueError("Componentes da data devem ser inteiros positivos")
    if not 1 <= mes <= 12:
        raise ValueError("Mês inválido")
    if not 1 <= dia <= _dias_no_mes(mes, ano):
        raise ValueError("Dia inválido para o mês e ano")

def adicionar_dias(data, n):
    _validar_data(data)
    if not isinstance(n, int):
        raise ValueError("O número de dias deve ser um inteiro")

    dia, mes, ano = data

    if n >= 0:
        for _ in range(n):
            dia += 1
            if dia > _dias_no_mes(mes, ano):
                dia = 1
                mes += 1
                if mes > 12:
                    mes = 1
                    ano += 1
    else:
        for _ in range(-n):
            dia -= 1
            if dia < 1:
                mes -= 1
                if mes < 1:
                    mes = 12
                    ano -= 1
                dia = _dias_no_mes(mes, ano)

    return (dia, mes, ano)

def classificar_terremoto(magnitude: float) -> str:
    """Classifica um terremoto pela escala Richter.

    Args:
        magnitude: Magnitude do terremoto (valor real não-negativo).

    Returns:
        Classificação textual conforme a escala Richter.

    Raises:
        ValueError: Se magnitude for negativa ou não for um número real.
    """
    if not isinstance(magnitude, (int, float)) or isinstance(magnitude, bool):
        raise ValueError("Magnitude deve ser um número real.")
    if magnitude < 0:
        raise ValueError("Magnitude não pode ser negativa.")

    if magnitude < 2.0:
        return "Micro"
    elif magnitude < 4.0:
        return "Leve"
    elif magnitude < 5.0:
        return "Moderado"
    elif magnitude < 6.0:
        return "Forte"
    elif magnitude < 7.0:
        return "Muito forte"
    elif magnitude < 8.0:
        return "Grande"
    else:
        return "Massivo"

def agrupar_por_chave(itens, ordenar=False):
    if not isinstance(itens, list):
        raise TypeError("itens deve ser uma lista")
    resultado = {}
    for item in itens:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("cada elemento deve ser uma tupla de dois itens")
        chave, valor = item
        if chave not in resultado:
            resultado[chave] = []
        resultado[chave].append(valor)
    if ordenar:
        for chave in resultado:
            resultado[chave].sort()
    return resultado

def processar_fila(operacoes):
    fila = []
    resultados = []
    for op in operacoes:
        if not op or not isinstance(op, tuple):
            continue
        tipo = op[0]
        if tipo == "chegada":
            if len(op) >= 2:
                fila.append(op[1])
        elif tipo == "atendimento":
            if fila:
                resultados.append(fila.pop(0))
            else:
                resultados.append(None)
        elif tipo == "tamanho":
            resultados.append(len(fila))
    return resultados

def ajustar_indentacao(linhas: list[str], nivel: int) -> list[str]:
    if nivel < 0:
        raise ValueError("nível de indentação não pode ser negativo")
    prefixo = " " * (4 * nivel)
    resultado = []
    for linha in linhas:
        if linha.strip() == "":
            resultado.append(linha)
        else:
            resultado.append(prefixo + linha)
    return resultado

class CacheLRU:
    def __init__(self, capacidade: int):
        if capacidade <= 0:
            raise ValueError("Capacidade deve ser positiva")
        self.capacidade = capacidade
        self.dados = {}
        self.ordem = []

    def get(self, chave):
        if chave not in self.dados:
            return None
        self.ordem.remove(chave)
        self.ordem.append(chave)
        return self.dados[chave]

    def put(self, chave, valor):
        if chave in self.dados:
            self.ordem.remove(chave)
        elif len(self.dados) >= self.capacidade:
            lru = self.ordem.pop(0)
            del self.dados[lru]
        self.dados[chave] = valor
        self.ordem.append(chave)

class PlacarLideres:
    def __init__(self):
        self._dados = {}

    def registrar(self, nome: str, pontos: int) -> None:
        if not isinstance(nome, str) or not nome:
            raise ValueError("nome deve ser string não vazia")
        if not isinstance(pontos, int) or pontos <= 0:
            raise ValueError("pontos deve ser inteiro positivo")
        self._dados[nome] = pontos

    def top(self, k: int) -> list[tuple[str, int]]:
        if not isinstance(k, int) or k <= 0:
            raise ValueError("k deve ser inteiro positivo")
        ordenados = sorted(self._dados.items(), key=lambda x: (-x[1], x[0]))
        return ordenados[:k]

    def remover(self, nome: str) -> None:
        if not isinstance(nome, str):
            raise ValueError("nome deve ser string")
        self._dados.pop(nome, None)

class Paginador:
    def __init__(self, itens, tamanho_pagina):
        if tamanho_pagina <= 0:
            raise ValueError("tamanho_pagina deve ser positivo")
        self._itens = list(itens)
        self._tamanho = tamanho_pagina

    @property
    def total_paginas(self):
        if not self._itens:
            return 0
        return (len(self._itens) + self._tamanho - 1) // self._tamanho

    def _validar_numero(self, numero):
        if numero < 1 or numero > self.total_paginas:
            raise IndexError("número de página inválido")

    def pagina(self, numero):
        self._validar_numero(numero)
        inicio = (numero - 1) * self._tamanho
        fim = inicio + self._tamanho
        return self._itens[inicio:fim]

    def tem_proxima(self, numero):
        self._validar_numero(numero)
        return numero < self.total_paginas

class ConstrutorWhere:
    def __init__(self):
        self._condicoes = []
        self._operador_logico = None

    def igual(self, coluna, valor):
        self._condicoes.append((coluna, '=', valor))
        return self

    def comparar(self, coluna, operador, valor):
        operadores_validos = {'=', '!=', '<', '>', '<=', '>='}
        if operador not in operadores_validos:
            raise ValueError(f"Operador inválido: {operador}")
        self._condicoes.append((coluna, operador, valor))
        return self

    def e(self):
        if self._operador_logico is None:
            self._operador_logico = 'AND'
        elif self._operador_logico != 'AND':
            raise ValueError("Não é permitido misturar AND e OR")
        return self

    def ou(self):
        if self._operador_logico is None:
            self._operador_logico = 'OR'
        elif self._operador_logico != 'OR':
            raise ValueError("Não é permitido misturar AND e OR")
        return self

    def build(self):
        if not self._condicoes:
            raise ValueError("Nenhuma condição adicionada")
        if len(self._condicoes) > 1 and self._operador_logico is None:
            raise ValueError("Operador lógico não definido para múltiplas condições")

        partes = []
        parametros = []
        for coluna, operador, valor in self._condicoes:
            partes.append(f"{coluna} {operador} %s")
            parametros.append(valor)

        if self._operador_logico:
            sql = f" WHERE ({f' {self._operador_logico} '.join(partes)})"
        else:
            sql = f" WHERE {partes[0]}"

        return sql, parametros

def ganhar_xp(personagem: dict, xp_ganho: int) -> tuple[int, bool]:
    if xp_ganho < 0:
        raise ValueError("xp_ganho não pode ser negativo")
    if not isinstance(personagem, dict):
        raise ValueError("personagem deve ser um dicionário")
    if 'nivel' not in personagem or 'xp' not in personagem:
        raise ValueError("personagem deve ter chaves 'nivel' e 'xp'")
    nivel = personagem['nivel']
    xp = personagem['xp']
    if not isinstance(nivel, int) or not isinstance(xp, int):
        raise ValueError("nivel e xp devem ser inteiros")
    if nivel < 1 or xp < 0:
        raise ValueError("nivel deve ser >= 1 e xp >= 0")

    xp += xp_ganho
    subiu = False
    while True:
        xp_necessario = 100 * nivel
        if xp >= xp_necessario:
            xp -= xp_necessario
            nivel += 1
            subiu = True
        else:
            break
    personagem['nivel'] = nivel
    personagem['xp'] = xp
    return nivel, subiu

class ETLRegistros:
    def __init__(self, registros):
        self.registros = [dict(r) for r in registros]

    def normalizar_campos(self):
        normalizados = []
        for reg in self.registros:
            novo = {}
            for k, v in reg.items():
                nk = str(k).strip().lower()
                nv = v.strip() if isinstance(v, str) else v
                novo[nk] = nv
            normalizados.append(novo)
        self.registros = normalizados
        return self

    def filtrar_validos(self, campos_obrigatorios):
        if not isinstance(campos_obrigatorios, (list, tuple)):
            raise TypeError("campos_obrigatorios deve ser lista ou tupla")
        validos = []
        for reg in self.registros:
            ok = True
            for c in campos_obrigatorios:
                if c not in reg or reg[c] is None or (isinstance(reg[c], str) and reg[c].strip() == ""):
                    ok = False
                    break
            if ok:
                validos.append(reg)
        self.registros = validos
        return self

    def agregar_por(self, campo, funcao):
        if not self.registros:
            self.registros = []
            return self
        if campo not in self.registros[0]:
            raise ValueError(f"Campo '{campo}' não encontrado")
        if funcao not in ("soma", "media", "contagem"):
            raise ValueError(f"Função '{funcao}' não suportada")
        grupos = {}
        for reg in self.registros:
            chave = reg[campo]
            valor = reg.get("valor")
            if not isinstance(valor, (int, float)):
                continue
            grupos.setdefault(chave, []).append(valor)
        resultado = []
        for chave, valores in grupos.items():
            if funcao == "soma":
                agg = sum(valores)
            elif funcao == "media":
                agg = sum(valores) / len(valores)
            else:
                agg = len(valores)
            resultado.append({campo: chave, funcao: agg})
        self.registros = resultado
        return self

FERIADOS_FIXOS = {
    "01/01", "21/04", "01/05", "07/09",
    "12/10", "02/11", "15/11", "25/12"
}

DIAS_POR_MES = {
    1: 31, 2: 29, 3: 31, 4: 30, 5: 31, 6: 30,
    7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31
}

def _validar_data(data: str) -> tuple[int, int]:
    if not isinstance(data, str):
        raise ValueError("Data deve ser uma string")
    partes = data.split("/")
    if len(partes) != 2:
        raise ValueError("Formato inválido, use DD/MM")
    dia_str, mes_str = partes
    if not (dia_str.isdigit() and mes_str.isdigit()):
        raise ValueError("Dia e mês devem ser numéricos")
    if len(dia_str) != 2 or len(mes_str) != 2:
        raise ValueError("Dia e mês devem ter dois dígitos")
    dia = int(dia_str)
    mes = int(mes_str)
    if mes < 1 or mes > 12:
        raise ValueError("Mês inválido")
    if dia < 1 or dia > DIAS_POR_MES[mes]:
        raise ValueError("Dia inválido para o mês")
    return dia, mes

def eh_feriado_fixo(data: str) -> bool:
    _validar_data(data)
    return data in FERIADOS_FIXOS

def filtrar_feriados(datas: list[str]) -> list[str]:
    resultado = []
    for data in datas:
        try:
            if eh_feriado_fixo(data):
                resultado.append(data)
        except ValueError:
            continue
    return resultado

def mapear_erro_para_http(erro: Exception) -> tuple[int, str]:
    if not isinstance(erro, Exception):
        raise TypeError("Argumento deve ser uma exceção")

    mapeamento = {
        ValueError: (400, "Requisição inválida"),
        KeyError: (404, "Recurso não encontrado"),
        PermissionError: (403, "Acesso negado"),
        ConnectionError: (503, "Serviço indisponível"),
        TimeoutError: (504, "Tempo de espera esgotado"),
    }

    for tipo_erro, resposta in mapeamento.items():
        if isinstance(erro, tipo_erro):
            return resposta

    return (500, "Erro interno do servidor")

class InventarioArmazem:
    def __init__(self):
        self._estoque = {}

    def adicionar(self, sku: str, quantidade: int) -> None:
        if not isinstance(quantidade, int) or quantidade <= 0:
            raise ValueError("Quantidade deve ser um inteiro positivo")
        self._estoque[sku] = self._estoque.get(sku, 0) + quantidade

    def remover(self, sku: str, quantidade: int) -> None:
        if not isinstance(quantidade, int) or quantidade <= 0:
            raise ValueError("Quantidade deve ser um inteiro positivo")
        if sku not in self._estoque:
            raise KeyError(f"SKU '{sku}' não encontrado")
        if self._estoque[sku] < quantidade:
            raise KeyError(f"Estoque insuficiente para SKU '{sku}'")
        self._estoque[sku] -= quantidade
        if self._estoque[sku] == 0:
            del self._estoque[sku]

    def consultar(self, sku: str) -> int:
        return self._estoque.get(sku, 0)

    def listar_baixo_estoque(self, limite: int) -> list[str]:
        if not isinstance(limite, int) or limite <= 0:
            raise ValueError("Limite deve ser um inteiro positivo")
        return sorted([sku for sku, qtd in self._estoque.items() if qtd < limite])

class ReservaSala:
    def __init__(self):
        self._salas = {}

    def reservar(self, sala: str, inicio: int, fim: int) -> None:
        if inicio >= fim:
            raise ValueError("inicio deve ser menor que fim")
        if sala not in self._salas:
            self._salas[sala] = []
        for i, f in self._salas[sala]:
            if not (fim <= i or inicio >= f):
                raise ValueError("sobreposição de reserva")
        self._salas[sala].append((inicio, fim))
        self._salas[sala].sort()

    def listar(self, sala: str) -> list[tuple[int, int]]:
        return list(self._salas.get(sala, []))

    def livre(self, sala: str, inicio: int, fim: int) -> bool:
        if inicio >= fim:
            return False
        for i, f in self._salas.get(sala, []):
            if not (fim <= i or inicio >= f):
                return False
        return True

def calcular_tarifa(distancia_km: float, tempo_espera_min: int) -> float:
    if distancia_km < 0:
        raise ValueError("Distância não pode ser negativa")
    if tempo_espera_min < 0:
        raise ValueError("Tempo de espera não pode ser negativo")
    bandeirada = 5.0
    valor_km = 2.5
    valor_espera = 0.5
    return bandeirada + distancia_km * valor_km + tempo_espera_min * valor_espera

def validar_campo(nome, valor, obrigatorio, min_len, max_len):
    if obrigatorio and (valor is None or valor == ""):
        return False, f"Campo '{nome}' é obrigatório."
    if valor is None:
        return True, ""
    if not isinstance(valor, str):
        valor = str(valor)
    if len(valor) < min_len:
        return False, f"Campo '{nome}' deve ter pelo menos {min_len} caracteres."
    if len(valor) > max_len:
        return False, f"Campo '{nome}' deve ter no máximo {max_len} caracteres."
    return True, ""


def validar_formulario(dados, regras):
    resultado = {}
    for nome, regra in regras.items():
        obrigatorio, min_len, max_len = regra
        valor = dados.get(nome)
        resultado[nome] = validar_campo(nome, valor, obrigatorio, min_len, max_len)
    return resultado

def soma_multiplos_intervalo(inicio, fim, divisores):
    if inicio > fim:
        raise ValueError("inicio deve ser menor ou igual a fim")
    if not divisores:
        raise ValueError("divisores não pode ser vazio")
    if 0 in divisores:
        raise ValueError("divisores não pode conter zero")
    total = 0
    for n in range(inicio, fim + 1):
        for d in divisores:
            if n % d == 0:
                total += n
                break
    return total


def conta_multiplos_intervalo(inicio, fim, divisores):
    if inicio > fim:
        raise ValueError("inicio deve ser menor ou igual a fim")
    if not divisores:
        raise ValueError("divisores não pode ser vazio")
    if 0 in divisores:
        raise ValueError("divisores não pode conter zero")
    count = 0
    for n in range(inicio, fim + 1):
        for d in divisores:
            if n % d == 0:
                count += 1
                break
    return count

class LogAuditoria:
    def __init__(self):
        self._eventos = []

    def registrar(self, usuario: str, acao: str, recurso: str, timestamp: int) -> None:
        if not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError("timestamp deve ser inteiro não negativo")
        self._eventos.append({
            "usuario": usuario,
            "acao": acao,
            "recurso": recurso,
            "timestamp": timestamp
        })

    def consultar(self, usuario: str = None):
        if usuario is not None and not isinstance(usuario, str):
            raise TypeError("usuario deve ser string ou None")
        filtrados = [e for e in self._eventos if usuario is None or e["usuario"] == usuario]
        return sorted(filtrados, key=lambda e: e["timestamp"])

import math
from typing import Sequence, Union

Number = Union[int, float]
Point = Sequence[Number]

def _validar_ponto(p: Point, nome: str) -> None:
    if not isinstance(p, (list, tuple)):
        raise TypeError(f"{nome} deve ser uma lista ou tupla")
    if len(p) != 2:
        raise TypeError(f"{nome} deve ter exatamente 2 coordenadas")
    if not all(isinstance(coord, (int, float)) for coord in p):
        raise TypeError(f"Todas as coordenadas de {nome} devem ser números")

def distancia_manhattan(p1: Point, p2: Point) -> float:
    _validar_ponto(p1, "p1")
    _validar_ponto(p2, "p2")
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def distancia_euclidiana(p1: Point, p2: Point) -> float:
    _validar_ponto(p1, "p1")
    _validar_ponto(p2, "p2")
    dx = p1[0] - p2[0]
    dy = p1[1] - p2[1]
    return math.sqrt(dx * dx + dy * dy)

def converter_para_horario(minutos: int) -> str:
    if not isinstance(minutos, int):
        raise TypeError("minutos deve ser um inteiro")
    if minutos < -10080 or minutos > 10080:
        raise ValueError("minutos fora do intervalo permitido [-10080, 10080]")
    normalizado = minutos % 1440
    horas = normalizado // 60
    mins = normalizado % 60
    return f"{horas:02d}:{mins:02d}"

def perimetro_poligono(pontos):
    if len(pontos) < 4:
        raise ValueError("Polígono deve ter pelo menos 3 vértices distintos mais o fechamento")
    if pontos[0] != pontos[-1]:
        raise ValueError("Polígono deve ser fechado (primeiro e último pontos iguais)")
    perimetro = 0.0
    for i in range(len(pontos) - 1):
        x1, y1 = pontos[i]
        x2, y2 = pontos[i + 1]
        dx = x2 - x1
        dy = y2 - y1
        perimetro += (dx * dx + dy * dy) ** 0.5
    return perimetro


def area_poligono(pontos):
    if len(pontos) < 4:
        raise ValueError("Polígono deve ter pelo menos 3 vértices distintos mais o fechamento")
    if pontos[0] != pontos[-1]:
        raise ValueError("Polígono deve ser fechado (primeiro e último pontos iguais)")
    soma = 0.0
    for i in range(len(pontos) - 1):
        x1, y1 = pontos[i]
        x2, y2 = pontos[i + 1]
        soma += x1 * y2 - x2 * y1
    return abs(soma) / 2.0

class ProcessadorTexto:
    def __init__(self, separador: str):
        if not separador:
            raise ValueError("Separador não pode ser vazio")
        self._separador = separador
        self._buffer = ""

    def adicionar(self, texto: str) -> None:
        if self._buffer:
            self._buffer += self._separador + texto
        else:
            self._buffer = texto

    def resultado(self) -> str:
        return self._buffer

    def limpar(self) -> None:
        self._buffer = ""

def paridade(n: int) -> str:
    if not isinstance(n, int):
        raise ValueError("argumento deve ser int")
    return "par" if n % 2 == 0 else "impar"


def alternar(valores: list[int]) -> list[str]:
    if not isinstance(valores, list) or len(valores) == 0:
        raise ValueError("lista vazia ou invalida")
    for v in valores:
        if not isinstance(v, int):
            raise ValueError("todos os elementos devem ser int")
    resultado = []
    anterior = None
    for v in valores:
        p = paridade(v)
        if anterior is not None:
            if (anterior == "par" and p == "par") or (anterior == "impar" and p == "impar"):
                p = "impar" if p == "par" else "par"
        resultado.append(p)
        anterior = paridade(v)
    return resultado

from collections.abc import Iterable


def achatar(lista):
    if not isinstance(lista, list):
        raise TypeError("O argumento deve ser uma lista")
    resultado = []
    for item in lista:
        if isinstance(item, list):
            resultado.extend(achatar(item))
        else:
            resultado.append(item)
    return resultado


def achatar_iteravel(iteravel, atomicos=None):
    if atomicos is None:
        atomicos = {str, bytes, tuple}
    if not isinstance(atomicos, (set, frozenset)):
        raise TypeError("atomicos deve ser um set ou frozenset")
    try:
        iter(iteravel)
    except TypeError:
        raise TypeError("O primeiro argumento deve ser iterável")
    for item in iteravel:
        if isinstance(item, Iterable) and type(item) not in atomicos:
            yield from achatar_iteravel(item, atomicos)
        else:
            yield item

class Truncador:
    def __init__(self, max_chars: int, suffix: str = "..."):
        if max_chars <= 0:
            raise ValueError("max_chars deve ser maior que zero")
        if len(suffix) >= max_chars:
            raise ValueError("suffix deve ser menor que max_chars")
        self._max_chars = max_chars
        self._suffix = suffix
        self._total = 0

    def truncar(self, texto: str) -> str:
        self._total += 1
        if len(texto) <= self._max_chars:
            return texto
        limite = self._max_chars - len(self._suffix)
        return texto[:limite] + self._suffix

    def reset(self) -> None:
        self._total = 0

    @property
    def total_processados(self) -> int:
        return self._total

import math

def volume_solido(solido: str, *dimensoes: float) -> float:
    if solido == "cubo":
        if len(dimensoes) != 1:
            raise ValueError("Cubo requer exatamente 1 dimensão (aresta)")
        aresta = dimensoes[0]
        if aresta <= 0:
            raise ValueError("Dimensões devem ser positivas")
        return aresta ** 3
    elif solido == "paralelepipedo":
        if len(dimensoes) != 3:
            raise ValueError("Paralelepipedo requer exatamente 3 dimensões (comprimento, largura, altura)")
        comp, larg, alt = dimensoes
        if comp <= 0 or larg <= 0 or alt <= 0:
            raise ValueError("Dimensões devem ser positivas")
        return comp * larg * alt
    elif solido == "cilindro":
        if len(dimensoes) != 2:
            raise ValueError("Cilindro requer exatamente 2 dimensões (raio, altura)")
        raio, alt = dimensoes
        if raio <= 0 or alt <= 0:
            raise ValueError("Dimensões devem ser positivas")
        return math.pi * raio ** 2 * alt
    elif solido == "esfera":
        if len(dimensoes) != 1:
            raise ValueError("Esfera requer exatamente 1 dimensão (raio)")
        raio = dimensoes[0]
        if raio <= 0:
            raise ValueError("Dimensões devem ser positivas")
        return (4/3) * math.pi * raio ** 3
    elif solido == "cone":
        if len(dimensoes) != 2:
            raise ValueError("Cone requer exatamente 2 dimensões (raio, altura)")
        raio, alt = dimensoes
        if raio <= 0 or alt <= 0:
            raise ValueError("Dimensões devem ser positivas")
        return (1/3) * math.pi * raio ** 2 * alt
    elif solido == "piramide":
        if len(dimensoes) != 2:
            raise ValueError("Piramide requer exatamente 2 dimensões (area_base, altura)")
        area_base, alt = dimensoes
        if area_base <= 0 or alt <= 0:
            raise ValueError("Dimensões devem ser positivas")
        return (1/3) * area_base * alt
    else:
        raise ValueError(f"Sólido desconhecido: {solido}")

def mmc_mdc(a: int, b: int) -> tuple[int, int]:
    """Retorna (MMC, MDC) de dois inteiros positivos.

    Raises:
        ValueError: se a ou b não forem inteiros ou forem <= 0.
    """
    if not isinstance(a, int) or not isinstance(b, int):
        raise ValueError("Ambos os argumentos devem ser inteiros")
    if a <= 0 or b <= 0:
        raise ValueError("Ambos os argumentos devem ser positivos")

    def mdc(x: int, y: int) -> int:
        while y:
            x, y = y, x % y
        return x

    g = mdc(a, b)
    l = a // g * b
    return (l, g)

def movimentos_permitidos(posicao, cor, dama=False, tamanho=8):
    linha, coluna = posicao
    if tamanho < 2:
        raise ValueError("Tamanho do tabuleiro deve ser pelo menos 2")
    if not (0 <= linha < tamanho and 0 <= coluna < tamanho):
        raise ValueError("Posição fora do tabuleiro")
    if cor not in ('branca', 'preta'):
        raise ValueError("Cor deve ser 'branca' ou 'preta'")

    direcoes = []
    if dama:
        direcoes = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
    else:
        if cor == 'branca':
            direcoes = [(-1, -1), (-1, 1)]
        else:
            direcoes = [(1, -1), (1, 1)]

    movimentos = []
    for dl, dc in direcoes:
        nl, nc = linha + dl, coluna + dc
        if 0 <= nl < tamanho and 0 <= nc < tamanho:
            movimentos.append((nl, nc))
    return movimentos

class TrianguloPascal:
    def __init__(self):
        self._linhas = [[1]]

    def proxima_linha(self):
        ultima = self._linhas[-1]
        nova = [1]
        for i in range(len(ultima) - 1):
            nova.append(ultima[i] + ultima[i + 1])
        nova.append(1)
        self._linhas.append(nova)
        return nova

    def obter_linha(self, n):
        if n < 0 or n >= len(self._linhas):
            raise ValueError("linha fora do intervalo gerado")
        return self._linhas[n]

from decimal import Decimal, ROUND_HALF_UP
from typing import Union


class Formatador:
    def __init__(self):
        self.resetar()

    def configurar(self, locale: str, moeda: str, casas_decimais: int, separador_milhar: str, separador_decimal: str) -> None:
        if not isinstance(locale, str) or not locale:
            raise ValueError("locale deve ser string não vazia")
        if not isinstance(moeda, str) or len(moeda) != 3:
            raise ValueError("moeda deve ser string de 3 caracteres")
        if not isinstance(casas_decimais, int) or not (0 <= casas_decimais <= 10):
            raise ValueError("casas_decimais deve ser inteiro entre 0 e 10")
        if not isinstance(separador_milhar, str) or len(separador_milhar) != 1:
            raise ValueError("separador_milhar deve ser string de 1 caractere")
        if not isinstance(separador_decimal, str) or len(separador_decimal) != 1:
            raise ValueError("separador_decimal deve ser string de 1 caractere")
        if separador_milhar == separador_decimal:
            raise ValueError("separadores devem ser distintos")

        self._locale = locale
        self._moeda = moeda
        self._casas_decimais = casas_decimais
        self._sep_milhar = separador_milhar
        self._sep_decimal = separador_decimal

    def formatar_numero(self, valor: Union[int, float, Decimal]) -> str:
        if not isinstance(valor, (int, float, Decimal)):
            raise TypeError("valor deve ser int, float ou Decimal")

        if isinstance(valor, float):
            valor = Decimal(str(valor))
        elif isinstance(valor, int):
            valor = Decimal(valor)

        quantizador = Decimal('1') / (Decimal('10') ** self._casas_decimais)
        valor = valor.quantize(quantizador, rounding=ROUND_HALF_UP)

        sinal = '-' if valor < 0 else ''
        valor_abs = abs(valor)

        parte_inteira = str(int(valor_abs))
        parte_decimal = ''

        if self._casas_decimais > 0:
            escala = 10 ** self._casas_decimais
            dec = int((valor_abs * escala) % escala)
            parte_decimal = str(dec).zfill(self._casas_decimais)

        partes_inteira = []
        for i, ch in enumerate(reversed(parte_inteira)):
            if i and i % 3 == 0:
                partes_inteira.append(self._sep_milhar)
            partes_inteira.append(ch)
        parte_inteira_fmt = ''.join(reversed(partes_inteira))

        if parte_decimal:
            return f"{sinal}{parte_inteira_fmt}{self._sep_decimal}{parte_decimal}"
        return f"{sinal}{parte_inteira_fmt}"

    def formatar_moeda(self, valor: Union[int, float, Decimal]) -> str:
        num_fmt = self.formatar_numero(valor)
        return f"{self._moeda} {num_fmt}"

    def resetar(self) -> None:
        self._locale = 'pt_BR'
        self._moeda = 'BRL'
        self._casas_decimais = 2
        self._sep_milhar = '.'
        self._sep_decimal = ','

def negociar_conteudo(accept_header, disponiveis):
    """
    Negocia o tipo de conteúdo com base no cabeçalho Accept (RFC 7231).

    Parâmetros:
        accept_header (str): Valor do cabeçalho Accept.
        disponiveis (list[str]): Lista de tipos MIME disponíveis no servidor.

    Retorna:
        str: Tipo MIME escolhido.

    Levanta:
