    for idx, entrada in enumerate(entradas_brutas):
        if not entrada:
            raise ValueError("Entrada vazia no cabeçalho Accept")
        partes = [p.strip() for p in entrada.split(';')]
        media_range = partes[0]
        if not media_range:
            raise ValueError("Media range vazio")
        # Valida media range: type/subtype
