                raise ValueError(f"Parâmetro inválido: {param}")
            nome, valor = param.split('=', 1)
            nome = nome.strip()
            valor = valor.strip()
            if nome == 'q':
                try:
                    q_val = float(valor)
                except ValueError:
                    raise ValueError(f"q-value inválido: {valor}")
                if not (0.0 <= q_val <= 1.0):
                    raise ValueError(f"q-value fora do intervalo: {q_val}")
                q = q_val
            # outros parâmetros são ignorados

        entradas.append({
            'tipo': tipo,
            'subtipo': subtipo,
            'q': q,
            'ordem': idx
        })

    # Ordena entradas por q desc, especificidade desc, ordem asc
    def chave_ordenacao(e):
        tipo_especifico = 0 if e['tipo'] != '*' else 1
        subtipo_especifico = 0 if e['subtipo'] != '*' else 1
        return (-e['q'], tipo_especifico, subtipo_especifico, e['ordem'])

    entradas.sort(key=chave_ordenacao)

    # Para cada entrada, procura o primeiro disponível que case
    for entrada in entradas:
        for disp in disponiveis:
            if _casa(entrada['tipo'], entrada['subtipo'], disp):
                return disp

    raise ValueError("Nenhum tipo aceitável disponível")


def _token_valido(token):
    """Verifica se token é um token HTTP válido (RFC 7230)."""
    if not token:
        return False
    for ch in token:
        # tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" / "." /
        #         "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
        if ch.isalnum():
            continue
        if ch in "!#$%&'*+-.^_`|~":
            continue
        return False
    return True


def _casa(tipo_pat, subtipo_pat, mime):
    """Verifica se o media range casa com o tipo MIME."""
    if mime.count('/') != 1:
        return False
    t, s = mime.split('/')
    if tipo_pat != '*' and tipo_pat != t:
        return False
    if subtipo_pat != '*' and subtipo_pat != s:
        return False
    return True

def parse_log_line(line: str):
    """Converte uma linha de log em (minuto, valor)."""
    if not isinstance(line, str):
        raise ValueError("Linha deve ser string")
    parts = line.strip().split()
    if len(parts) != 3:
        raise ValueError("Formato inválido: esperado 'YYYY-MM-DD HH:MM:SS value'")
    date_part, time_part, value_part = parts
    # valida data e hora básicas
    try:
        from datetime import datetime
        dt = datetime.strptime(f"{date_part} {time_part}", "%Y-%m-%d %H:%M:%S")
    except Exception:
        raise ValueError("Data/hora inválida")
    minute_key = dt.strftime("%Y-%m-%d %H:%M")
    try:
        value = float(value_part)
    except Exception:
        raise ValueError("Valor não numérico")
    return minute_key, value


def aggregate_by_minute(entries):
    """Agrega métricas por minuto: soma, contagem, min, max."""
    try:
        iterator = iter(entries)
    except TypeError:
        raise TypeError("Entrada deve ser iterável")
    result = {}
    for item in iterator:
        if not (isinstance(item, tuple) and len(item) == 2):
            continue
        minute, value = item
        if not isinstance(minute, str) or not isinstance(value, (int, float)):
            continue
        # valida formato do minuto
        try:
            from datetime import datetime
            datetime.strptime(minute, "%Y-%m-%d %H:%M")
        except Exception:
            continue
        if minute not in result:
            result[minute] = [0.0, 0, float('inf'), float('-inf')]
        agg = result[minute]
        agg[0] += float(value)
        agg[1] += 1
        if value < agg[2]:
            agg[2] = float(value)
        if value > agg[3]:
            agg[3] = float(value)
    # converte listas em tuplas
    return {k: (v[0], v[1], v[2], v[3]) for k, v in result.items()}

def agrupar_sessoes(timestamps, limiar):
    if limiar <= 0:
        raise ValueError("Limiar deve ser positivo")
    if not timestamps:
        return []
    ordenados = sorted(timestamps)
    sessoes = [[ordenados[0]]]
    for ts in ordenados[1:]:
        if ts - sessoes[-1][-1] <= limiar:
            sessoes[-1].append(ts)
        else:
            sessoes.append([ts])
    return sessoes


def estatisticas_sessoes(sessoes):
    if not sessoes:
        raise ValueError("Lista de sessões vazia")
    total_sessoes = len(sessoes)
    total_eventos = sum(len(s) for s in sessoes)
    tamanhos = [len(s) for s in sessoes]
    return {
        'total_sessoes': total_sessoes,
        'total_eventos': total_eventos,
        'tamanho_medio': total_eventos / total_sessoes,
        'maior_sessao': max(tamanhos),
        'menor_sessao': min(tamanhos)
    }

def eh_primo(num: int) -> bool:
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True


def proximo_primo_em_primos_gemeos(n: int) -> int:
    if n < 2:
        raise ValueError("n deve ser >= 2")
    p = n + 1
    while True:
        if eh_primo(p) and eh_primo(p + 2):
            return p
        p += 1

def contar_digitos(numero):
    if not isinstance(numero, int):
        raise ValueError("O argumento deve ser um inteiro")
    if numero < 0:
        raise ValueError("O argumento não pode ser negativo")
    if numero == 0:
        return 1
    contador = 0
    while numero > 0:
        numero //= 10
        contador += 1
    return contador

class Desempenho:
    def __init__(self):
        self._notas = []

    def adicionar_nota(self, nota: float) -> None:
        if not (0 <= nota <= 100):
            raise ValueError("Nota deve estar entre 0 e 100")
        self._notas.append(float(nota))

    def media(self) -> float:
        if not self._notas:
            raise ValueError("Nenhuma nota registrada")
        return sum(self._notas) / len(self._notas)

    def maior_nota(self) -> float:
        if not self._notas:
            raise ValueError("Nenhuma nota registrada")
        return max(self._notas)

    def menor_nota(self) -> float:
        if not self._notas:
            raise ValueError("Nenhuma nota registrada")
        return min(self._notas)

    def quantidade_acima_da_media(self) -> int:
        if not self._notas:
            raise ValueError("Nenhuma nota registrada")
        m = self.media()
        return sum(1 for n in self._notas if n > m)

    def relatorio(self) -> str:
        if not self._notas:
            raise ValueError("Nenhuma nota registrada")
        m = self.media()
        maior = self.maior_nota()
        menor = self.menor_nota()
        acima = self.quantidade_acima_da_media()
        return (f"Notas: {len(self._notas)} | Média: {m:.2f} | Maior: {maior:.2f} | "
                f"Menor: {menor:.2f} | Acima da média: {acima}")

class Compra:
    def __init__(self, itens=None):
        self._itens = {}
        self._cupons = {}
        if itens:
            for nome, preco, qtd in itens:
                self.adicionar(nome, preco, qtd)

    def adicionar(self, nome, preco, qtd):
        if preco <= 0 or qtd <= 0:
            raise ValueError("preco e quantidade devem ser positivos")
        if nome in self._itens:
            _, qtd_atual = self._itens[nome]
            self._itens[nome] = (preco, qtd_atual + qtd)
        else:
            self._itens[nome] = (preco, qtd)

    def aplicar_cupom(self, codigo, tipo, valor):
        if codigo in self._cupons:
            raise ValueError("cupom duplicado")
        if tipo == "percentual":
            if not (0 < valor <= 100):
                raise ValueError("percentual invalido")
        elif tipo == "fixo":
            if valor <= 0:
                raise ValueError("valor fixo invalido")
        else:
            raise ValueError("tipo de cupom invalido")
        self._cupons[codigo] = (tipo, valor)

    def total(self):
        subtotal = sum(preco * qtd for preco, qtd in self._itens.values())
        for tipo, valor in self._cupons.values():
            if tipo == "percentual":
                subtotal *= (1 - valor / 100)
        for tipo, valor in self._cupons.values():
            if tipo == "fixo":
                subtotal -= valor
        return max(0.0, round(subtotal, 2))

class FiltroProdutos:
    def __init__(self, produtos):
        if not isinstance(produtos, list):
            raise TypeError("produtos deve ser uma lista")
        for p in produtos:
            if not isinstance(p, dict):
                raise ValueError("cada produto deve ser um dicionário")
            if not all(k in p for k in ("nome", "categoria", "preco")):
                raise ValueError("produto deve conter chaves 'nome', 'categoria' e 'preco'")
        self._produtos = produtos
        self._categoria = None
        self._preco_min = None
        self._preco_max = None
        self._substring = None

    def por_categoria(self, categoria):
        if isinstance(categoria, str):
            self._categoria = categoria
        return self

    def por_preco_min(self, valor):
        if isinstance(valor, (int, float)):
            self._preco_min = valor
        return self

    def por_preco_max(self, valor):
        if isinstance(valor, (int, float)):
            self._preco_max = valor
        return self

    def por_nome_contem(self, substring):
        if isinstance(substring, str):
            self._substring = substring.lower()
        return self

    def aplicar(self):
        resultado = []
        for p in self._produtos:
            if self._categoria is not None and p["categoria"] != self._categoria:
                continue
            if self._preco_min is not None and p["preco"] < self._preco_min:
                continue
            if self._preco_max is not None and p["preco"] > self._preco_max:
                continue
            if self._substring is not None and self._substring not in p["nome"].lower():
                continue
            resultado.append(p)
        return resultado

class Anotador:
    def __init__(self, texto: str):
        self._texto = texto
        self._anotacoes = []

    def adicionar(self, ini: int, fim: int, rotulo: str) -> None:
        if not (0 <= ini <= fim <= len(self._texto)):
            raise ValueError("Índices fora dos limites do texto")
        if not rotulo:
            raise ValueError("Rótulo não pode ser vazio")
        self._anotacoes.append((ini, fim, rotulo))

    def remover(self, indice: int) -> None:
        if not (0 <= indice < len(self._anotacoes)):
            raise IndexError("Índice de anotação inválido")
        del self._anotacoes[indice]

    def obter_anotacoes(self):
        return list(self._anotacoes)

class ContaBancaria:
    def __init__(self, titular: str, saldo_inicial: float = 0.0):
        self.titular = titular
        self._saldo = float(saldo_inicial)

    @property
    def saldo(self) -> float:
        return self._saldo

    def depositar(self, valor: float) -> None:
        if valor <= 0:
            raise ValueError("Valor de depósito deve ser positivo")
        self._saldo += valor

    def sacar(self, valor: float) -> None:
        if valor <= 0:
            raise ValueError("Valor de saque deve ser positivo")
        if valor > self._saldo:
            raise ValueError("Saldo insuficiente")
        self._saldo -= valor

def health_check(services):
    if not services:
        raise ValueError("services list cannot be empty")

    required_keys = {'name', 'failures', 'threshold'}
    result = []

    for svc in services:
        if not isinstance(svc, dict):
            raise ValueError("each service must be a dictionary")
        if not required_keys.issubset(svc.keys()):
            missing = required_keys - svc.keys()
            raise ValueError(f"service missing required keys: {missing}")

        name = svc['name']
        failures = svc['failures']
        threshold = svc['threshold']

        if not isinstance(name, str):
            raise ValueError("service name must be a string")
        if not isinstance(failures, int) or failures < 0:
            raise ValueError("failures must be a non-negative integer")
        if not isinstance(threshold, int) or threshold <= 0:
            raise ValueError("threshold must be a positive integer")

        if failures < threshold:
            status = 'healthy'
        elif failures == threshold:
            status = 'degraded'
        else:
            status = 'unhealthy'

        result.append((name, status))

    return result

class CompressorIntervalos:
    def __init__(self):
        self._numeros = set()

    def adicionar(self, numero):
        if not isinstance(numero, int):
            raise TypeError("O valor deve ser um inteiro")
        self._numeros.add(numero)

    def intervalos(self):
        if not self._numeros:
            return []
        ordenados = sorted(self._numeros)
        intervalos = []
        inicio = ordenados[0]
        fim = ordenados[0]
        for n in ordenados[1:]:
            if n == fim + 1:
                fim = n
            else:
                intervalos.append((inicio, fim))
                inicio = n
                fim = n
        intervalos.append((inicio, fim))
        return intervalos

    def reset(self):
        self._numeros.clear()

def construir_tabela(cabecalhos, linhas):
    if not cabecalhos:
        raise ValueError("Cabeçalhos não podem ser vazios")
    num_cols = len(cabecalhos)
    for i, linha in enumerate(linhas):
        if len(linha) != num_cols:
            raise ValueError(f"Linha {i} tem {len(linha)} colunas, esperado {num_cols}")

    todas_linhas = [cabecalhos] + linhas
    larguras = [max(len(str(celula)) for celula in col) for col in zip(*todas_linhas)]

    def formatar_linha(celulas):
        return "| " + " | ".join(str(c).ljust(larg) for c, larg in zip(celulas, larguras)) + " |"

    separador = "+" + "+".join("-" * (larg + 2) for larg in larguras) + "+"

    partes = [separador, formatar_linha(cabecalhos), separador]
    for linha in linhas:
        partes.append(formatar_linha(linha))
    partes.append(separador)

    return "\n".join(partes)


def formatar_relatorio(titulo, tabela):
    if not titulo or not titulo.strip():
        raise ValueError("Título não pode ser vazio")
    if not isinstance(tabela, str) or not tabela:
        raise ValueError("Tabela deve ser uma string não vazia")

    linha_sep = "=" * len(titulo)
    return f"{titulo}\n{linha_sep}\n{tabela}"

def formatar_documento(valor: str, mascara: str) -> str:
    if not valor.isdigit():
        raise ValueError("valor deve conter apenas dígitos")
    if '#' not in mascara:
        raise ValueError("mascara deve conter pelo menos um '#'")
    num_hash = mascara.count('#')
    if len(valor) < num_hash:
        valor = valor.zfill(num_hash)
    elif len(valor) > num_hash:
        valor = valor[-num_hash:]
    it = iter(valor)
    resultado = []
    for ch in mascara:
        if ch == '#':
            resultado.append(next(it))
        else:
            resultado.append(ch)
    return ''.join(resultado)

def mesclar_dicts(dicts):
    if not isinstance(dicts, list):
        raise TypeError("Esperava uma lista de dicionários")
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError("Todos os elementos devem ser dicionários")

    resultado = {}
    ocorrencias = {}

    for d in dicts:
        for chave, valor in d.items():
            if chave not in ocorrencias:
                ocorrencias[chave] = []
            ocorrencias[chave].append(valor)

    for chave, valores in ocorrencias.items():
        if len(valores) == 1:
            resultado[chave] = valores[0]
        else:
            resultado[chave] = valores

    return resultado

def achatar_dicionario(d: dict) -> dict:
    if not isinstance(d, dict):
        raise ValueError("Argumento deve ser um dicionário")

    resultado = {}

    def _achatar_atual(atual, prefixo=""):
        for chave, valor in atual.items():
            if not isinstance(chave, str):
                raise ValueError("Todas as chaves devem ser strings")

            nova_chave = f"{prefixo}.{chave}" if prefixo else chave

            if isinstance(valor, dict):
                _achatar_atual(valor, nova_chave)
            else:
                resultado[nova_chave] = valor

    _achatar_atual(d)
    return resultado

def carregar_configuracao(padrao: dict, arquivo: dict, ambiente: dict) -> dict:
    def _validar_fonte(fonte: dict, nome: str) -> None:
        if not isinstance(fonte, dict):
            raise TypeError(f"{nome} deve ser um dicionário")
        for chave, valor in fonte.items():
            if not isinstance(chave, str):
                raise TypeError(f"Chave {chave!r} em {nome} não é string")
            if not isinstance(valor, (str, int, bool)):
                raise TypeError(f"Valor {valor!r} para chave {chave!r} em {nome} tem tipo inválido")

    _validar_fonte(padrao, "padrao")
    _validar_fonte(arquivo, "arquivo")
    _validar_fonte(ambiente, "ambiente")

    resultado = {}
    resultado.update(padrao)
    resultado.update(arquivo)
    resultado.update(ambiente)
    return resultado

import math


class ConversorAngulos:
    def __init__(self, valor: float, unidade: str):
        if unidade == 'radianos':
            self._radianos = valor
        elif unidade == 'graus':
            self._radianos = math.radians(valor)
        else:
            raise ValueError("Unidade deve ser 'graus' ou 'radianos'")

    def para_graus(self) -> float:
        return math.degrees(self._radianos)

    def para_radianos(self) -> float:
        return self._radianos

    def normalizar(self) -> 'ConversorAngulos':
        self._radianos = self._radianos % (2 * math.pi)
        return self

    def adicionar(self, valor: float, unidade: str) -> 'ConversorAngulos':
        if unidade == 'radianos':
            self._radianos += valor
        elif unidade == 'graus':
            self._radianos += math.radians(valor)
        else:
            raise ValueError("Unidade deve ser 'graus' ou 'radianos'")
        return self

def gerar_progressao(inicio: float, razao: float, n: int) -> list[float]:
    """Gera os n primeiros termos de uma progressão aritmética."""
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n deve ser um inteiro positivo")
    return [inicio + i * razao for i in range(n)]


def soma_progressao(inicio: float, razao: float, n: int) -> float:
    """Calcula a soma dos n primeiros termos de uma progressão aritmética."""
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n deve ser um inteiro positivo")
    # Soma = n/2 * (2*inicio + (n-1)*razao)
    return n * (2 * inicio + (n - 1) * razao) / 2

class Quiz:
    def __init__(self, perguntas):
        self._mapa = {p: r for p, r in perguntas}
        self._acertos = 0
        self._erros = 0

    def responder(self, pergunta, resposta_usuario):
        if pergunta not in self._mapa:
            raise ValueError("Pergunta não encontrada")
        if resposta_usuario is None or resposta_usuario.strip() == "":
            raise ValueError("Resposta vazia")
        if resposta_usuario.strip().lower() == self._mapa[pergunta].strip().lower():
            self._acertos += 1
        else:
            self._erros += 1

    def pontuacao(self):
        return (self._acertos, self._erros)

class CalculadoraHistorico:
    def __init__(self):
        self._valor = 0.0
        self._historico = []

    def executar(self, operador: str, valor: float) -> float:
        if operador not in ('+', '-', '*', '/', '^'):
            raise ValueError(f"Operador inválido: {operador}")
        anterior = self._valor
        if operador == '+':
            self._valor = anterior + valor
        elif operador == '-':
            self._valor = anterior - valor
        elif operador == '*':
            self._valor = anterior * valor
        elif operador == '/':
            if valor == 0:
                raise ZeroDivisionError("Divisão por zero")
            self._valor = anterior / valor
        elif operador == '^':
            self._valor = anterior ** valor
        self._historico.append((operador, valor, anterior))
        return self._valor

    def desfazer(self) -> float:
        if not self._historico:
            raise IndexError("Nenhuma operação para desfazer")
        operador, valor, anterior = self._historico.pop()
        self._valor = anterior
        return self._valor

    def limpar(self) -> None:
        self._valor = 0.0
        self._historico.clear()

    @property
    def valor(self) -> float:
        return self._valor

    @property
    def historico(self) -> list:
        return list(self._historico)

def capitalizar_nomes(nomes: list[str]) -> list[str]:
    if not isinstance(nomes, list):
        raise TypeError("A entrada deve ser uma lista.")

    resultado = []
    for nome in nomes:
        if not isinstance(nome, str):
            raise TypeError("Todos os elementos da lista devem ser strings.")

        partes = nome.split()
        partes_capitalizadas = []
        for parte in partes:
            sub_partes = parte.split('-')
            sub_partes_capitalizadas = [sub.capitalize() for sub in sub_partes]
            partes_capitalizadas.append('-'.join(sub_partes_capitalizadas))

        resultado.append(' '.join(partes_capitalizadas))

    return resultado

def comprimento_lis(seq):
    if not isinstance(seq, list):
        raise ValueError("Entrada deve ser uma lista")
    if not all(isinstance(x, int) for x in seq):
        raise ValueError("Todos os elementos devem ser inteiros")
    n = len(seq)
    if n == 0:
        return 0
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if seq[j] < seq[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)

def reconstruir_lis(seq):
    if not isinstance(seq, list):
        raise ValueError("Entrada deve ser uma lista")
    if not all(isinstance(x, int) for x in seq):
        raise ValueError("Todos os elementos devem ser inteiros")
    n = len(seq)
    if n == 0:
        return []
    dp = [1] * n
    prev = [-1] * n
    for i in range(n):
        for j in range(i):
            if seq[j] < seq[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                prev[i] = j
    max_len = max(dp)
    idx = dp.index(max_len)
    lis = []
    while idx != -1:
        lis.append(seq[idx])
        idx = prev[idx]
    lis.reverse()
    return lis

def normalizar(texto, limite):
    if not isinstance(texto, str):
        raise ValueError("texto deve ser string")
    if not isinstance(limite, int) or limite <= 0:
        raise ValueError("limite deve ser inteiro positivo")

    limpo = ' '.join(texto.strip().split())
    resultado = limpo.lower()

    if len(resultado) > limite:
        if limite <= 3:
            resultado = resultado[:limite]
        else:
            resultado = resultado[:limite - 3] + "..."

    return resultado

class ContadorOcorrencias:
    def __init__(self):
        self._contagens = {}

    def adicionar(self, item: str) -> None:
        if not isinstance(item, str):
            raise TypeError("Item deve ser uma string")
        if not item:
            raise ValueError("Item não pode ser vazio")
        self._contagens[item] = self._contagens.get(item, 0) + 1

    def remover(self, item: str) -> None:
        if not isinstance(item, str):
            raise TypeError("Item deve ser uma string")
        if not item:
            raise ValueError("Item não pode ser vazio")
        if item not in self._contagens or self._contagens[item] == 0:
            raise ValueError("Item não encontrado ou contagem zero")
        self._contagens[item] -= 1
        if self._contagens[item] == 0:
            del self._contagens[item]

    def obter_contagem(self, item: str) -> int:
        if not isinstance(item, str):
            raise TypeError("Item deve ser uma string")
        return self._contagens.get(item, 0)

def intersecao_intervalos(intervalos):
    if not intervalos:
        raise ValueError("Lista de intervalos não pode ser vazia")

    max_inicio = None
    min_fim = None

    for intervalo in intervalos:
        if not isinstance(intervalo, tuple) or len(intervalo) != 2:
            raise ValueError("Cada intervalo deve ser uma tupla de dois inteiros")
        inicio, fim = intervalo
        if not isinstance(inicio, int) or not isinstance(fim, int):
            raise ValueError("Cada intervalo deve ser uma tupla de dois inteiros")
        if inicio > fim:
            raise ValueError("Início do intervalo não pode ser maior que o fim")

        if max_inicio is None or inicio > max_inicio:
            max_inicio = inicio
        if min_fim is None or fim < min_fim:
            min_fim = fim

    if max_inicio <= min_fim:
        return (max_inicio, min_fim)
    return None

class AnalisadorCaracteres:
