class Autocompletar:
    def __init__(self):
        self._raiz = {}
        self._fim = object()

    def inserir(self, palavra: str) -> None:
        if not isinstance(palavra, str) or palavra == "":
            raise ValueError("palavra deve ser string não vazia")
        no = self._raiz
        for ch in palavra:
            no = no.setdefault(ch, {})
        no[self._fim] = True

    def sugerir(self, prefixo: str) -> list[str]:
        if not isinstance(prefixo, str):
            raise ValueError("prefixo deve ser string")
        no = self._raiz
        for ch in prefixo:
            if ch not in no:
                return []
            no = no[ch]
        resultados = []
        def dfs(atual, caminho):
            if self._fim in atual:
                resultados.append("".join(caminho))
            for ch in sorted(atual.keys()):
                if ch is not self._fim:
                    dfs(atual[ch], caminho + [ch])
        dfs(no, list(prefixo))
        return resultados

class DeduplicadorRegistros:
    def __init__(self, chave, estrategia="primeiro"):
        if estrategia not in ("primeiro", "ultimo"):
            raise ValueError("Estratégia inválida")
        self._chave = chave
        self._estrategia = estrategia
        self._vistos = {}
        self._ordem = []

    def adicionar(self, registro):
        k = self._chave(registro)
        if k is None:
            raise ValueError("Chave não pode ser None")
        if self._estrategia == "primeiro":
            if k not in self._vistos:
                self._vistos[k] = registro
                self._ordem.append(k)
        else:
            if k in self._vistos:
                self._vistos[k] = registro
            else:
                self._vistos[k] = registro
                self._ordem.append(k)

    def resultado(self):
        return [self._vistos[k] for k in self._ordem]

