class EscalonadorIntervalo:
    def __init__(self, minimo: float, maximo: float):
        if minimo >= maximo:
            raise ValueError("minimo deve ser menor que maximo")
        self.minimo = minimo
        self.maximo = maximo

    def escalonar(self, valor: float, minimo_origem: float, maximo_origem: float) -> float:
        if minimo_origem == maximo_origem:
            raise ValueError("intervalo de origem nao pode ter amplitude zero")
        if valor < minimo_origem or valor > maximo_origem:
            raise ValueError("valor fora do intervalo de origem")
        proporcao = (valor - minimo_origem) / (maximo_origem - minimo_origem)
        return self.minimo + proporcao * (self.maximo - self.minimo)

class PoolRecursos:
    def __init__(self, capacidade: int, fabrica):
        if capacidade <= 0:
            raise ValueError("Capacidade deve ser positiva")
        if not callable(fabrica):
            raise ValueError("Fábrica deve ser callable")
        self._capacidade = capacidade
        self._fabrica = fabrica
        self._pool = []

    def acquire(self):
        if self._pool:
            return self._pool.pop()
        return self._fabrica()

    def release(self, recurso):
        if recurso is None:
            raise ValueError("Recurso não pode ser None")
        if len(self._pool) < self._capacidade:
            self._pool.append(recurso)

def converter_unidades(valor, unidade_origem, unidade_destino):
    unidades_validas = {'m', 'cm', 'mm'}
    if unidade_origem not in unidades_validas or unidade_destino not in unidades_validas:
        raise ValueError("Unidade inválida")
    if valor < 0:
        raise ValueError("Valor não pode ser negativo")

    fatores = {'m': 1.0, 'cm': 0.01, 'mm': 0.001}
    valor_em_metros = valor * fatores[unidade_origem]
    return valor_em_metros / fatores[unidade_destino]

class HistoricoNavegacao:
    def __init__(self):
        self._urls = []
        self._indice = -1

    def visitar(self, url: str) -> None:
        if self._indice < len(self._urls) - 1:
            self._urls = self._urls[:self._indice + 1]
        self._urls.append(url)
        self._indice = len(self._urls) - 1

    def voltar(self) -> str | None:
        if self._indice > 0:
            self._indice -= 1
            return self._urls[self._indice]
        return None

    def avancar(self) -> str | None:
        if self._indice < len(self._urls) - 1:
            self._indice += 1
            return self._urls[self._indice]
        return None

    def atual(self) -> str | None:
        if self._indice >= 0:
            return self._urls[self._indice]
        return None

def dia_da_semana(ano: int, mes: int, dia: int) -> str:
    if ano < 1:
        raise ValueError("Ano deve ser >= 1")
    if not 1 <= mes <= 12:
        raise ValueError("Mês deve estar entre 1 e 12")

    dias_por_mes = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    def eh_bissexto(a):
        return a % 4 == 0 and (a % 100 != 0 or a % 400 == 0)

    if mes == 2 and eh_bissexto(ano):
        max_dia = 29
    else:
        max_dia = dias_por_mes[mes - 1]

    if not 1 <= dia <= max_dia:
        raise ValueError("Dia inválido para o mês e ano")

    a = (14 - mes) // 12
    y = ano - a
    m = mes + 12 * a - 2
    d = (dia + y + y // 4 - y // 100 + y // 400 + (31 * m) // 12) % 7

    nomes = ["domingo", "segunda-feira", "terça-feira", "quarta-feira", "quinta-feira", "sexta-feira", "sábado"]
    return nomes[d]

def pontuacao_dardos(x, y):
    if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
        raise ValueError("Coordenadas devem ser números")
    distancia = (x ** 2 + y ** 2) ** 0.5
    if distancia <= 1:
        return 10
    if distancia <= 5:
        return 5
    if distancia <= 10:
        return 1
    return 0

def contar_intervalos(numeros: list[int]) -> dict[str, int]:
    if not numeros:
        raise ValueError("A lista não pode estar vazia")
    for n in numeros:
        if not isinstance(n, int):
            raise ValueError("Todos os elementos devem ser inteiros")
    contagem = {
        "negativos": 0,
        "zero": 0,
        "positivos_pares": 0,
        "positivos_impares": 0
    }
    for n in numeros:
        if n < 0:
            contagem["negativos"] += 1
        elif n == 0:
            contagem["zero"] += 1
        elif n % 2 == 0:
            contagem["positivos_pares"] += 1
        else:
            contagem["positivos_impares"] += 1
    return contagem

def soma_produto_digitos(n: int) -> tuple[int, int]:
    if not isinstance(n, int):
        raise ValueError("Argumento deve ser inteiro")
    if n < 0:
        raise ValueError("Argumento deve ser não-negativo")
    if n == 0:
        return (0, 0)
    s = 0
    p = 1
    while n:
        d = n % 10
        s += d
        p *= d
        n //= 10
    return (s, p)

import re


def extrair_social(texto: str) -> tuple[list[str], list[str]]:
    if not isinstance(texto, str):
        raise ValueError("O argumento deve ser uma string")

    hashtag_pattern = r'(?<!\S)#([A-Za-z][A-Za-z0-9_]*)(?!\S)'
    mention_pattern = r'(?<!\S)@([A-Za-z][A-Za-z0-9_]*)(?!\S)'

    hashtags = set(re.findall(hashtag_pattern, texto))
    mentions = set(re.findall(mention_pattern, texto))

    return (sorted(hashtags), sorted(mentions))

from math import gcd


def simplificar(fracao: tuple[int, int]) -> tuple[int, int]:
    """Retorna a fração irredutível equivalente com denominador positivo."""
    num, den = fracao
    if den == 0:
        raise ValueError("Denominador não pode ser zero")
    if num == 0:
        return (0, 1)
    d = gcd(abs(num), abs(den))
    num //= d
    den //= d
    if den < 0:
        num = -num
        den = -den
    return (num, den)


def somar(f1: tuple[int, int], f2: tuple[int, int]) -> tuple[int, int]:
    """Retorna a soma de duas frações, simplificada."""
    n1, d1 = f1
    n2, d2 = f2
    if d1 == 0 or d2 == 0:
        raise ValueError("Denominador não pode ser zero")
    num = n1 * d2 + n2 * d1
    den = d1 * d2
    return simplificar((num, den))

def zeros_fatorial(n: int) -> int:
    if not isinstance(n, int):
        raise ValueError("n deve ser um inteiro")
    if n < 0:
        raise ValueError("n deve ser não negativo")
    count = 0
    divisor = 5
    while divisor <= n:
        count += n // divisor
        divisor *= 5
    return count

def calcular_media(aluno: dict) -> float:
    if "notas" not in aluno:
        raise ValueError("Chave 'notas' ausente")
    notas = aluno["notas"]
    if not isinstance(notas, list):
        raise ValueError("'notas' deve ser uma lista")
    if not notas:
        raise ValueError("Lista de notas vazia")
    for n in notas:
        if not isinstance(n, (int, float)):
            raise ValueError("Notas devem ser numéricas")
        if n < 0 or n > 10:
            raise ValueError("Notas devem estar entre 0 e 10")
    media = sum(notas) / len(notas)
    return round(media, 1)


def classificar_aluno(aluno: dict) -> str:
    media = calcular_media(aluno)
    if media >= 7:
