    if media >= 5:
        return "Recuperação"
    return "Reprovado"

def gerenciar_fila(comandos):
    fila = []
    resultados = []
    for cmd in comandos:
        partes = cmd.strip().split()
        if not partes:
            raise ValueError("Comando inválido")
        acao = partes[0]
        if acao == "CHEGADA":
            if len(partes) < 2:
                raise ValueError("Comando inválido")
            nome = " ".join(partes[1:])
            fila.append(nome)
        elif acao == "ATENDIMENTO":
            if fila:
                resultados.append(fila.pop(0))
            else:
                resultados.append("Fila vazia")
        elif acao == "PROXIMO":
            if fila:
                resultados.append(fila[0])
            else:
                resultados.append("Fila vazia")
        elif acao == "TAMANHO":
            resultados.append(len(fila))
        else:
            raise ValueError("Comando inválido")
    return resultados

def parse_log(line: str) -> tuple[str, str]:
    if not isinstance(line, str):
        raise ValueError("Linha deve ser uma string")
    if ": " not in line:
        raise ValueError("Formato inválido: esperado 'LEVEL: mensagem'")
    level, msg = line.split(": ", 1)
    if not level:
        raise ValueError("Nível vazio")
    if not msg:
        raise ValueError("Mensagem vazia")
    return level, msg


def stats_by_level(entries: list[tuple[str, str]]) -> dict[str, dict[str, int | str]]:
    result: dict[str, dict[str, int | str]] = {}
    for level, msg in entries:
        if level not in result:
            result[level] = {"count": 0, "longest": ""}
        result[level]["count"] += 1
        if len(msg) > len(result[level]["longest"]):
            result[level]["longest"] = msg
    return result

import time
import uuid


class SessaoUsuario:
    def __init__(self):
        self._sessoes = {}

    def criar_sessao(self, usuario_id: str, duracao_segundos: int) -> str:
        if not usuario_id:
            raise ValueError("usuario_id não pode ser vazio ou nulo")
        if duracao_segundos <= 0:
            raise ValueError("duracao_segundos deve ser maior que zero")

        token = str(uuid.uuid4())
        expiracao = time.time() + duracao_segundos
        self._sessoes[token] = {
            "usuario_id": usuario_id,
            "expiracao": expiracao
        }
        return token

    def validar_sessao(self, token: str) -> str | None:
        if token not in self._sessoes:
            return None

        sessao = self._sessoes[token]
        if time.time() > sessao["expiracao"]:
            del self._sessoes[token]
            return None

        return sessao["usuario_id"]

class EditorTexto:
    def __init__(self):
        self._texto = ""
        self._historico_desfazer = []
        self._historico_refazer = []

    def digitar(self, texto: str) -> None:
        if not texto:
            return
        self._historico_desfazer.append(self._texto)
        self._texto += texto
        self._historico_refazer.clear()

    def desfazer(self) -> None:
        if not self._historico_desfazer:
            raise ValueError("Nada para desfazer")
        self._historico_refazer.append(self._texto)
        self._texto = self._historico_desfazer.pop()

    def refazer(self) -> None:
        if not self._historico_refazer:
            raise ValueError("Nada para refazer")
        self._historico_desfazer.append(self._texto)
        self._texto = self._historico_refazer.pop()

    def obter_texto(self) -> str:
        return self._texto

