class SistemaComentarios:
    def __init__(self):
        self._comentarios = {}
        self._proximo_id = 1

    def adicionar_comentario(self, texto: str, pai_id: int | None = None) -> int:
        texto_limpo = texto.strip()
        if not texto_limpo:
            raise ValueError("Texto do comentário não pode ser vazio.")

        if pai_id is not None and pai_id not in self._comentarios:
            raise ValueError("Comentário pai não encontrado.")

        comentario_id = self._proximo_id
        self._proximo_id += 1

        self._comentarios[comentario_id] = {
            "id": comentario_id,
            "texto": texto_limpo,
            "pai_id": pai_id,
            "filhos_ids": []
        }

        if pai_id is not None:
            self._comentarios[pai_id]["filhos_ids"].append(comentario_id)

        return comentario_id

    def remover_comentario(self, comentario_id: int) -> None:
        if comentario_id not in self._comentarios:
            raise ValueError("Comentário não encontrado.")

        ids_para_remover = self._coletar_ids_descendentes(comentario_id)
        ids_para_remover.add(comentario_id)

        for cid in ids_para_remover:
            comentario = self._comentarios[cid]
            pid = comentario["pai_id"]
            if pid is not None and pid in self._comentarios:
                if cid in self._comentarios[pid]["filhos_ids"]:
                    self._comentarios[pid]["filhos_ids"].remove(cid)
            del self._comentarios[cid]

    def _coletar_ids_descendentes(self, comentario_id: int) -> set[int]:
        descendentes = set()
        fila = [comentario_id]
        while fila:
            atual_id = fila.pop()
            filhos = self._comentarios[atual_id]["filhos_ids"]
            for filho_id in filhos:
                descendentes.add(filho_id)
                fila.append(filho_id)
        return descendentes

    def editar_comentario(self, comentario_id: int, novo_texto: str) -> None:
        if comentario_id not in self._comentarios:
            raise ValueError("Comentário não encontrado.")

        texto_limpo = novo_texto.strip()
        if not texto_limpo:
            raise ValueError("Texto do comentário não pode ser vazio.")

        self._comentarios[comentario_id]["texto"] = texto_limpo

    def listar_comentarios(self) -> list[str]:
        raizes = sorted(
            [c for c in self._comentarios.values() if c["pai_id"] is None],
            key=lambda c: c["id"]
        )
        resultado = []
        for raiz in raizes:
            self._dfs_listar(raiz["id"], 0, resultado)
        return resultado

    def _dfs_listar(self, comentario_id: int, profundidade: int, resultado: list[str]) -> None:
        comentario = self._comentarios[comentario_id]
        indentacao = "  " * profundidade
        resultado.append(f"{indentacao}{comentario['id']}: {comentario['texto']}")
        for filho_id in comentario["filhos_ids"]:
            self._dfs_listar(filho_id, profundidade + 1, resultado)

