class ArmstrongChecker:
    def __init__(self):
        self._history = []

    def is_armstrong(self, n):
        if not isinstance(n, int) or n < 0:
            raise ValueError("n deve ser um inteiro não-negativo")
        digits = [int(d) for d in str(n)]
        power = len(digits)
        total = sum(d ** power for d in digits)
        result = total == n
        self._history.append((n, result))
        return result

    def get_history(self):
        return list(self._history)

def separar_pares_impares(numeros):
    if not isinstance(numeros, list):
        raise TypeError("O argumento deve ser uma lista")
    for n in numeros:
        if not isinstance(n, int):
            raise TypeError("Todos os elementos devem ser inteiros")
    pares = [n for n in numeros if n % 2 == 0]
    impares = [n for n in numeros if n % 2 != 0]
    return (pares, impares)


def intercalar_listas(lista1, lista2):
    if not isinstance(lista1, list) or not isinstance(lista2, list):
        raise TypeError("Ambos os argumentos devem ser listas")
    for n in lista1:
        if not isinstance(n, int):
            raise TypeError("Todos os elementos devem ser inteiros")
    for n in lista2:
        if not isinstance(n, int):
            raise TypeError("Todos os elementos devem ser inteiros")
    resultado = []
    min_len = min(len(lista1), len(lista2))
    for i in range(min_len):
        resultado.append(lista1[i])
        resultado.append(lista2[i])
    if len(lista1) > min_len:
        resultado.extend(lista1[min_len:])
    elif len(lista2) > min_len:
        resultado.extend(lista2[min_len:])
    return resultado

def formatar_valor(valor, tipo):
    if not isinstance(valor, (int, float)):
        raise ValueError("valor deve ser numérico")
    if tipo == "moeda":
        return f"R$ {valor:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    elif tipo == "porcentagem":
        return f"{valor * 100:.2f}%".replace(".", ",")
    elif tipo == "cientifico":
        return f"{valor:.2e}".replace(".", ",")
    elif tipo == "inteiro":
        return str(int(round(valor)))
    else:
        raise ValueError("tipo inválido")

def percentil_latencia(latencias: list[float], percentil: float) -> float:
    """Retorna o valor do percentil solicitado usando interpolação linear."""
    if not latencias:
        raise ValueError("Lista de latências não pode ser vazia")
    if not (0 <= percentil <= 100):
        raise ValueError("Percentil deve estar entre 0 e 100")

    sorted_lat = sorted(latencias)
    n = len(sorted_lat)
    if n == 1:
        return sorted_lat[0]

    pos = (percentil / 100) * (n - 1)
    lower = int(pos)
    upper = lower + 1
    weight = pos - lower

    if upper >= n:
        return sorted_lat[-1]

    return sorted_lat[lower] * (1 - weight) + sorted_lat[upper] * weight


def resumo_percentis(latencias: list[float]) -> dict[str, float]:
    """Retorna dicionário com percentis padrão (p25, p50, p75, p90, p95, p99)."""
    percentis = [25, 50, 75, 90, 95, 99]
    return {f"p{p}": percentil_latencia(latencias, p) for p in percentis}

def top_n(itens, n):
    if not isinstance(n, int):
        raise TypeError("n deve ser um inteiro")
    try:
        iter(itens)
    except TypeError:
        raise TypeError("itens deve ser iterável")
    if n < 0:
        raise ValueError("n não pode ser negativo")
    lista = list(itens)
    if n > len(lista):
        raise ValueError("n não pode ser maior que o número de elementos")
    return sorted(lista, reverse=True)[:n]

def build_conditions(filters: dict) -> tuple[str, list]:
    """Constrói fragmento WHERE e parâmetros a partir de dicionário de filtros."""
    if not filters:
        return "", []

    operator_map = {
        "__eq": "=",
        "__ne": "!=",
        "__gt": ">",
        "__gte": ">=",
        "__lt": "<",
        "__lte": "<=",
        "__in": "IN",
        "__like": "LIKE",
        "__ilike": "ILIKE",
        "__is_null": "IS NULL",
        "__is_not_null": "IS NOT NULL",
    }

    fragments = []
    params = []

    for key, value in filters.items():
        matched_op = None
        column = key
        for op_suffix, sql_op in operator_map.items():
            if key.endswith(op_suffix):
                matched_op = op_suffix
                column = key[:-len(op_suffix)]
                break

        if matched_op is None:
            matched_op = "__eq"

        if matched_op in ("__is_null", "__is_not_null"):
            fragments.append(f"{column} {operator_map[matched_op]}")
            continue

        if value is None:
            continue

        if matched_op == "__in":
            if isinstance(value, str) or not hasattr(value, "__iter__"):
                raise ValueError("Operador __in requer um iterável não-string")
            value_list = list(value)
            if not value_list:
                raise ValueError("Operador __in requer iterável não vazio")
            placeholders = ", ".join(["?"] * len(value_list))
            fragments.append(f"{column} IN ({placeholders})")
            params.extend(value_list)
        elif matched_op in ("__like", "__ilike"):
            if not isinstance(value, str):
                raise ValueError(f"Operador {matched_op} requer string")
            fragments.append(f"{column} {operator_map[matched_op]} ?")
            params.append(value)
        else:
            fragments.append(f"{column} {operator_map[matched_op]} ?")
            params.append(value)

    sql_fragment = " AND ".join(fragments)
    return sql_fragment, params


def apply_conditions(base_query: str, conditions: tuple[str, list]) -> str:
    """Aplica fragmento WHERE à query base."""
    fragment, _ = conditions
    if not fragment:
        return base_query
    return f"{base_query} WHERE {fragment}"

def elementos_unicos(lista):
    if not isinstance(lista, list):
        raise TypeError("A entrada deve ser uma lista.")
    contagem = {}
    for item in lista:
        contagem[item] = contagem.get(item, 0) + 1
    return [item for item in lista if contagem[item] == 1]

