def diagonais(matriz):
    if not matriz:
        raise ValueError("matriz vazia")
    n = len(matriz)
    for linha in matriz:
        if len(linha) != n:
            raise ValueError("matriz nao quadrada")
    principal = [matriz[i][i] for i in range(n)]
    secundaria = [matriz[i][n - 1 - i] for i in range(n)]
    return (principal, secundaria)

class FreteDistancia:
    def __init__(self, taxa_por_km: float, distancia_minima_gratis: int):
        if taxa_por_km <= 0:
            raise ValueError("taxa_por_km deve ser maior que zero")
        if distancia_minima_gratis < 0:
            raise ValueError("distancia_minima_gratis nao pode ser negativa")
        self._taxa_por_km = taxa_por_km
        self._distancia_minima_gratis = distancia_minima_gratis

    def calcular(self, valor_pedido: float, distancia_km: int) -> float:
        if valor_pedido < 0:
            raise ValueError("valor_pedido nao pode ser negativo")
        if distancia_km < 0:
            raise ValueError("distancia_km nao pode ser negativa")
        if distancia_km <= self._distancia_minima_gratis:
            return 0.0
        frete = (distancia_km - self._distancia_minima_gratis) * self._taxa_por_km
        return min(frete, valor_pedido)

def construir_indice(texto):
    if not isinstance(texto, str):
        raise TypeError("O texto deve ser uma string")
    if not texto.strip():
        return {}

    import string
    palavras = texto.split()
    indice = {}

    for pos, palavra in enumerate(palavras):
        normalizada = palavra.strip(string.punctuation).lower()
        if normalizada:
            if normalizada not in indice:
                indice[normalizada] = []
            indice[normalizada].append(pos)

    return indice

