def soma_divisores_propios(n: int) -> int:
    """Retorna a soma dos divisores próprios de n (excluindo n).
    Levanta ValueError se n não for inteiro positivo.
    """
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n deve ser inteiro positivo")
    if n == 1:
        return 0
    soma = 1
    limite = int(n ** 0.5)
    for d in range(2, limite + 1):
        if n % d == 0:
            soma += d
            outro = n // d
            if outro != d:
                soma += outro
    return soma


def sao_amigos(a: int, b: int) -> bool:
    """Retorna True se a e b formam um par de números amigos.
    Números amigos: a != b, soma_divisores_propios(a) == b e soma_divisores_propios(b) == a.
    Levanta ValueError se a ou b não forem inteiros positivos.
    """
    if not isinstance(a, int) or a <= 0:
        raise ValueError("a deve ser inteiro positivo")
    if not isinstance(b, int) or b <= 0:
        raise ValueError("b deve ser inteiro positivo")
    if a == b:
        return False
    return soma_divisores_propios(a) == b and soma_divisores_propios(b) == a

class AnalisadorCabecalhosHTTP:
