        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        "!#$%&'*+-.^_`|~"
    )

    def __init__(self):
        self._headers = []  # list of (original_name, value)

    def adicionar(self, nome: str, valor: str) -> None:
        if not nome:
            raise ValueError("Nome do cabeçalho não pode ser vazio")
        if not all(c in self._TOKEN_CHARS for c in nome):
            raise ValueError(f"Nome do cabeçalho inválido: {nome!r}")
        if any(ord(c) < 32 and c not in (' ', '\t') for c in valor):
            raise ValueError(f"Valor do cabeçalho contém caractere de controle inválido: {valor!r}")
        self._headers.append((nome, valor))

    def obter_todos(self, nome: str) -> list[str]:
        nome_lower = nome.lower()
        return [v for n, v in self._headers if n.lower() == nome_lower]

    def obter_primeiro(self, nome: str) -> str | None:
        nome_lower = nome.lower()
        for n, v in self._headers:
            if n.lower() == nome_lower:
                return v
        return None

    def serializar(self) -> str:
        return ''.join(f"{n}: {v}\r\n" for n, v in self._headers)

