import re
from typing import Tuple

_VERSION_RE = re.compile(r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$")

def parse_version(version_str: str) -> Tuple[int, int, int]:
    """Parse a semantic version string into a (major, minor, patch) tuple."""
    if not isinstance(version_str, str):
        raise ValueError("Version must be a string")
    m = _VERSION_RE.match(version_str.strip())
    if not m:
        raise ValueError(f"Invalid version format: {version_str!r}")
    major, minor, patch = map(int, m.groups())
    return (major, minor, patch)


def _parse_range(range_str: str):
    """Parse a range string into a structured representation."""
    if not isinstance(range_str, str):
        raise ValueError("Range must be a string")
    s = range_str.strip()
    if not s:
        raise ValueError("Empty range")

    # Hyphen range: "1.0.0-2.0.0"
    if "-" in s and not s.startswith(("<", ">", "=", "!", "^", "~")):
        parts = s.split("-", 1)
        if len(parts) != 2:
            raise ValueError(f"Invalid hyphen range: {range_str!r}")
        low = parse_version(parts[0].strip())
        high = parse_version(parts[1].strip())
        return ("hyphen", low, high)

    # Caret: ^1.2.3
    if s.startswith("^"):
        ver = parse_version(s[1:].strip())
        return ("caret", ver)

    # Tilde: ~1.2.3
    if s.startswith("~"):
        ver = parse_version(s[1:].strip())
        return ("tilde", ver)

    # Comparison operators
    for op in (">=", "<=", "==", "!=", ">", "<"):
        if s.startswith(op):
            ver = parse_version(s[len(op):].strip())
            return ("comp", op, ver)

    raise ValueError(f"Unrecognized range format: {range_str!r}")


def satisfies(version_str: str, range_str: str) -> bool:
    """Check if a version satisfies a range specification."""
    version = parse_version(version_str)
    kind = _parse_range(range_str)

    if kind[0] == "comp":
        _, op, other = kind
        if op == ">":
            return version > other
        if op == ">=":
            return version >= other
        if op == "<":
            return version < other
        if op == "<=":
            return version <= other
        if op == "==":
            return version == other
        if op == "!=":
            return version != other

    if kind[0] == "hyphen":
        _, low, high = kind
        return low <= version <= high

    if kind[0] == "caret":
        _, base = kind
        bm, bn, bp = base
        vm, vn, vp = version
        if bm == 0:
            # 0.x.y -> only patch changes allowed if minor same, else minor locked? Actually spec: ^0.y.z allows changes that don't modify left-most non-zero digit.
            # Common semver: ^0.2.3 := >=0.2.3 <0.3.0 ; ^0.0.3 := >=0.0.3 <0.0.4
            if bn == 0:
                return version >= base and vm == 0 and vn == 0 and vp >= bp
            else:
                return version >= base and vm == 0 and vn == bn
        else:
            # ^1.2.3 := >=1.2.3 <2.0.0
            return version >= base and vm == bm

    if kind[0] == "tilde":
        _, base = kind
        bm, bn, bp = base
        vm, vn, vp = version
        # ~1.2.3 := >=1.2.3 <1.3.0
        return version >= base and vm == bm and vn == bn

    raise ValueError("Internal error: unknown range kind")

def soma_sequencia_aritmetica(inicio, diferenca, n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n deve ser um inteiro positivo")
    if not isinstance(inicio, (int, float)) or not isinstance(diferenca, (int, float)):
        raise ValueError("inicio e diferenca devem ser números")
    total = n * (2 * inicio + (n - 1) * diferenca) / 2
    return int(total) if total == int(total) else total

def gerar_relatorio_uso(registros):
    if not isinstance(registros, list):
        raise ValueError("A entrada deve ser uma lista")

    resultado = {}

    for registro in registros:
        if not isinstance(registro, dict):
            continue

        cliente_id = registro.get("cliente_id")
        mes = registro.get("mes")
        quantidade = registro.get("quantidade")

        if not isinstance(cliente_id, int) or cliente_id <= 0:
            continue
        if not isinstance(mes, str) or len(mes) != 7 or mes[4] != '-' or not mes[:4].isdigit() or not mes[5:].isdigit():
            continue
        if not isinstance(quantidade, int) or quantidade < 0:
            continue

        chave = (cliente_id, mes)
        resultado[chave] = resultado.get(chave, 0) + quantidade

    return resultado

def extrair_nome_arquivo(caminho: str) -> str:
    if not caminho or caminho.endswith(("/", "\\")):
        raise ValueError("Caminho inválido")
    # Obtém a parte após o último separador
    nome_com_ext = caminho.replace("\\", "/").split("/")[-1]
    if "." not in nome_com_ext:
        return nome_com_ext
    # Separa no último ponto
    return nome_com_ext.rsplit(".", 1)[0]


def extrair_extensao(caminho: str) -> str:
    if not caminho or caminho.endswith(("/", "\\")):
        raise ValueError("Caminho inválido")
    nome_com_ext = caminho.replace("\\", "/").split("/")[-1]
    if "." not in nome_com_ext:
        return ""
    return nome_com_ext.rsplit(".", 1)[1]

def converter_base_num(valor: str, origem: int, destino: int) -> str:
    if not isinstance(valor, str):
        raise ValueError("valor deve ser string")
    if not (2 <= origem <= 36):
        raise ValueError("base origem deve estar entre 2 e 36")
    if not (2 <= destino <= 36):
        raise ValueError("base destino deve estar entre 2 e 36")
    if valor == "":
        raise ValueError("valor não pode ser vazio")

    digitos = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    valor_upper = valor.upper()

    # Valida caracteres e converte para decimal
    decimal = 0
    for ch in valor_upper:
        if ch not in digitos[:origem]:
            raise ValueError(f"caractere inválido '{ch}' para base {origem}")
        decimal = decimal * origem + digitos.index(ch)

    # Converte decimal para base destino
    if decimal == 0:
        return "0"

    resultado = []
    while decimal > 0:
        decimal, resto = divmod(decimal, destino)
        resultado.append(digitos[resto])

    return "".join(reversed(resultado))

def gerenciar_tarefas(tarefas, comando, argumento=None):
    concluidas = []

    def _processar(lista_tarefas, cmd, arg):
        nonlocal concluidas
        if cmd == "adicionar":
            if not arg or not arg.strip():
                raise ValueError("Tarefa não pode ser vazia")
            lista_tarefas.append(arg.strip())
            return lista_tarefas[:]
        elif cmd == "remover":
            if arg not in lista_tarefas:
                raise ValueError("Tarefa não encontrada")
            lista_tarefas.remove(arg)
            return lista_tarefas[:]
        elif cmd == "concluir":
            if arg not in lista_tarefas:
                raise ValueError("Tarefa não encontrada")
            lista_tarefas.remove(arg)
            concluidas.append(arg)
            return lista_tarefas[:]
        elif cmd == "listar":
            return lista_tarefas[:]
        elif cmd == "listar_concluidas":
            return concluidas[:]
        else:
            raise ValueError("Comando inválido")

    return _processar(tarefas[:], comando, argumento)

class DeduplicadorOrdenado:
