def calcular_espera(tentativa: int, base: float, fator: float) -> float:
    if tentativa < 1:
        raise ValueError("tentativa deve ser >= 1")
    if base < 0:
        raise ValueError("base deve ser >= 0")
    if fator <= 0:
        raise ValueError("fator deve ser > 0")
    return base * (fator ** (tentativa - 1))

def uniao_intervalos(intervalos):
    if not isinstance(intervalos, list):
        raise ValueError("A entrada deve ser uma lista")

    intervalos_normalizados = []
    for i, item in enumerate(intervalos):
        if not isinstance(item, (list, tuple)):
            raise ValueError(f"Intervalo no índice {i} não é lista ou tupla")
        if len(item) != 2:
            raise ValueError(f"Intervalo no índice {i} não tem tamanho 2")
        inicio, fim = item
        if not isinstance(inicio, int) or not isinstance(fim, int):
            raise ValueError(f"Intervalo no índice {i} deve conter inteiros")
        if inicio > fim:
            raise ValueError(f"Intervalo no índice {i} tem início maior que fim")
        intervalos_normalizados.append([inicio, fim])

    if not intervalos_normalizados:
        return []

    intervalos_normalizados.sort(key=lambda x: x[0])

    resultado = [intervalos_normalizados[0]]
    for atual in intervalos_normalizados[1:]:
        ultimo = resultado[-1]
        if atual[0] <= ultimo[1] + 1:
            ultimo[1] = max(ultimo[1], atual[1])
        else:
            resultado.append(atual)

    return resultado

def classificar_ph(ph):
    if not isinstance(ph, (int, float)):
        raise ValueError("pH deve ser um número")
    if isinstance(ph, float) and ph != ph:
        raise ValueError("pH não pode ser NaN")
    if ph < 0 or ph > 14:
        raise ValueError("pH deve estar entre 0 e 14")
    if ph < 3:
        return "Ácido forte"
    elif ph < 7:
        return "Ácido fraco"
    elif ph == 7:
        return "Neutro"
    elif ph <= 10:
        return "Base fraca"
    else:
        return "Base forte"

def luhn_checksum(digits: str) -> int:
    if not digits:
        raise ValueError("input must not be empty")
    if not digits.isdigit():
        raise ValueError("input must contain only digits")
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            total += d
        else:
            doubled = d * 2
            total += doubled - 9 if doubled > 9 else doubled
    return (10 - (total % 10)) % 10

def proximo_primo(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("n deve ser um inteiro não negativo")
    def eh_primo(k):
        if k < 2:
            return False
        if k % 2 == 0:
            return k == 2
        i = 3
        while i * i <= k:
            if k % i == 0:
                return False
            i += 2
        return True
    candidato = n + 1
    while True:
        if eh_primo(candidato):
            return candidato
        candidato += 1

def proximo_triangular(n: int) -> int:
    if not isinstance(n, int):
        raise ValueError("n deve ser um inteiro")
    if n < 0:
        raise ValueError("n deve ser não negativo")

    k = 1
    while True:
        triangular = k * (k + 1) // 2
        if triangular > n:
            return triangular
        k += 1


def eh_quadrado_perfeito(n: int) -> bool:
    if not isinstance(n, int):
        raise ValueError("n deve ser um inteiro")
    if n < 0:
        raise ValueError("n deve ser não negativo")

    if n == 0:
        return True

    raiz = int(n ** 0.5)
    return raiz * raiz == n

def media_ponderada(valores, pesos):
    if len(valores) != len(pesos):
        raise ValueError("Listas devem ter o mesmo tamanho")
    if not valores:
        raise ValueError("Listas não podem ser vazias")
    if any(p < 0 for p in pesos):
        raise ValueError("Pesos não podem ser negativos")
    soma_pesos = sum(pesos)
    if soma_pesos == 0:
        raise ValueError("Soma dos pesos não pode ser zero")
    soma_produtos = sum(v * p for v, p in zip(valores, pesos))
    return soma_produtos / soma_pesos

import unicodedata

def _normalizar(texto: str) -> str:
    return unicodedata.normalize('NFKD', texto).encode('ascii', 'ignore').decode('ascii')

def _partes_validas(nome: str):
    partes = [_normalizar(p) for p in nome.strip().split()]
    validas = [p for p in partes if len(p) >= 3]
    if not validas:
        raise ValueError("Nome deve conter pelo menos uma parte com 3 ou mais caracteres")
    return validas

def abreviar_nome(nome: str) -> str:
    validas = _partes_validas(nome)
    primeiro = validas[0].capitalize()
    if len(validas) == 1:
        return primeiro
    iniciais = ' '.join(f'{p[0].upper()}.' for p in validas[1:])
    return f'{primeiro} {iniciais}'

def gerar_iniciais(nome: str) -> str:
    validas = _partes_validas(nome)
    return ' '.join(f'{p[0].upper()}.' for p in validas)

def _mdc(a: int, b: int) -> int:
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a


def somar_fracao(f1: tuple[int, int], f2: tuple[int, int]) -> tuple[int, int]:
    for fracao in (f1, f2):
        if not isinstance(fracao, tuple) or len(fracao) != 2:
            raise TypeError("A fração deve ser uma tupla de dois inteiros")
        num, den = fracao
        if not isinstance(num, int) or not isinstance(den, int):
            raise TypeError("Numerador e denominador devem ser inteiros")
        if den == 0:
            raise ValueError("Denominador não pode ser zero")

    n1, d1 = f1
    n2, d2 = f2

    num = n1 * d2 + n2 * d1
    den = d1 * d2

    if den < 0:
        num, den = -num, -den

    divisor = _mdc(num, den)
    return (num // divisor, den // divisor)

def frequencia_itens(iteravel):
    try:
        iter(iteravel)
    except TypeError:
        raise TypeError("O argumento deve ser iterável")

    contagem = {}
    for item in iteravel:
        try:
            hash(item)
        except TypeError:
            continue
        contagem[item] = contagem.get(item, 0) + 1
    return contagem

def calcular_boletim(notas, pesos):
    if len(notas) != len(pesos):
        raise ValueError("Listas devem ter o mesmo tamanho")
    if not notas:
        raise ValueError("Listas não podem ser vazias")
    for n in notas:
        if n < 0:
            raise ValueError("Notas não podem ser negativas")
    for p in pesos:
        if p <= 0:
            raise ValueError("Pesos devem ser positivos")
    soma_ponderada = sum(n * p for n, p in zip(notas, pesos))
    soma_pesos = sum(pesos)
    media = soma_ponderada / soma_pesos
    if media >= 7.0:
        conceito = 'A'
        aprovado = True
    elif media >= 5.0:
        conceito = 'B'
        aprovado = True
    elif media >= 3.0:
        conceito = 'C'
        aprovado = False
    else:
        conceito = 'D'
        aprovado = False
    return {'media': media, 'aprovado': aprovado, 'conceito': conceito}

