import math

def medidas_poligono_regular(num_lados: int, lado: float) -> tuple[float, float]:
    if num_lados < 3:
        raise ValueError("Número de lados deve ser >= 3")
    if lado <= 0:
        raise ValueError("Comprimento do lado deve ser > 0")
    perimetro = num_lados * lado
    area = (num_lados * lado ** 2) / (4 * math.tan(math.pi / num_lados))
    return (perimetro, area)

def converter_horario(horario: str, deslocamento: int) -> str:
    if not isinstance(horario, str):
        raise ValueError("Horário deve ser uma string")
    partes = horario.split(":")
    if len(partes) != 2:
        raise ValueError("Formato de horário inválido")
    try:
        hora = int(partes[0])
        minuto = int(partes[1])
    except ValueError:
        raise ValueError("Hora e minuto devem ser números inteiros")
    if not (0 <= hora <= 23):
        raise ValueError("Hora deve estar entre 0 e 23")
    if not (0 <= minuto <= 59):
        raise ValueError("Minuto deve estar entre 0 e 59")
    total_minutos = hora * 60 + minuto + deslocamento * 60
    total_minutos %= 24 * 60
    nova_hora = total_minutos // 60
    novo_minuto = total_minutos % 60
    return f"{nova_hora:02d}:{novo_minuto:02d}"

