MOEDAS = {'BRL', 'USD', 'EUR'}

def taxa_cambio(origem: str, destino: str) -> float:
    o = origem.upper()
    d = destino.upper()
    if o not in MOEDAS:
        raise ValueError(f'Moeda não suportada: {o}')
    if d not in MOEDAS:
        raise ValueError(f'Moeda não suportada: {d}')
    if o == d:
        raise ValueError('Origem e destino devem ser diferentes')
    return TABELA[(o, d)]

def converter(valor: float, origem: str, destino: str) -> float:
    return round(valor * taxa_cambio(origem, destino), 2)

def analise_numeros(numeros: list) -> dict:
    if not numeros:
        raise ValueError("A lista não pode estar vazia")

    for n in numeros:
        if isinstance(n, bool) or not isinstance(n, (int, float)):
            raise TypeError("Todos os elementos devem ser números (int ou float)")

    soma_positivos = sum(n for n in numeros if n > 0)
    contagem_negativos = sum(1 for n in numeros if n < 0)
    media_absolutos = sum(abs(n) for n in numeros) / len(numeros)

    return {
        "soma_positivos": soma_positivos,
        "contagem_negativos": contagem_negativos,
        "media_absolutos": media_absolutos
    }

def deduplicar_eventos(eventos, janela_segundos):
    if janela_segundos <= 0:
        raise ValueError("janela_segundos deve ser positivo")
    if not isinstance(eventos, list):
        raise ValueError("eventos deve ser uma lista")

    resultado = []
    ultimos_timestamps = {}

    for evento in eventos:
        if not isinstance(evento, dict):
            raise ValueError("cada evento deve ser um dicionário")
        if 'id' not in evento or 'timestamp' not in evento:
            raise ValueError("evento deve conter chaves 'id' e 'timestamp'")

        id_evento = evento['id']
        timestamp = evento['timestamp']

        if not isinstance(id_evento, str):
            raise ValueError("id do evento deve ser string")
        if not isinstance(timestamp, (int, float)):
            raise ValueError("timestamp deve ser numérico")
        if timestamp < 0:
            raise ValueError("timestamp não pode ser negativo")

        if id_evento not in ultimos_timestamps or timestamp - ultimos_timestamps[id_evento] >= janela_segundos:
            resultado.append(evento)
            ultimos_timestamps[id_evento] = timestamp

    return resultado

def remover_duplicados_por_chave(registros, chave):
    if not isinstance(registros, list):
        raise ValueError("registros deve ser uma lista")
    vistos = set()
    resultado = []
    for reg in registros:
        if not isinstance(reg, dict):
            raise ValueError("todos os elementos devem ser dicionários")
        if chave not in reg:
            raise ValueError(f"chave '{chave}' ausente em um dos dicionários")
        valor = reg[chave]
        if valor not in vistos:
            vistos.add(valor)
            resultado.append(reg)
    return resultado


