def proxima_geracao(grade):
    if not grade or not grade[0]:
        raise ValueError("Grade vazia")

    linhas = len(grade)
    colunas = len(grade[0])

    for linha in grade:
        if len(linha) != colunas:
            raise ValueError("Grade não retangular")
        for celula in linha:
            if celula not in (0, 1):
                raise ValueError("Valores inválidos na grade")

    def contar_vizinhos(i, j):
        count = 0
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                if di == 0 and dj == 0:
                    continue
                ni, nj = i + di, j + dj
                if 0 <= ni < linhas and 0 <= nj < colunas:
                    count += grade[ni][nj]
        return count

    nova_grade = []
    for i in range(linhas):
        nova_linha = []
        for j in range(colunas):
            vizinhos = contar_vizinhos(i, j)
            if grade[i][j] == 1:
                nova_linha.append(1 if vizinhos in (2, 3) else 0)
            else:
                nova_linha.append(1 if vizinhos == 3 else 0)
        nova_grade.append(nova_linha)

    return nova_grade

