class EncurtadorURL:
    def __init__(self):
        self._url_para_codigo = {}
        self._codigo_para_url = {}
        self._cliques = {}
        self._contador = 0
        self._alfabeto = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

    def _codificar_base62(self, numero):
        if numero == 0:
            return self._alfabeto[0]
        caracteres = []
        base = len(self._alfabeto)
        while numero > 0:
            numero, resto = divmod(numero, base)
            caracteres.append(self._alfabeto[resto])
        return "".join(reversed(caracteres))

    def encurtar(self, url):
        if url in self._url_para_codigo:
            return self._url_para_codigo[url]
        codigo = self._codificar_base62(self._contador)
        self._contador += 1
        self._url_para_codigo[url] = codigo
        self._codigo_para_url[codigo] = url
        self._cliques[codigo] = 0
        return codigo

    def expandir(self, codigo):
        if codigo not in self._codigo_para_url:
            raise KeyError("Código não encontrado")
        self._cliques[codigo] += 1
        return self._codigo_para_url[codigo]

    def estatisticas(self):
        ordenados = sorted(
            self._cliques.items(),
            key=lambda item: (-item[1], item[0])
        )
        return {
            "total_urls": len(self._url_para_codigo),
            "total_cliques": sum(self._cliques.values()),
            "codigos_mais_acessados": ordenados
        }

class InventarioRPG:
    def __init__(self):
        self._itens = {}

    def adicionar_item(self, nome: str, quantidade: int, peso_unitario: float):
        if quantidade <= 0:
            raise ValueError("Quantidade deve ser positiva")
        if peso_unitario <= 0:
            raise ValueError("Peso unitário deve ser positivo")
        if nome in self._itens:
            qtd_atual, peso = self._itens[nome]
            if peso != peso_unitario:
                raise ValueError("Peso unitário difere do item existente")
            self._itens[nome] = (qtd_atual + quantidade, peso)
        else:
            self._itens[nome] = (quantidade, peso_unitario)

    def remover_item(self, nome: str, quantidade: int):
        if quantidade <= 0:
            raise ValueError("Quantidade deve ser positiva")
        if nome not in self._itens:
            raise ValueError("Item não existe no inventário")
        qtd_atual, peso = self._itens[nome]
        if quantidade > qtd_atual:
            raise ValueError("Quantidade insuficiente no inventário")
        if quantidade == qtd_atual:
            del self._itens[nome]
        else:
            self._itens[nome] = (qtd_atual - quantidade, peso)

    def peso_total(self) -> float:
        return sum(qtd * peso for qtd, peso in self._itens.values())

    def listar_itens(self) -> dict:
        return self._itens.copy()

def construir_where(clausulas):
    if not clausulas:
        raise ValueError("Lista de cláusulas vazia")

    operadores_validos = {'=', '!=', '<', '>', '<=', '>=', 'LIKE', 'IN', 'NOT IN'}
    partes = []
    params = []

    for clausula in clausulas:
        if not isinstance(clausula, dict):
            raise ValueError("Cada cláusula deve ser um dicionário")

        chaves_esperadas = {'coluna', 'operador', 'valor'}
        if set(clausula.keys()) != chaves_esperadas:
            raise ValueError("Cláusula deve conter exatamente as chaves: coluna, operador, valor")

        coluna = clausula['coluna']
        operador = clausula['operador']
        valor = clausula['valor']

        if operador not in operadores_validos:
            raise ValueError(f"Operador inválido: {operador}")

        if operador in ('IN', 'NOT IN'):
            if isinstance(valor, (str, bytes)):
                raise ValueError(f"Operador {operador} requer um iterável (não string/bytes)")
            try:
                iter(valor)
            except TypeError:
                raise ValueError(f"Operador {operador} requer um iterável")
            placeholders = ', '.join(['%s'] * len(valor))
            partes.append(f"{coluna} {operador} ({placeholders})")
            params.extend(valor)
        else:
            partes.append(f"{coluna} {operador} %s")
            params.append(valor)

    sql = ' AND '.join(partes)
    return sql, params

def encontrar_pares_soma(nums, target):
    if nums is None:
        raise ValueError("lista não pode ser None")
    seen = set()
    pairs = set()
    for x in nums:
        y = target - x
        if y in seen:
            a, b = (x, y) if x <= y else (y, x)
            pairs.add((a, b))
        seen.add(x)
    return list(pairs)


def contar_pares_soma(nums, target):
    if nums is None:
        raise ValueError("lista não pode ser None")
    return len(encontrar_pares_soma(nums, target))

def parse_query_params(query: str) -> dict[str, str]:
    for ch in query:
        code = ord(ch)
        if code <= 31 or code == 127:
            raise ValueError("query contains control characters")

    result = {}
    if not query:
        return result

    pairs = query.split('&')
    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        result[key] = value
    return result

class ClassificadorTerremotos:
    _CATEGORIAS = [
        (8.0, "Grande"),
        (7.0, "Maior"),
        (6.0, "Forte"),
        (5.0, "Moderado"),
        (4.0, "Leve"),
        (2.0, "Menor"),
        (0.0, "Micro"),
    ]

    def __init__(self):
        self._magnitudes = []
        self._contagem = {cat: 0 for _, cat in self._CATEGORIAS}

    def registrar(self, magnitude):
        if not isinstance(magnitude, (int, float)):
            raise ValueError("Magnitude deve ser um número")
        if magnitude < 0:
            raise ValueError("Magnitude não pode ser negativa")
        self._magnitudes.append(float(magnitude))
        categoria = self._classificar(magnitude)
        self._contagem[categoria] += 1

    def _classificar(self, magnitude):
        for limite, categoria in self._CATEGORIAS:
            if magnitude >= limite:
                return categoria
        return "Micro"

    def classificar_ultimo(self):
        if not self._magnitudes:
            return None
        return self._classificar(self._magnitudes[-1])

    def contagem_por_categoria(self):
        return dict(self._contagem)

def janela_deslizante(lista: list[int], k: int) -> list[int]:
    if k <= 0:
        raise ValueError("k deve ser maior que zero")
    if k > len(lista):
        raise ValueError("k não pode ser maior que o tamanho da lista")

    resultado = []
    soma_atual = sum(lista[:k])
    resultado.append(soma_atual)

    for i in range(k, len(lista)):
        soma_atual += lista[i] - lista[i - k]
        resultado.append(soma_atual)

    return resultado

