def rotear(rotas, caminho):
    if not isinstance(caminho, str) or not caminho.startswith('/'):
        raise ValueError("caminho deve ser uma string iniciada com '/'")
    if caminho == '/':
        pass
    for prefixo in rotas:
        if not isinstance(prefixo, str) or not prefixo.startswith('/'):
            raise ValueError("prefixos devem ser strings iniciadas com '/'")
    candidatos = [p for p in rotas if caminho == p or caminho.startswith(p + '/')]
    if not candidatos:
        raise KeyError("nenhum prefixo corresponde ao caminho")
    melhor = max(candidatos, key=len)
    return rotas[melhor]

