        quantidade_total = sum(q for q, _ in self._itens)
        bruto = self.subtotal_bruto()
        desconto = bruto * self._percentual_desconto(quantidade_total)
        return round(bruto - desconto, 2)

def calcular_dosagem(peso: float, dosagem_padrao: float) -> float:
    if peso <= 0:
        raise ValueError("Peso deve ser maior que zero")
    if dosagem_padrao < 0:
        raise ValueError("Dosagem padrão não pode ser negativa")
    dose_total = peso * dosagem_padrao
    if dose_total > 1000:
        raise ValueError("Dose total excede o limite máximo de 1000 mg")
    return float(dose_total)

TABELA_CAMBIO = {
    "USD": 1.0,
    "EUR": 0.85,
    "BRL": 5.2,
    "GBP": 0.75,
    "JPY": 110.0
}

def converter_moeda(valor, origem, destino):
    if valor < 0:
        raise ValueError("Valor não pode ser negativo")

    origem_upper = origem.upper()
    destino_upper = destino.upper()

    if origem_upper not in TABELA_CAMBIO:
        raise ValueError(f"Moeda de origem inválida: {origem}")
    if destino_upper not in TABELA_CAMBIO:
        raise ValueError(f"Moeda de destino inválida: {destino}")

    valor_em_usd = valor / TABELA_CAMBIO[origem_upper]
    resultado = valor_em_usd * TABELA_CAMBIO[destino_upper]

    return round(resultado, 2)

def calcular_juros_compostos(capital: float, taxa: float, periodos: int) -> float:
    if capital < 0:
        raise ValueError("capital não pode ser negativo")
    if taxa < 0:
        raise ValueError("taxa não pode ser negativa")
    if not isinstance(periodos, int) or periodos < 0:
        raise ValueError("periodos deve ser inteiro não-negativo")
    montante = capital * (1 + taxa) ** periodos
    return round(montante, 2)

def lis(sequence):
    if not isinstance(sequence, list):
        raise TypeError("Input must be a list")
    if not sequence:
        raise TypeError("List cannot be empty")
    if not all(isinstance(x, int) for x in sequence):
        raise TypeError("All elements must be integers")

    n = len(sequence)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if sequence[j] < sequence[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

import re

def filtrar_mensagem(mensagem, bloqueadas):
    if not isinstance(mensagem, str):
        raise ValueError("mensagem deve ser string")
    try:
        iter(bloqueadas)
    except TypeError:
        raise ValueError("bloqueadas deve ser iterável")

    bloqueadas_set = set()
    for p in bloqueadas:
        if not isinstance(p, str) or p == "":
            raise ValueError("cada palavra bloqueada deve ser string não vazia")
        bloqueadas_set.add(p.lower())

    if not bloqueadas_set:
        return mensagem

    padrao = r'\b(' + '|'.join(re.escape(p) for p in bloqueadas_set) + r')\b'
    regex = re.compile(padrao, flags=re.IGNORECASE)

    def substituir(match):
        return '*' * len(match.group(0))

    return regex.sub(substituir, mensagem)

class DivisorMultiplo:
    def __init__(self, n: int):
        if not isinstance(n, int) or n <= 0:
            raise ValueError("n deve ser um inteiro positivo")
        self._n = n
        self._divisores = self._calcular_divisores()

    def _calcular_divisores(self) -> list[int]:
        divs = []
        for i in range(1, int(self._n ** 0.5) + 1):
            if self._n % i == 0:
                divs.append(i)
                if i != self._n // i:
                    divs.append(self._n // i)
        divs.sort()
        return divs

    @property
    def divisores(self) -> list[int]:
        return self._divisores[:]

    def eh_divisor(self, d: int) -> bool:
        if not isinstance(d, int) or d <= 0:
            raise ValueError("d deve ser um inteiro positivo")
        return self._n % d == 0

    def multiplos_ate(self, limite: int) -> list[int]:
        if not isinstance(limite, int) or limite < 1:
            raise ValueError("limite deve ser inteiro >= 1")
        if limite < self._n:
            return []
        return [self._n * k for k in range(1, limite // self._n + 1)]

    def mdc(self, outro: int) -> int:
        if not isinstance(outro, int) or outro <= 0:
            raise ValueError("outro deve ser um inteiro positivo")
        a, b = self._n, outro
        while b:
            a, b = b, a % b
        return a

def calcular_creditos_totais(disciplinas: dict) -> int:
    if not disciplinas:
        raise ValueError("O dicionário de disciplinas não pode ser vazio.")

    total = 0
    for codigo, dados in disciplinas.items():
        if not isinstance(dados, tuple) or len(dados) != 2:
            raise ValueError(f"Valor inválido para a disciplina {codigo}: deve ser uma tupla de dois elementos.")
        creditos, nota = dados
        if not isinstance(creditos, (int, float)) or not isinstance(nota, (int, float)):
            raise ValueError(f"Créditos e nota para {codigo} devem ser numéricos.")
        if nota >= 5.0:
            total += int(creditos)
    return total


def pode_formar(disciplinas: dict, minimo_creditos: int) -> bool:
    total_aprovado = calcular_creditos_totais(disciplinas)
    return total_aprovado >= minimo_creditos

def processar_cesta(itens, cupom=None):
    if not itens:
        raise ValueError("A cesta não pode estar vazia")

    subtotal = 0
    total_itens = 0

    for item in itens:
        preco = item["preco"]
        quantidade = item["quantidade"]

        if preco < 0:
            raise ValueError("Preço não pode ser negativo")
        if quantidade <= 0:
            raise ValueError("Quantidade deve ser positiva")

        subtotal += preco * quantidade
        total_itens += quantidade

    desconto = 0
    if cupom == "DESCONTO10":
        desconto = subtotal * 0.10
    elif cupom == "DESCONTO20":
        desconto = subtotal * 0.20

    total_final = subtotal - desconto

    return {
        "total_itens": total_itens,
        "subtotal": subtotal,
        "desconto": desconto,
        "total_final": total_final
    }

def contar_letras(texto: str) -> dict[str, int]:
