    contagem = {}
    for ch in texto.lower():
        if 'a' <= ch <= 'z':
            contagem[ch] = contagem.get(ch, 0) + 1
    return contagem

def calcular_depreciacao(valor_inicial: float, taxa_anual: float, anos: int) -> tuple[float, float]:
    if valor_inicial < 0:
        raise ValueError("valor_inicial deve ser não-negativo")
    if not (0 <= taxa_anual <= 1):
        raise ValueError("taxa_anual deve estar entre 0 e 1")
    if anos < 0:
        raise ValueError("anos deve ser não-negativo")

    linear = float(round(valor_inicial * (1 - taxa_anual * anos), 2))
    decrescente = float(round(valor_inicial * (1 - taxa_anual) ** anos, 2))
    return (linear, decrescente)

def extrair_trecho(texto: str, inicio: int, fim: int) -> str:
    if inicio < 0:
        raise ValueError("Índice inicial não pode ser negativo")
    if fim > len(texto):
        raise ValueError("Índice final excede o comprimento do texto")
    if inicio > fim:
        raise ValueError("Índice inicial não pode ser maior que o índice final")
    return texto[inicio:fim]

