def calcular_totais_linha(matriz: list[list[float]]) -> list[float]:
    if not matriz:
        raise ValueError("A matriz não pode ser vazia.")
    num_colunas = len(matriz[0])
    for i, linha in enumerate(matriz):
        if len(linha) != num_colunas:
            raise ValueError(f"Todas as linhas devem ter o mesmo tamanho. Linha 0 tem {num_colunas}, linha {i} tem {len(linha)}.")
    return [sum(linha) for linha in matriz]


def calcular_totais_coluna(matriz: list[list[float]]) -> list[float]:
    if not matriz:
        raise ValueError("A matriz não pode ser vazia.")
    num_colunas = len(matriz[0])
    for i, linha in enumerate(matriz):
        if len(linha) != num_colunas:
            raise ValueError(f"Todas as linhas devem ter o mesmo tamanho. Linha 0 tem {num_colunas}, linha {i} tem {len(linha)}.")
    return [sum(linha[j] for linha in matriz) for j in range(num_colunas)]

def mdc(a: int, b: int) -> int:
    if not isinstance(a, int) or not isinstance(b, int) or a <= 0 or b <= 0:
        raise ValueError("Os argumentos devem ser inteiros positivos")
    while b:
        a, b = b, a % b
    return a


def mmc(a: int, b: int) -> int:
    if not isinstance(a, int) or not isinstance(b, int) or a <= 0 or b <= 0:
        raise ValueError("Os argumentos devem ser inteiros positivos")
    return a * b // mdc(a, b)

def extrair_partes_caminho(caminho: str) -> dict:
    if not isinstance(caminho, str):
        raise ValueError("Caminho deve ser uma string")
    if caminho == "":
        raise ValueError("Caminho vazio")
    if caminho == "/":
        raise ValueError("Caminho não pode ser apenas '/'")
    if caminho.endswith("/"):
        raise ValueError("Caminho não pode terminar com '/'")

    ultima_barra = caminho.rfind("/")
    if ultima_barra == -1:
        diretorio = ""
        nome_com_ext = caminho
    else:
        diretorio = caminho[:ultima_barra + 1]
        nome_com_ext = caminho[ultima_barra + 1:]

    if nome_com_ext == "":
        raise ValueError("Nome base vazio")

    ponto = nome_com_ext.rfind(".")
    if ponto == -1:
        nome_base = nome_com_ext
        extensao = ""
    else:
        nome_base = nome_com_ext[:ponto]
        extensao = nome_com_ext[ponto:]

    if nome_base == "":
        raise ValueError("Nome base vazio")

    return {
        "diretorio": diretorio,
        "nome_base": nome_base,
        "extensao": extensao
    }

import time
from collections import deque
from dataclasses import dataclass
from typing import Optional


@dataclass
class _EntradaChave:
    chave: str
    expiracao: float


class RotacaoChavesAPI:
    def __init__(self) -> None:
        self._fila: deque[_EntradaChave] = deque()

    def add_chave(self, chave: str, ttl_segundos: int) -> None:
        if not isinstance(ttl_segundos, int) or ttl_segundos <= 0:
            raise ValueError("TTL deve ser um inteiro positivo")
        if any(e.chave == chave for e in self._fila):
            raise ValueError("Chave já existe")
        expiracao = time.monotonic() + ttl_segundos
        self._fila.append(_EntradaChave(chave, expiracao))

    def chave_atual(self) -> Optional[str]:
        agora = time.monotonic()
        while self._fila and self._fila[0].expiracao <= agora:
            self._fila.popleft()
        return self._fila[0].chave if self._fila else None

    def remover_expiradas(self) -> int:
        agora = time.monotonic()
        removidas = 0
        while self._fila and self._fila[0].expiracao <= agora:
            self._fila.popleft()
            removidas += 1
        return removidas

