def indentar_texto(texto, nivel):
    if not isinstance(texto, str):
        raise TypeError("texto deve ser uma string")
    if not isinstance(nivel, int):
        raise TypeError("nivel deve ser um inteiro")
    if nivel < 0:
        raise ValueError("nivel não pode ser negativo")

    if nivel == 0:
        return texto

    prefixo = ' ' * (nivel * 4)
    linhas = texto.split('\n')
    resultado = []
    for linha in linhas:
        if linha.strip() == '':
            resultado.append(linha)
        else:
            resultado.append(prefixo + linha)
    return '\n'.join(resultado)

def mesclar_config(padrao: dict, arquivo: dict, ambiente: dict) -> dict:
    if not isinstance(padrao, dict) or not isinstance(arquivo, dict) or not isinstance(ambiente, dict):
        raise TypeError("Todos os argumentos devem ser dicionários")

    def mesclar_recursivo(base: dict, sobrescrita: dict) -> dict:
        resultado = base.copy()
        for chave, valor in sobrescrita.items():
            if (
                chave in resultado
                and isinstance(resultado[chave], dict)
                and isinstance(valor, dict)
            ):
                resultado[chave] = mesclar_recursivo(resultado[chave], valor)
            else:
                resultado[chave] = valor
        return resultado

    mesclado = mesclar_recursivo(padrao, arquivo)
    mesclado = mesclar_recursivo(mesclado, ambiente)
    return mesclado


def obter_config(config: dict, chave: str):
    if not isinstance(config, dict):
        raise TypeError("O primeiro argumento deve ser um dicionário")
    if not isinstance(chave, str):
        raise TypeError("A chave deve ser uma string")

    if not chave:
        return None

    partes = chave.split(".")
    atual = config
    for parte in partes:
        if not isinstance(atual, dict) or parte not in atual:
            return None
        atual = atual[parte]
    return atual

def _esta_ordenada(lista):
    return all(lista[i] <= lista[i + 1] for i in range(len(lista) - 1))

def busca_indice(lista, alvo):
    if not _esta_ordenada(lista):
        raise ValueError("A lista deve estar ordenada")
    esquerda, direita = 0, len(lista) - 1
    while esquerda <= direita:
        meio = (esquerda + direita) // 2
        if lista[meio] == alvo:
            return meio
        elif lista[meio] < alvo:
            esquerda = meio + 1
        else:
            direita = meio - 1
    return -1

def existe(lista, alvo):
    return busca_indice(lista, alvo) != -1

def pontuacao_dado(face: int) -> int:
