            vencedor = nome
    return vencedor

def alternar_paridade(numeros):
    if not isinstance(numeros, list):
        raise TypeError("Entrada deve ser uma lista")

    resultado = []
    for i, num in enumerate(numeros):
        if not isinstance(num, int):
            raise ValueError("Todos os elementos devem ser inteiros")

        if i % 2 == 0:
            resultado.append(num)
        else:
            if num % 2 == 0:
                resultado.append(num + 1)
            else:
                resultado.append(num - 1)
    return resultado

class Metricas:
