        self._contadores = {}
        self._somas = {}

    def registrar(self, chave: str, valor):
        if not isinstance(chave, str) or not chave:
            raise ValueError("Chave deve ser string não vazia")
        if not isinstance(valor, (int, float)):
            raise TypeError("Valor deve ser numérico")
        self._contadores[chave] = self._contadores.get(chave, 0) + 1
        self._somas[chave] = self._somas.get(chave, 0) + valor

    def contador(self, chave: str) -> int:
        return self._contadores.get(chave, 0)

    def soma(self, chave: str) -> float:
        return self._somas.get(chave, 0.0)

    def histograma(self) -> list[tuple[str, int]]:
