def build_where_clause(filters: dict) -> tuple[str, list]:
    if not isinstance(filters, dict):
        raise ValueError("filters must be a dictionary")

    conditions = []
    params = []

    for key, value in filters.items():
        if not isinstance(key, str):
            raise ValueError("filter keys must be strings")
        if isinstance(value, (dict, list, tuple, set)):
            raise ValueError("filter values cannot be dict, list, tuple, or set")

        if value is None:
            conditions.append(f"{key} IS NULL")
        else:
            conditions.append(f"{key} = ?")
            params.append(value)

    where_clause = " AND ".join(conditions) if conditions else ""
    return where_clause, params


def apply_where_params(base_query: str, where_result: tuple[str, list]) -> tuple[str, list]:
    where_clause, params = where_result
    if where_clause:
        final_query = f"{base_query} WHERE {where_clause}"
    else:
        final_query = base_query
    return final_query, params

