def validar_linha_sudoku(linha: list[int]) -> bool:
    if len(linha) != 9:
        raise ValueError("A linha deve conter exatamente 9 elementos.")
    for v in linha:
        if not isinstance(v, int) or v < 0 or v > 9:
            raise ValueError("Valores devem ser inteiros entre 0 e 9.")
    vistos = set()
    for v in linha:
        if v == 0:
            continue
        if v in vistos:
            return False
        vistos.add(v)
    return True


def completar_linha_sudoku(linha: list[int]) -> list[int]:
    if not validar_linha_sudoku(linha):
        raise ValueError("Linha inválida para completamento.")
    faltantes = [d for d in range(1, 10) if d not in linha]
    zeros_idx = [i for i, v in enumerate(linha) if v == 0]
    if len(faltantes) != len(zeros_idx):
        raise ValueError("Não é possível completar de forma única.")
    if len(zeros_idx) != 1:
        raise ValueError("Não é possível completar de forma única.")
    resultado = list(linha)
    for idx, val in zip(zeros_idx, faltantes):
        resultado[idx] = val
    return resultado

def calcular_preco_final(preco_unitario: float, quantidade: int, desconto: float = 0.0, imposto: float = 0.0) -> float:
    if preco_unitario < 0:
        raise ValueError("preco_unitario nao pode ser negativo")
    if quantidade < 0:
        raise ValueError("quantidade nao pode ser negativa")
    if desconto < 0 or desconto > 100:
        raise ValueError("desconto deve estar entre 0 e 100")
    if imposto < 0:
        raise ValueError("imposto nao pode ser negativo")
    subtotal = preco_unitario * quantidade
    valor_desconto = subtotal * (desconto / 100)
    valor_com_desconto = subtotal - valor_desconto
    valor_imposto = valor_com_desconto * (imposto / 100)
    return valor_com_desconto + valor_imposto


def aplicar_desconto_quantidade(preco_unitario: float, quantidade: int, faixas: list[tuple[int, float]]) -> float:
    if preco_unitario < 0:
        raise ValueError("preco_unitario nao pode ser negativo")
    if quantidade < 0:
        raise ValueError("quantidade nao pode ser negativa")
    if not faixas:
        raise ValueError("faixas nao pode ser vazia")
    for limite, perc in faixas:
        if limite < 0:
            raise ValueError("limite_minimo nao pode ser negativo")
        if perc < 0 or perc > 100:
            raise ValueError("percentual_desconto deve estar entre 0 e 100")
    desconto_aplicavel = 0.0
    for limite, perc in faixas:
        if quantidade >= limite and perc > desconto_aplicavel:
            desconto_aplicavel = perc
    return preco_unitario * (1 - desconto_aplicavel / 100)

def atender_fila(tempos):
    if not tempos:
        raise ValueError("A fila não pode estar vazia")
    if any(t < 0 for t in tempos):
        raise ValueError("Tempos de atendimento não podem ser negativos")

    tempo_total_espera = 0
    tempo_acumulado = 0

    for tempo in tempos:
        tempo_total_espera += tempo_acumulado
        tempo_acumulado += tempo

    return tempo_total_espera

def divisores_em_comum(a, b):
    if not isinstance(a, int) or not isinstance(b, int):
        raise ValueError("Ambos os argumentos devem ser inteiros")
    if a <= 0 or b <= 0:
        raise ValueError("Ambos os argumentos devem ser positivos")

    def mdc(x, y):
        while y:
            x, y = y, x % y
        return x

    g = mdc(a, b)
    divisores = []
    for i in range(1, int(g**0.5) + 1):
        if g % i == 0:
            divisores.append(i)
            if i != g // i:
                divisores.append(g // i)
    return sorted(divisores)

def converter(valor, unidade_origem, unidade_destino):
    if valor < 0:
        raise ValueError("Valor não pode ser negativo")

    unidades_comprimento = {'m': 1.0, 'cm': 0.01, 'mm': 0.001, 'km': 1000.0}
    unidades_massa = {'kg': 1.0, 'g': 0.001, 'mg': 0.000001, 't': 1000.0}

    if unidade_origem in unidades_comprimento and unidade_destino in unidades_comprimento:
        valor_em_metros = valor * unidades_comprimento[unidade_origem]
        return valor_em_metros / unidades_comprimento[unidade_destino]
    elif unidade_origem in unidades_massa and unidade_destino in unidades_massa:
        valor_em_kg = valor * unidades_massa[unidade_origem]
        return valor_em_kg / unidades_massa[unidade_destino]
    else:
        raise ValueError("Unidades incompatíveis ou não suportadas")

def calcular_area_triangulo(base, altura):
    if not isinstance(base, (int, float)) or not isinstance(altura, (int, float)):
        raise ValueError("Base e altura devem ser números")
    if base <= 0 or altura <= 0:
        raise ValueError("Base e altura devem ser positivos")
    return (base * altura) / 2

import copy


class Sorteador:
    def __init__(self, itens):
        self._original = list(itens)
        self._itens = list(itens)
        self._pos = 0

    def sortear(self):
        if not self._itens:
            raise IndexError("lista vazia")
        idx = self._pos % len(self._itens)
        item = self._itens.pop(idx)
        self._pos = idx
        return item

    def reset(self):
        self._itens = list(self._original)
        self._pos = 0

    def estado(self):
        return (list(self._itens), self._pos)

_contador_timestamp = 0

def registrar_presenca(registros, aluno, status):
    global _contador_timestamp
    if not isinstance(registros, list):
        raise ValueError("Registros deve ser uma lista.")
    if not isinstance(aluno, str) or not aluno.strip():
        raise ValueError("Nome do aluno deve ser uma string não vazia.")
    if status not in ('presente', 'ausente', 'atrasado'):
        raise ValueError("Status inválido. Use: 'presente', 'ausente' ou 'atrasado'.")
    _contador_timestamp += 1
    registros.append({
        'aluno': aluno.strip(),
        'status': status,
        'timestamp': _contador_timestamp
    })

def gerar_relatorio(registros):
    if not isinstance(registros, list):
        raise ValueError("Registros deve ser uma lista.")
    contagem = {'presente': 0, 'ausente': 0, 'atrasado': 0}
    atrasados = []
    for reg in registros:
        if isinstance(reg, dict) and 'status' in reg and 'aluno' in reg:
            st = reg['status']
            if st in contagem:
                contagem[st] += 1
            if st == 'atrasado':
                atrasados.append(reg['aluno'])
    return {
        'contagem': contagem,
        'atrasados': sorted(atrasados)
    }

def para_minutos(hora, minuto):
    if not isinstance(hora, int) or not isinstance(minuto, int):
        raise ValueError("Hora e minuto devem ser inteiros")
    if not (0 <= hora <= 23):
        raise ValueError("Hora deve estar entre 0 e 23")
    if not (0 <= minuto <= 59):
        raise ValueError("Minuto deve estar entre 0 e 59")
    return hora * 60 + minuto


def para_horario(minutos):
    if not isinstance(minutos, int):
        raise ValueError("Minutos deve ser um inteiro")
    if minutos < 0:
        raise ValueError("Minutos não pode ser negativo")
    total = minutos % 1440
    hora = total // 60
    minuto = total % 60
    return (hora, minuto)

def gerenciar_inscricoes(operacoes):
    cursos = {}
    resultados = []

    for op in operacoes:
        acao = op[0]

        if acao == "inscrever":
            _, curso, aluno, capacidade = op
            if capacidade <= 0:
                raise ValueError("Capacidade deve ser maior que zero")
            if curso not in cursos:
                cursos[curso] = {"capacidade": capacidade, "inscritos": set()}
            else:
                if cursos[curso]["capacidade"] != capacidade:
                    raise ValueError("Capacidade do curso não confere")

            if aluno in cursos[curso]["inscritos"]:
                raise ValueError("Aluno já inscrito neste curso")
            if len(cursos[curso]["inscritos"]) >= cursos[curso]["capacidade"]:
                raise ValueError("Curso lotado")

            cursos[curso]["inscritos"].add(aluno)
            resultados.append(None)

        elif acao == "cancelar":
            _, curso, aluno = op
            if curso not in cursos:
                raise ValueError("Curso inexistente")
            if aluno not in cursos[curso]["inscritos"]:
                raise ValueError("Aluno não inscrito neste curso")

            cursos[curso]["inscritos"].remove(aluno)
            resultados.append(None)

        elif acao == "listar_inscritos":
            _, curso = op
            if curso not in cursos:
                raise ValueError("Curso inexistente")
            resultados.append(sorted(cursos[curso]["inscritos"]))

        elif acao == "vagas_disponiveis":
            _, curso = op
            if curso not in cursos:
                raise ValueError("Curso inexistente")
            vagas = cursos[curso]["capacidade"] - len(cursos[curso]["inscritos"])
            resultados.append(vagas)

        else:
            raise ValueError("Operação inválida")

    return resultados

class ValidadorPlaca:
    def __init__(self):
        self._validas = []
        self._vistas = set()

    def validar(self, placa: str) -> None:
        if not isinstance(placa, str):
            raise ValueError("Placa deve ser uma string")
        placa = placa.strip().upper()
        if not placa:
            raise ValueError("Placa vazia")
        if len(placa) != 7:
            raise ValueError("Placa deve ter 7 caracteres")

        padrao_antigo = all(c.isalpha() for c in placa[:3]) and all(c.isdigit() for c in placa[3:])
        padrao_mercosul = (all(c.isalpha() for c in placa[:3]) and
                           placa[3].isdigit() and
                           placa[4].isalpha() and
                           all(c.isdigit() for c in placa[5:]))

        if not (padrao_antigo or padrao_mercosul):
            raise ValueError("Formato de placa inválido")

        if placa not in self._vistas:
            self._vistas.add(placa)
            self._validas.append(placa)

    def listar_validas(self) -> list[str]:
        return list(self._validas)

def contar_especiais(texto: str) -> int:
