import re

def inverter_texto(texto: str, modo: str) -> str:
    if modo not in ('palavras', 'frases', 'ambos'):
        raise ValueError("Modo inválido. Use 'palavras', 'frases' ou 'ambos'.")

    if modo in ('palavras', 'ambos'):
        palavras = texto.split()
        texto = ' '.join(reversed(palavras))

    if modo in ('frases', 'ambos'):
        partes = re.split(r'([.!?])', texto)
        frases = []
        i = 0
        while i < len(partes) - 1:
            frase = partes[i].strip()
            pontuacao = partes[i + 1]
            if frase:
                frases.append(frase + pontuacao)
            i += 2
        if i < len(partes) and partes[i].strip():
            frases.append(partes[i].strip())
        texto = ' '.join(reversed(frases))

    return texto

class CalendarioReservas:
    def __init__(self):
        self._reservas = {}

    def adicionar_reserva(self, id_reserva: str, inicio: str, fim: str) -> None:
        if fim < inicio:
            raise ValueError("Data de fim anterior à data de início")
        for existente in self._reservas.values():
            if not (fim < existente["inicio"] or inicio > existente["fim"]):
                raise ValueError("Sobreposição de reserva")
        self._reservas[id_reserva] = {"inicio": inicio, "fim": fim}

    def esta_reservado(self, data: str) -> bool:
        for reserva in self._reservas.values():
            if reserva["inicio"] <= data <= reserva["fim"]:
                return True
        return False

    def listar_reservas(self) -> list[tuple[str, str, str]]:
        return sorted(
            [(id_r, r["inicio"], r["fim"]) for id_r, r in self._reservas.items()],
            key=lambda x: x[1]
        )

    def remover_reserva(self, id_reserva: str) -> None:
        if id_reserva not in self._reservas:
            raise ValueError("Reserva não encontrada")
        del self._reservas[id_reserva]

