def simular_caminho(acoes: list[tuple[str, int]], inicio: tuple[int, int, int]) -> tuple[int, int, int]:
    """Simula o movimento do robô na grade a partir de uma posição inicial."""
    x, y, direcao = inicio
    if direcao not in (0, 1, 2, 3):
        raise ValueError("Direção inicial deve ser 0, 1, 2 ou 3")
    # 0=Norte, 1=Leste, 2=Sul, 3=Oeste
    for acao, valor in acoes:
        if acao == 'frente':
            if direcao == 0:
                y += valor
            elif direcao == 1:
                x += valor
            elif direcao == 2:
                y -= valor
            else:  # direcao == 3
                x -= valor
        elif acao == 'esquerda':
            direcao = (direcao - (valor // 90)) % 4
        elif acao == 'direita':
            direcao = (direcao + (valor // 90)) % 4
    return (x, y, direcao)

