    if len(numero) < 13 or len(numero) > 19:
        raise ValueError("Comprimento deve estar entre 13 e 19 dígitos")

    ultimos_quatro = numero[-4:]
    mascarados = '*' * (len(numero) - 4)
    return mascarados + ultimos_quatro

class GradeHorarios:
    def __init__(self):
        self._aulas_por_dia = {i: [] for i in range(7)}

    def adicionar_aula(self, dia: int, inicio: int, fim: int, disciplina: str) -> None:
        if not 0 <= dia <= 6:
            raise ValueError("Dia da semana deve estar entre 0 e 6")
        if inicio >= fim:
            raise ValueError("Horário de início deve ser menor que o horário de fim")
        if not isinstance(disciplina, str) or not disciplina.strip():
            raise ValueError("Nome da disciplina não pode ser vazio")

        nova_aula = (inicio, fim, disciplina.strip())
        for aula_existente in self._aulas_por_dia[dia]:
            if max(inicio, aula_existente[0]) < min(fim, aula_existente[1]):
                raise ValueError("Conflito de horário com aula existente")

        self._aulas_por_dia[dia].append(nova_aula)
        self._aulas_por_dia[dia].sort(key=lambda x: x[0])

    def listar_dia(self, dia: int) -> list[tuple[int, int, str]]:
        if not 0 <= dia <= 6:
            raise ValueError("Dia da semana deve estar entre 0 e 6")
        return list(self._aulas_por_dia[dia])

    def listar_todas(self) -> list[tuple[int, int, int, str]]:
        resultado = []
        for dia in range(7):
            for inicio, fim, disciplina in self._aulas_por_dia[dia]:
                resultado.append((dia, inicio, fim, disciplina))
        return resultado

