def extrair_hashtags_mencoes(texto):
    if not isinstance(texto, str):
        raise TypeError("O argumento deve ser uma string")
    if not texto:
        raise ValueError("O texto não pode estar vazio")

    hashtags = []
    mencoes = []
    hashtags_vistas = set()
    mencoes_vistas = set()

    import re
    padrao = r'(?:^|\s)(#[A-Za-z0-9_]+|@[A-Za-z0-9_]+)(?=\s|$|[.,;:!?])'
    matches = re.findall(padrao, texto)

    for match in matches:
        if match.startswith('#'):
            tag = match[1:]
            if tag not in hashtags_vistas:
                hashtags_vistas.add(tag)
                hashtags.append(tag)
        elif match.startswith('@'):
            mencao = match[1:]
            if mencao not in mencoes_vistas:
                mencoes_vistas.add(mencao)
                mencoes.append(mencao)

    return (hashtags, mencoes)

def parse_query_string(query: str) -> dict:
    if not query:
        return {}

    result = {}
    pairs = query.split('&')

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''

        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(value)
            else:
                result[key] = [existing, value]
        else:
            result[key] = value

    return result


def build_query_string(params: dict) -> str:
    if not params:
        return ''

    items = []

    for key in sorted(params.keys()):
        value = params[key]
        if value is None:
            values = ['']
        elif isinstance(value, list):
            values = value
        else:
            values = [value]

        for v in values:
            if isinstance(v, bool):
                str_v = 'true' if v else 'false'
            elif v is None:
                str_v = ''
            else:
                str_v = str(v)
            items.append((key, str_v))

    items.sort(key=lambda x: (x[0], x[1]))

    return '&'.join(f'{k}={v}' for k, v in items)

