def simular_fila_atendimento(comandos):
    fila = []
    resultados = []

    for cmd in comandos:
        partes = cmd.split()
        if not partes:
            raise ValueError("Comando inválido")

        tipo = partes[0]

        if tipo == "CHEGADA":
            if len(partes) != 2:
                raise ValueError("Comando inválido")
            nome = partes[1]
            fila.append(nome)
        elif tipo == "ATENDER":
            if len(partes) != 1:
                raise ValueError("Comando inválido")
            if not fila:
                resultados.append("VAZIA")
            else:
                resultados.append(fila.pop(0))
        elif tipo == "PROXIMO":
            if len(partes) != 1:
                raise ValueError("Comando inválido")
            if not fila:
                resultados.append("VAZIA")
            else:
                resultados.append(fila[0])
        elif tipo == "TAMANHO":
            if len(partes) != 1:
                raise ValueError("Comando inválido")
            resultados.append(len(fila))
        else:
            raise ValueError("Comando inválido")

    return resultados

class RoteiroEntregas:
    def __init__(self, capacidade_maxima: int):
        if capacidade_maxima <= 0:
            raise ValueError("Capacidade deve ser positiva")
        self.capacidade_maxima = capacidade_maxima
        self.entregas = []  # lista de tuplas (destino, peso)

    def adicionar_entrega(self, destino: str, peso: float):
        if peso < 0:
            raise ValueError("Peso não pode ser negativo")
        if any(d == destino for d, _ in self.entregas):
            raise ValueError("Destino duplicado")
        if self.peso_total() + peso > self.capacidade_maxima:
            raise ValueError("Capacidade excedida")
        self.entregas.append((destino, peso))

    def remover_entrega(self, destino: str) -> bool:
        for i, (d, _) in enumerate(self.entregas):
            if d == destino:
                del self.entregas[i]
                return True
        return False

    def proxima_entrega(self):
        if not self.entregas:
            return None
        return self.entregas[0][0]

    def peso_total(self) -> float:
        return sum(p for _, p in self.entregas)

