def calcular_tarifa_taxi(distancia_km, tempo_espera_min, bandeira):
    if distancia_km < 0:
        raise ValueError("Distância não pode ser negativa")
    if tempo_espera_min < 0:
        raise ValueError("Tempo de espera não pode ser negativo")
    if bandeira not in (1, 2):
        raise ValueError("Bandeira deve ser 1 ou 2")

    valor_distancia = distancia_km * 2.50
    valor_espera = tempo_espera_min * 0.80
    multiplicador = 1.0 if bandeira == 1 else 1.5

    total = (valor_distancia + valor_espera) * multiplicador
    return round(total, 2)

