def ordenar_migracoes(migracoes: dict[str, list[str]]) -> list[str]:
    grafo = {m: set(deps) for m, deps in migracoes.items()}
    for m, deps in grafo.items():
        for d in deps:
            if d not in grafo:
                raise ValueError(f"Dependência inexistente: {d}")

    visitando = set()
    visitado = set()
    ordem = []

    def dfs(no: str):
        if no in visitando:
            raise ValueError("Dependência cíclica detectada")
        if no in visitado:
            return
        visitando.add(no)
        for dep in grafo[no]:
            dfs(dep)
        visitando.remove(no)
        visitado.add(no)
        ordem.append(no)

    for no in grafo:
        if no not in visitado:
            dfs(no)
    return ordem

def filtrar_produtos(produtos, categoria=None, preco_min=None, preco_max=None, em_estoque=None):
    chaves_obrigatorias = {"nome", "categoria", "preco", "em_estoque"}
    for p in produtos:
        if not chaves_obrigatorias.issubset(p.keys()):
            raise ValueError("Produto inválido: chaves obrigatórias ausentes")
    if preco_min is not None and preco_max is not None and preco_min > preco_max:
        raise ValueError("preco_min não pode ser maior que preco_max")
    resultado = []
    for p in produtos:
        if categoria is not None and p["categoria"] != categoria:
            continue
        if preco_min is not None and p["preco"] < preco_min:
            continue
        if preco_max is not None and p["preco"] > preco_max:
            continue
        if em_estoque is not None and p["em_estoque"] != em_estoque:
            continue
        resultado.append(p)
    return resultado

def historico_operacoes(limite=10):
    if not isinstance(limite, int) or limite <= 0:
        raise ValueError("Limite deve ser um inteiro positivo")

    class Historico:
        def __init__(self, max_size):
            self._max_size = max_size
            self._dados = []

        def adicionar(self, operacao, resultado):
            if len(self._dados) >= self._max_size:
                self._dados.pop(0)
            self._dados.append((operacao, resultado))

        def desfazer(self):
            if not self._dados:
                raise IndexError("Histórico vazio")
            return self._dados.pop()

        def obter_historico(self):
            return list(self._dados)

    return Historico(limite)

import re
import string

def construir_indice_palavras(texto: str) -> dict[str, list[int]]:
    if not isinstance(texto, str):
        raise ValueError("O argumento deve ser uma string.")
    if not texto.strip():
        raise ValueError("A string não pode ser vazia ou conter apenas espaços em branco.")

    # Encontra palavras e suas posições de início no texto original
    # \b\w+\b captura sequências de caracteres alfanuméricos/underscore delimitadas por fronteiras de palavra
    # Isso ignora pontuação nas bordas naturalmente
    palavras_com_posicoes = [(m.group().lower(), m.start()) for m in re.finditer(r'\b\w+\b', texto)]

    indice = {}
    for palavra, posicao in palavras_com_posicoes:
        if palavra not in indice:
            indice[palavra] = []
        indice[palavra].append(posicao)

    # As listas já estão ordenadas pois re.finditer processa da esquerda para a direita
    return indice

def converter_minutos_para_horario(minutos: int) -> str:
    if not isinstance(minutos, int):
        raise ValueError("Minutos deve ser um inteiro")
    if minutos < 0 or minutos >= 1440:
        raise ValueError("Minutos deve estar entre 0 e 1439")
    horas = minutos // 60
    mins = minutos % 60
    return f"{horas:02d}:{mins:02d}"

class MediaPonderada:
    def __init__(self):
        self._notas = []
        self._pesos = []

    def adicionar(self, nota, peso):
        if not isinstance(nota, (int, float)):
            raise TypeError("nota deve ser um numero")
        if not isinstance(peso, (int, float)):
            raise TypeError("peso deve ser um numero")
        if peso <= 0:
            raise ValueError("peso deve ser positivo")
        self._notas.append(float(nota))
        self._pesos.append(float(peso))

    def media(self):
        if not self._notas:
            return None
        soma_produtos = sum(n * p for n, p in zip(self._notas, self._pesos))
        soma_pesos = sum(self._pesos)
        return soma_produtos / soma_pesos

    def reset(self):
        self._notas.clear()
        self._pesos.clear()

