def gerar_relatorio_frequencia(palavras: list[str]) -> dict[str, int]:
    if not isinstance(palavras, list):
        raise ValueError("Entrada deve ser uma lista")
    for p in palavras:
        if not isinstance(p, str):
            raise ValueError("Todos os elementos devem ser strings")
    freq: dict[str, int] = {}
    for p in palavras:
        freq[p] = freq.get(p, 0) + 1
    return dict(sorted(freq.items(), key=lambda kv: (-kv[1], kv[0])))

class GerenciadorPrioridades:
    def __init__(self):
        self._tarefas = []
        self._contador = 0

    def adicionar_tarefa(self, nome, prioridade):
        if not isinstance(prioridade, int) or prioridade <= 0:
            raise ValueError("Prioridade deve ser um inteiro positivo")
        self._tarefas.append((self._contador, nome, prioridade))
        self._contador += 1

    def proxima_tarefa(self):
        if not self._tarefas:
            raise IndexError("Nenhuma tarefa disponível")
        idx = max(range(len(self._tarefas)), key=lambda i: (self._tarefas[i][2], -self._tarefas[i][0]))
        _, nome, prioridade = self._tarefas.pop(idx)
        return (nome, prioridade)

    def listar_tarefas(self):
        ordenadas = sorted(self._tarefas, key=lambda t: (-t[2], t[0]))
        return [(nome, prioridade) for _, nome, prioridade in ordenadas]

    def remover_tarefa(self, nome):
        for i, (_, n, _) in enumerate(self._tarefas):
            if n == nome:
                self._tarefas.pop(i)
                return True
        return False

class EstatisticasNumericas:
    def __init__(self):
        self._valores = []

    def adicionar(self, valor):
        if isinstance(valor, bool) or not isinstance(valor, (int, float)):
            raise TypeError("Valor deve ser int ou float")
        self._valores.append(valor)
        return len(self._valores)

    def media(self):
        if not self._valores:
            raise ValueError("Lista vazia")
        return sum(self._valores) / len(self._valores)

    def desvio_padrao(self):
        n = len(self._valores)
        if n < 2:
            raise ValueError("Menos de 2 elementos")
        m = sum(self._valores) / n
        variancia = sum((x - m) ** 2 for x in self._valores) / n
        return variancia ** 0.5

    def limpar(self):
        self._valores.clear()
        return None

def interpolar_linear(x, x0, y0, x1, y1):
    if x0 == x1:
        raise ValueError("x0 e x1 não podem ser iguais")
    if x1 < x0:
        x0, x1 = x1, x0
        y0, y1 = y1, y0
    if x < x0 or x > x1:
        raise ValueError("x está fora do intervalo de interpolação")
    if x0 == x1:
        return y0
    t = (x - x0) / (x1 - x0)
    return y0 + t * (y1 - y0)

