def arredondar(valor, casas):
    if not isinstance(valor, (int, float)):
        raise TypeError("valor deve ser int ou float")
    if not isinstance(casas, int):
        raise TypeError("casas deve ser int")
    if casas < 0:
        raise ValueError("casas não pode ser negativo")
    if casas == 0:
        return int(valor + 0.5) if valor >= 0 else int(valor - 0.5)
    fator = 10 ** casas
    if valor >= 0:
        return int(valor * fator + 0.5) / fator
    else:
        return int(valor * fator - 0.5) / fator

def calcular_dano(atacante: dict, defensor: dict) -> int:
    """Calcula o dano causado por um atacante a um defensor."""
    for d, nome in [(atacante, 'atacante'), (defensor, 'defensor')]:
        if not isinstance(d, dict):
            raise ValueError(f"{nome} deve ser um dicionário")
        if 'ataque' not in d or 'defesa' not in d:
            raise ValueError(f"{nome} deve conter chaves 'ataque' e 'defesa'")
        if not isinstance(d['ataque'], int) or not isinstance(d['defesa'], int):
            raise ValueError(f"'ataque' e 'defesa' de {nome} devem ser inteiros")
        if d['ataque'] <= 0 or d['defesa'] <= 0:
            raise ValueError(f"'ataque' e 'defesa' de {nome} devem ser positivos")
    dano = atacante['ataque'] - defensor['defesa']
    return max(1, dano)


def simular_combate(jogador: dict, inimigo: dict) -> str:
    """Simula um combate por turnos entre jogador e inimigo."""
    for d, nome in [(jogador, 'jogador'), (inimigo, 'inimigo')]:
        if not isinstance(d, dict):
            raise ValueError(f"{nome} deve ser um dicionário")
        for chave in ('hp', 'ataque', 'defesa'):
            if chave not in d:
                raise ValueError(f"{nome} deve conter chave '{chave}'")
            if not isinstance(d[chave], int) or d[chave] <= 0:
                raise ValueError(f"'{chave}' de {nome} deve ser inteiro positivo")
    hp_jogador = jogador['hp']
    hp_inimigo = inimigo['hp']
    turno_jogador = True
    while hp_jogador > 0 and hp_inimigo > 0:
        if turno_jogador:
            dano = calcular_dano(jogador, inimigo)
            hp_inimigo -= dano
        else:
            dano = calcular_dano(inimigo, jogador)
            hp_jogador -= dano
        turno_jogador = not turno_jogador
    return 'jogador' if hp_jogador > 0 else 'inimigo'

class ParserCSV:
    def __init__(self, linha: str, separador: str = ","):
        self.linha = linha
        self.separador = separador

    def parse(self) -> list[str]:
        if not self.linha:
            return [""]

        campos = []
        campo_atual = []
        dentro_aspas = False
        i = 0
        n = len(self.linha)

        while i < n:
            char = self.linha[i]

            if char == '"':
                if dentro_aspas:
                    if i + 1 < n and self.linha[i + 1] == '"':
                        campo_atual.append('"')
                        i += 2
                        continue
                    else:
                        dentro_aspas = False
                        i += 1
                        continue
                else:
                    if campo_atual:
                        raise ValueError("Aspas de abertura em posição inválida")
                    dentro_aspas = True
                    i += 1
                    continue

            if char == self.separador and not dentro_aspas:
                campos.append("".join(campo_atual).strip())
                campo_atual = []
                i += 1
                continue

            campo_atual.append(char)
            i += 1

        if dentro_aspas:
            raise ValueError("Aspas não balanceadas")

        campos.append("".join(campo_atual).strip())
        return campos

def mediana_e_moda(valores):
    if not valores:
        raise ValueError("lista vazia")
    ordenados = sorted(valores)
    n = len(ordenados)
    if n % 2 == 1:
        mediana = ordenados[n // 2]
    else:
        mediana = (ordenados[n // 2 - 1] + ordenados[n // 2]) / 2
    contagem = {}
    for v in ordenados:
        contagem[v] = contagem.get(v, 0) + 1
    max_freq = max(contagem.values())
    candidatos = [v for v, f in contagem.items() if f == max_freq]
    moda = min(candidatos)
    return (mediana, moda)

