def divisores_proprios(n: int) -> list[int]:
    """Retorna lista ordenada dos divisores próprios de n (excluindo n)."""
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n deve ser inteiro positivo")
    if n == 1:
        return []
    divs = [1]
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i != n // i:
                divs.append(n // i)
    divs.sort()
    return divs


def multiplos_comuns(a: int, b: int, limite: int) -> list[int]:
    """Retorna lista ordenada dos múltiplos comuns de a e b menores que limite."""
    if not all(isinstance(x, int) and x > 0 for x in (a, b, limite)):
        raise ValueError("argumentos devem ser inteiros positivos")
    # MDC via Euclides
    def mdc(x, y):
        while y:
            x, y = y, x % y
        return x
    mmc = a * b // mdc(a, b)
    if mmc >= limite:
        return []
    return list(range(mmc, limite, mmc))

