class CotaPlano:
    def __init__(self, cota_mensal: int):
        if not isinstance(cota_mensal, int) or cota_mensal <= 0:
            raise ValueError("Cota mensal deve ser um inteiro positivo")
        self.cota_mensal = cota_mensal
        self.cota_restante = cota_mensal

    def consumir(self, qtd: int) -> int:
        if not isinstance(qtd, int) or qtd <= 0:
            raise ValueError("Quantidade deve ser um inteiro positivo")
        if qtd > self.cota_restante:
            raise ValueError("Cota insuficiente")
        self.cota_restante -= qtd
        return self.cota_restante

    def dias_para_reset(self, hoje: date) -> int:
        if not isinstance(hoje, date):
            raise ValueError("Parâmetro 'hoje' deve ser do tipo date")
        _, ultimo_dia = monthrange(hoje.year, hoje.month)
        return (ultimo_dia - hoje.day) + 1

