def calcular_progressao(tipo: str, a1: float, r: float, n: int) -> tuple[list[float], float]:
    if tipo not in ('aritmetica', 'geometrica'):
        raise ValueError("Tipo deve ser 'aritmetica' ou 'geometrica'")
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n deve ser inteiro positivo")
    if tipo == 'geometrica' and a1 == 0 and r == 0:
        raise ValueError("Progressão geométrica com a1=0 e r=0 é indefinida")

    termos = []
    if tipo == 'aritmetica':
        termos = [a1 + i * r for i in range(n)]
        soma = n * (2 * a1 + (n - 1) * r) / 2
    else:
        termos = [a1 * (r ** i) for i in range(n)]
        if r == 1:
            soma = n * a1
        else:
            soma = a1 * (1 - r ** n) / (1 - r)

    return (termos, soma)

class RotacaoLista:
    def __init__(self, lista_inicial=None):
        self._lista = list(lista_inicial) if lista_inicial is not None else []

    def rotacionar(self, direcao: str, passos: int) -> None:
        if not self._lista:
            return
        if direcao not in ("esquerda", "direita"):
            raise ValueError("Direção deve ser 'esquerda' ou 'direita'")
        n = len(self._lista)
        k = passos % n
        if k == 0:
            return
        if direcao == "esquerda":
            self._lista[:] = self._lista[k:] + self._lista[:k]
        else:
            self._lista[:] = self._lista[-k:] + self._lista[:-k]

    def obter(self):
        return self._lista.copy()

import time
from collections import OrderedDict


class CacheTempo:
    def __init__(self, ttl_segundos: int, capacidade_maxima: int | None = None):
        if ttl_segundos <= 0:
            raise ValueError("ttl_segundos deve ser maior que zero")
        if capacidade_maxima is not None and capacidade_maxima <= 0:
            raise ValueError("capacidade_maxima deve ser maior que zero")
        self._ttl = ttl_segundos
        self._capacidade = capacidade_maxima
        self._dados: OrderedDict[str, tuple[object, float]] = OrderedDict()

    def put(self, chave: str, valor: object) -> None:
        agora = time.time()
        if chave in self._dados:
            self._dados[chave] = (valor, agora)
            self._dados.move_to_end(chave)
        else:
            if self._capacidade is not None and len(self._dados) >= self._capacidade:
                self._dados.popitem(last=False)
            self._dados[chave] = (valor, agora)

    def get(self, chave: str) -> object | None:
        if chave not in self._dados:
            return None
        valor, timestamp = self._dados[chave]
        if time.time() - timestamp > self._ttl:
            del self._dados[chave]
            return None
        return valor

    def remove(self, chave: str) -> bool:
        if chave in self._dados:
            del self._dados[chave]
            return True
        return False

    def limpar_expirados(self) -> int:
        agora = time.time()
        expiradas = [k for k, (_, ts) in self._dados.items() if agora - ts > self._ttl]
        for k in expiradas:
            del self._dados[k]
        return len(expiradas)

class CarrinhoCompras:
    def __init__(self):
        self._itens = {}
        self._desconto = 0.0

    def adicionar_item(self, nome: str, preco: float, quantidade: int):
        if preco <= 0 or quantidade <= 0:
            raise ValueError("Preço e quantidade devem ser positivos")
        if nome in self._itens:
            self._itens[nome]["quantidade"] += quantidade
        else:
            self._itens[nome] = {"preco": preco, "quantidade": quantidade}

    def remover_item(self, nome: str):
        if nome not in self._itens:
            raise ValueError("Item não encontrado")
        del self._itens[nome]

    def aplicar_desconto(self, porcentagem: float):
        if porcentagem < 0 or porcentagem > 100:
            raise ValueError("Desconto deve estar entre 0 e 100")
        self._desconto = porcentagem

    def total(self) -> float:
        subtotal = sum(item["preco"] * item["quantidade"] for item in self._itens.values())
        return subtotal * (1 - self._desconto / 100)

def resumir_texto(texto: str, n: int) -> str:
