def validar_cadastro(dados: dict) -> list[str]:
    if not isinstance(dados, dict):
        raise TypeError("Entrada deve ser um dicionário")

    chaves_obrigatorias = {'nome', 'email', 'idade', 'senha', 'confirmar_senha'}
    if not chaves_obrigatorias.issubset(dados.keys()):
        raise TypeError("Dicionário deve conter as chaves: nome, email, idade, senha, confirmar_senha")

    erros = []

    nome = dados['nome']
    if not isinstance(nome, str) or not nome.strip():
        erros.append("nome: não pode ser vazio")

    email = dados['email']
    if not isinstance(email, str):
        erros.append("email: deve ser uma string")
    else:
        if email.count('@') != 1:
            erros.append("email: deve conter exatamente um '@'")
        else:
            parte_local, dominio = email.split('@')
            if '.' not in dominio:
                erros.append("email: domínio deve conter pelo menos um '.'")

    idade = dados['idade']
    if not isinstance(idade, int):
        erros.append("idade: deve ser um inteiro")
    elif idade < 13 or idade > 120:
        erros.append("idade: deve estar entre 13 e 120")

    senha = dados['senha']
    if not isinstance(senha, str):
        erros.append("senha: deve ser uma string")
    else:
        if len(senha) < 8:
            erros.append("senha: deve ter pelo menos 8 caracteres")
        if not any(c.isupper() for c in senha):
            erros.append("senha: deve conter pelo menos uma maiúscula")
        if not any(c.islower() for c in senha):
            erros.append("senha: deve conter pelo menos uma minúscula")
        if not any(c.isdigit() for c in senha):
            erros.append("senha: deve conter pelo menos um dígito")
        especiais = set('!@#$%^&*')
        if not any(c in especiais for c in senha):
            erros.append("senha: deve conter pelo menos um caractere especial (!@#$%^&*)")

    confirmar = dados['confirmar_senha']
    if not isinstance(confirmar, str):
        erros.append("confirmar_senha: deve ser uma string")
    elif confirmar != senha:
        erros.append("confirmar_senha: deve ser idêntico à senha")

    return erros

def calcular_parcelas(valor_principal: float, taxa_juros_mensal: float, numero_parcelas: int) -> list[float]:
    if valor_principal <= 0:
        raise ValueError("valor_principal deve ser positivo")
    if taxa_juros_mensal < 0:
        raise ValueError("taxa_juros_mensal não pode ser negativa")
    if numero_parcelas <= 0:
        raise ValueError("numero_parcelas deve ser positivo")
    if taxa_juros_mensal == 0 and numero_parcelas > 1000:
        raise ValueError("numero_parcelas excede limite para taxa zero")

    amortizacao = valor_principal / numero_parcelas
    parcelas = []
    saldo_devedor = valor_principal

    for _ in range(numero_parcelas):
        juros = saldo_devedor * taxa_juros_mensal
        parcela = amortizacao + juros
        parcelas.append(round(parcela, 2))
        saldo_devedor -= amortizacao

    return parcelas

class ArvoreGenealogica:
