def calcular_subtotal(itens: list[tuple[float, int]]) -> float:
    if not itens:
        raise ValueError("A lista de itens não pode estar vazia")
    total = 0.0
    for preco, qtd in itens:
        if preco < 0:
            raise ValueError("Preço unitário não pode ser negativo")
        if not isinstance(qtd, int) or qtd <= 0:
            raise ValueError("Quantidade deve ser inteiro positivo")
        total += preco * qtd
    return total


def aplicar_desconto_progressivo(subtotal: float, numero_itens: int) -> float:
    if subtotal < 0:
        raise ValueError("Subtotal não pode ser negativo")
    if not isinstance(numero_itens, int) or numero_itens <= 0:
        raise ValueError("Número de itens deve ser inteiro positivo")
    if 3 <= numero_itens <= 5:
        desconto = 0.05
    elif 6 <= numero_itens <= 9:
        desconto = 0.10
    elif numero_itens >= 10:
        desconto = 0.15
    else:
        desconto = 0.0
    return round(subtotal * (1 - desconto), 2)

def processar_intervalos(numeros):
    if not numeros:
        raise ValueError("Lista vazia")
    for n in numeros:
        if not isinstance(n, int):
            raise ValueError("Elemento não inteiro")

    ordenados = sorted(set(numeros))
    if not ordenados:
        raise ValueError("Lista vazia")

    intervalos = []
    inicio = ordenados[0]
    fim = ordenados[0]

    for num in ordenados[1:]:
        if num == fim + 1:
            fim = num
        else:
            intervalos.append((inicio, fim))
            inicio = num
            fim = num
    intervalos.append((inicio, fim))
    return intervalos

def normalizar_caminho(caminho: str) -> str:
    if not isinstance(caminho, str):
        raise TypeError("caminho deve ser uma string")
    if caminho == "":
        return "."

    # Detecta se é caminho absoluto (começa com / ou \)
    absoluto = caminho.startswith('/') or caminho.startswith('\\')

    # Normaliza separadores para /
    partes = caminho.replace('\\', '/').split('/')

    pilha = []
    for parte in partes:
        if parte == '' or parte == '.':
            # Ignora vazios (barras duplicadas) e .
            continue
        elif parte == '..':
            if pilha and pilha[-1] != '..':
                pilha.pop()
            elif not absoluto:
                # Em caminhos relativos, mantém .. se não há nada para subir
                pilha.append('..')
            # Em caminhos absolutos, .. no início é ignorado (não sobe além da raiz)
        else:
            pilha.append(parte)

    resultado = '/'.join(pilha)
    if absoluto:
        resultado = '/' + resultado
    if resultado == '':
        return '.'
    return resultado

class ColecaoItens:
    def __init__(self):
        self._itens = {}
        self._proximo_id = 1

    def adicionar(self, dados: dict) -> int:
        if not isinstance(dados, dict):
            raise TypeError("dados deve ser um dicionário")
        item_id = self._proximo_id
        self._proximo_id += 1
        self._itens[item_id] = dict(dados)
        return item_id

    def buscar(self, **filtros) -> list:
        resultados = []
        for item in self._itens.values():
            if all(item.get(k) == v for k, v in filtros.items()):
                resultados.append(dict(item))
        return resultados

    def atualizar(self, item_id: int, novos_dados: dict) -> None:
        if item_id not in self._itens:
            raise ValueError("ID não encontrado")
        if not isinstance(novos_dados, dict):
            raise TypeError("novos_dados deve ser um dicionário")
        self._itens[item_id].update(novos_dados)

    def remover(self, item_id: int) -> None:
        if item_id not in self._itens:
            raise ValueError("ID não encontrado")
        del self._itens[item_id]

def calcular_situacao(notas):
    if not isinstance(notas, list):
        raise ValueError("As notas devem ser fornecidas em uma lista.")
    n = len(notas)
    if n < 3 or n > 5:
        raise ValueError("A lista deve conter entre 3 e 5 notas.")
    for nota in notas:
        if not isinstance(nota, (int, float)):
            raise ValueError("Todas as notas devem ser números (int ou float).")
        if nota < 0 or nota > 10:
            raise ValueError("As notas devem estar no intervalo de 0 a 10.")
    media = round(sum(notas) / n, 1)
    if media >= 7:
        situacao = 'Aprovado'
    elif media >= 5:
        situacao = 'Recuperação'
    else:
        situacao = 'Reprovado'
    return (media, situacao)

def minutos_para_horario(minutos: int) -> str:
    if not isinstance(minutos, int):
        raise ValueError("Minutos deve ser um inteiro")
    if minutos < 0:
        raise ValueError("Minutos não pode ser negativo")
    horas = minutos // 60
    mins = minutos % 60
    return f"{horas:02d}:{mins:02d}"


def horario_para_minutos(horario: str) -> int:
    if not isinstance(horario, str):
        raise ValueError("Horário deve ser uma string")
    partes = horario.split(":")
    if len(partes) != 2:
        raise ValueError("Formato inválido, esperado HH:MM")
    try:
        horas = int(partes[0])
        minutos = int(partes[1])
    except ValueError:
        raise ValueError("Horas e minutos devem ser números inteiros")
    if not (0 <= horas <= 23):
        raise ValueError("Horas deve estar entre 00 e 23")
    if not (0 <= minutos <= 59):
        raise ValueError("Minutos deve estar entre 00 e 59")
    return horas * 60 + minutos

