def mesclar_configs(base: dict, overrides: dict) -> dict:
    if not isinstance(base, dict):
        raise TypeError("base deve ser um dicionário")
    if not isinstance(overrides, dict):
        raise TypeError("overrides deve ser um dicionário")

    resultado = {}
    for chave, valor in base.items():
        resultado[chave] = valor

    for chave, valor in overrides.items():
        if valor is None:
            resultado.pop(chave, None)
        elif chave in resultado and isinstance(resultado[chave], dict) and isinstance(valor, dict):
            resultado[chave] = mesclar_configs(resultado[chave], valor)
        else:
            resultado[chave] = valor

    return resultado

import re

def contar_palavras_texto(texto: str) -> int:
    if not isinstance(texto, str):
        raise ValueError("Entrada deve ser uma string")
    if not texto:
        return 0
    palavras = re.findall(r'[A-Za-z0-9]+', texto)
    return len(palavras)

def contar_frases_texto(texto: str) -> int:
    if not isinstance(texto, str):
        raise ValueError("Entrada deve ser uma string")
    if not texto:
        return 0
    frases = re.split(r'[.!?](?=\s|$)', texto)
    frases_validas = [f for f in frases if f.strip()]
    return len(frases_validas)

from datetime import date, timedelta
from typing import Tuple


def _parse_data(data_str: str) -> date:
    try:
        dia, mes, ano = map(int, data_str.split("/"))
        return date(ano, mes, dia)
    except Exception:
        raise ValueError("Data inválida")


def _formatar_data(d: date) -> str:
    return d.strftime("%d/%m/%Y")


def adicionar_dias_uteis(data_inicial: date, dias_uteis: int) -> date:
    if dias_uteis < 0:
        raise ValueError("Dias úteis não podem ser negativos")
    atual = data_inicial
    adicionados = 0
    while adicionados < dias_uteis:
        atual += timedelta(days=1)
        if atual.weekday() < 5:  # 0-4 = segunda a sexta
            adicionados += 1
    return atual


def calcular_prazo_entrega(data_inicio: str, dias_uteis: int) -> str:
    if dias_uteis < 0:
        raise ValueError("Dias úteis não podem ser negativos")
    data = _parse_data(data_inicio)
    data_fim = adicionar_dias_uteis(data, dias_uteis)
    return _formatar_data(data_fim)

import math


def calcular_volume(solido: str, **dimensoes) -> float:
    solidos_validos = {"cubo", "esfera", "cilindro", "cone"}
    if solido not in solidos_validos:
        raise ValueError(f"Sólido desconhecido: {solido}")

    dimensoes_necessarias = {
        "cubo": {"aresta"},
        "esfera": {"raio"},
        "cilindro": {"raio", "altura"},
        "cone": {"raio", "altura"},
    }

    necessarias = dimensoes_necessarias[solido]
    fornecidas = set(dimensoes.keys())

    if necessarias != fornecidas:
        faltando = necessarias - fornecidas
        extras = fornecidas - necessarias
        mensagens = []
        if faltando:
            mensagens.append(f"Dimensões obrigatórias ausentes: {', '.join(sorted(faltando))}")
        if extras:
            mensagens.append(f"Dimensões não utilizadas: {', '.join(sorted(extras))}")
        raise ValueError("; ".join(mensagens))

    for nome, valor in dimensoes.items():
        if not isinstance(valor, (int, float)):
            raise ValueError(f"Dimensão '{nome}' deve ser numérica")
        if valor <= 0:
            raise ValueError(f"Dimensão '{nome}' deve ser maior que zero")

    if solido == "cubo":
        a = dimensoes["aresta"]
        return float(a ** 3)
    elif solido == "esfera":
        r = dimensoes["raio"]
        return float((4 / 3) * math.pi * r ** 3)
    elif solido == "cilindro":
        r = dimensoes["raio"]
        h = dimensoes["altura"]
        return float(math.pi * r ** 2 * h)
    else:  # cone
        r = dimensoes["raio"]
        h = dimensoes["altura"]
        return float((1 / 3) * math.pi * r ** 2 * h)

def validar_campos(dados: dict) -> list[str]:
    erros = []
    nome = dados.get("nome", "")
    if not isinstance(nome, str) or not nome.strip():
        erros.append("Nome não pode ser vazio.")
    email = dados.get("email", "")
    if not isinstance(email, str):
        erros.append("Email inválido.")
    else:
        if email.count("@") != 1:
            erros.append("Email deve conter exatamente um '@'.")
        else:
            local, dominio = email.split("@")
            if "." not in dominio:
                erros.append("Email deve conter pelo menos um '.' após o '@'.")
    idade = dados.get("idade")
    if not isinstance(idade, int):
        erros.append("Idade deve ser um inteiro entre 0 e 120.")
    elif idade < 0 or idade > 120:
        erros.append("Idade deve ser um inteiro entre 0 e 120.")
    return erros


def limpar_dados(dados: dict) -> dict:
    nome = dados.get("nome", "")
