def agregar_por_minuto(registros):
    if not registros:
        raise ValueError("Lista de registros vazia")

    agrupados = {}
    for timestamp, valor in registros:
        if not isinstance(timestamp, int):
            raise ValueError("Timestamp deve ser inteiro")
        if timestamp < 0:
            raise ValueError("Timestamp não pode ser negativo")
        if not isinstance(valor, (int, float)):
            raise ValueError("Valor deve ser numérico")

        minuto = timestamp // 60
        if minuto not in agrupados:
            agrupados[minuto] = []
        agrupados[minuto].append(valor)

    resultado = {}
    for minuto, valores in agrupados.items():
        resultado[minuto] = sum(valores) / len(valores)

    return resultado

def gerar_escala(funcionarios: list[str], turnos_por_dia: int) -> dict[str, list[list[str]]]:
    if not funcionarios:
        raise ValueError("Lista de funcionários não pode ser vazia")
    if turnos_por_dia < 1:
        raise ValueError("Turnos por dia deve ser pelo menos 1")
    if len(funcionarios) < turnos_por_dia:
        raise ValueError("Número de funcionários deve ser maior ou igual aos turnos por dia")

    dias = ["segunda", "terca", "quarta", "quinta", "sexta", "sabado", "domingo"]
    n = len(funcionarios)
    total_turnos = 7 * turnos_por_dia

    base = total_turnos // n
    extra = total_turnos % n
    cotas = [base + (1 if i < extra else 0) for i in range(n)]

    escala = {dia: [[] for _ in range(turnos_por_dia)] for dia in dias}
    idx = 0
    for dia in dias:
        for t in range(turnos_por_dia):
            tentativas = 0
            while tentativas < n:
                func = funcionarios[idx % n]
                if cotas[funcionarios.index(func)] > 0:
                    if t == 0 or func not in escala[dia][t - 1]:
                        escala[dia][t].append(func)
                        cotas[funcionarios.index(func)] -= 1
                        break
                idx += 1
                tentativas += 1
            else:
                for j in range(n):
                    func = funcionarios[j]
                    if cotas[j] > 0 and (t == 0 or func not in escala[dia][t - 1]):
                        escala[dia][t].append(func)
                        cotas[j] -= 1
                        break
            idx += 1
    return escala

def extrair_diagonais(matriz):
    if not isinstance(matriz, list) or not all(isinstance(linha, list) for linha in matriz):
        raise ValueError("A matriz deve ser uma lista de listas")

    n = len(matriz)
    if n == 0:
        raise ValueError("A matriz não pode estar vazia")

    tamanho_linha = len(matriz[0])
    if not all(len(linha) == tamanho_linha for linha in matriz):
        raise ValueError("Todas as linhas devem ter o mesmo tamanho")

    if n != tamanho_linha:
        raise ValueError("A matriz deve ser quadrada")

    principal = [matriz[i][i] for i in range(n)]
    secundaria = [matriz[i][n - 1 - i] for i in range(n)]

    return (principal, secundaria)

class ClassificacaoCampeonato:
    def __init__(self):
        self._resultados = {}

    def adicionar_resultado(self, vencedor, perdedor):
        if not vencedor or not perdedor:
            raise ValueError("Os nomes dos times não podem ser vazios ou nulos.")
        self._resultados.setdefault(vencedor, [0, 0])
        self._resultados.setdefault(perdedor, [0, 0])
        self._resultados[vencedor][0] += 1
        self._resultados[perdedor][1] += 1

    def classificacao(self):
        return sorted(
            [(nome, v[0], v[1]) for nome, v in self._resultados.items()],
            key=lambda x: (-x[1], x[0])
        )

class OperacaoBancaria:
    def __init__(self, saldo_inicial, limite_diario):
        if saldo_inicial < 0:
            raise ValueError("saldo inicial não pode ser negativo")
        if limite_diario < 0:
            raise ValueError("limite diário não pode ser negativo")
        self.saldo = saldo_inicial
        self.limite_diario = limite_diario
        self.sacado_hoje = 0

    def saque(self, valor):
        if valor <= 0:
            raise ValueError("valor do saque deve ser positivo")
        if valor > self.saldo:
            raise ValueError("saldo insuficiente")
        if self.sacado_hoje + valor > self.limite_diario:
            raise ValueError("limite diário excedido")
        self.saldo -= valor
        self.sacado_hoje += valor

    def deposito(self, valor):
        if valor <= 0:
            raise ValueError("valor do depósito deve ser positivo")
        self.saldo += valor

    def extrato(self):
        return (self.saldo, self.sacado_hoje)

from datetime import date


def diferenca_datas(data1, data2):
    def validar_data(data):
        if not isinstance(data, tuple) or len(data) != 3:
            raise ValueError("A data deve ser uma tupla de três inteiros.")
        ano, mes, dia = data
        if not all(isinstance(v, int) for v in (ano, mes, dia)):
            raise ValueError("Ano, mês e dia devem ser inteiros.")
        if not (1 <= ano <= 9999):
            raise ValueError("Ano deve estar entre 1 e 9999.")
        if not (1 <= mes <= 12):
            raise ValueError("Mês deve estar entre 1 e 12.")
        try:
            return date(ano, mes, dia)
        except ValueError:
            raise ValueError("Data inválida.")

    d1 = validar_data(data1)
    d2 = validar_data(data2)
    return abs((d2 - d1).days)

