def comprimir_rle(texto):
    if not isinstance(texto, str):
        raise TypeError("texto deve ser uma string")
    if texto == "":
        raise ValueError("texto nao pode ser vazio")
    partes = []
    atual = texto[0]
    contador = 1
    for caractere in texto[1:]:
        if caractere == atual:
            contador += 1
        else:
            partes.append(atual + str(contador))
            atual = caractere
            contador = 1
    partes.append(atual + str(contador))
    resultado = "".join(partes)
    if len(resultado) >= len(texto):
        return texto
    return resultado

def mesclar_intervalos(intervalos):
    if intervalos is None:
        raise ValueError("intervalos deve ser uma lista")

    normalizados = []
    for intervalo in intervalos:
        if not isinstance(intervalo, (list, tuple)) or len(intervalo) != 2:
            raise ValueError("cada intervalo deve conter exatamente dois números")
        inicio, fim = intervalo
        if not isinstance(inicio, int) or not isinstance(fim, int):
            raise ValueError("os limites do intervalo devem ser inteiros")
        if inicio > fim:
            raise ValueError("o início não pode ser maior que o fim")
        normalizados.append([inicio, fim])

    if not normalizados:
        return []

    normalizados.sort(key=lambda x: x[0])
    resultado = [normalizados[0]]

    for inicio, fim in normalizados[1:]:
        ultimo = resultado[-1]
        if inicio <= ultimo[1]:
            if fim > ultimo[1]:
                ultimo[1] = fim
        else:
            resultado.append([inicio, fim])

    return resultado

