def estatistica(lista):
    if not lista:
        raise ValueError("lista vazia")
    for item in lista:
        if not isinstance(item, (int, float)):
            raise TypeError("todos os elementos devem ser numeros")
    ordenada = sorted(lista)
    n = len(ordenada)
    if n % 2 == 1:
        mediana = ordenada[n // 2]
    else:
        mediana = (ordenada[n // 2 - 1] + ordenada[n // 2]) / 2
    frequencias = {}
    for item in lista:
        frequencias[item] = frequencias.get(item, 0) + 1
    max_freq = max(frequencias.values())
    modas = [valor for valor, freq in frequencias.items() if freq == max_freq]
    moda = min(modas)
    return (mediana, moda)

