            raise ValueError("inicio e fim devem ser inteiros")
        if inicio < 0 or fim < 0:
            raise ValueError("inicio e fim devem ser nao negativos")
        if fim <= inicio:
            raise ValueError("fim deve ser maior que inicio")
        for ini, fim_existente, _ in self._reservas:
            if inicio < fim_existente and ini < fim:
                raise ValueError("horario sobrepoe reserva existente")
        id_reserva = self._proximo_id
        self._reservas.append((inicio, fim, id_reserva))
        self._proximo_id += 1
        return id_reserva

