import keyword
import re

_PADRAO_IDENTIFICADOR = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')


def eh_identificador_valido(texto):
    if not isinstance(texto, str) or texto == '':
        raise ValueError('texto deve ser uma string não vazia')
    return texto.isidentifier() and not keyword.iskeyword(texto)


def extrair_identificadores(texto):
    if not isinstance(texto, str) or texto == '':
        raise ValueError('texto deve ser uma string não vazia')
    encontrados = []
    for correspondencia in _PADRAO_IDENTIFICADOR.finditer(texto):
        candidato = correspondencia.group()
        if eh_identificador_valido(candidato):
            encontrados.append(candidato)
    return encontrados

def calcular_conjuntos(a, b):
    if not isinstance(a, list) or not isinstance(b, list):
        raise TypeError("Ambos os argumentos devem ser listas")
    for item in a + b:
        if not isinstance(item, (int, str)):
            raise ValueError("Elementos devem ser inteiros ou strings")
    set_a = set(a)
    set_b = set(b)
    return {
        'uniao': sorted(set_a | set_b),
        'intersecao': sorted(set_a & set_b),
        'diferenca': sorted(set_a - set_b),
    }

