class DesfazerRefazer:
    def __init__(self):
        self._pilha_desfazer = []
        self._pilha_refazer = []

    def executar(self, acao, valor):
        self._pilha_desfazer.append((acao, valor))
        self._pilha_refazer.clear()
        return acao(valor)

    def desfazer(self):
        if not self._pilha_desfazer:
            raise ValueError("Nenhuma ação para desfazer")
        acao, valor = self._pilha_desfazer.pop()
        self._pilha_refazer.append((acao, valor))
        return valor

    def refazer(self):
        if not self._pilha_refazer:
            raise ValueError("Nenhuma ação para refazer")
        acao, valor = self._pilha_refazer.pop()
        self._pilha_desfazer.append((acao, valor))
        return acao(valor)

