def intersecao_intervalo(intervalo_a, intervalo_b):
    for intervalo in (intervalo_a, intervalo_b):
        if not isinstance(intervalo, tuple) or len(intervalo) != 2:
            raise ValueError("intervalo deve ser uma tupla de exatamente dois elementos")
        inicio, fim = intervalo
        if not isinstance(inicio, (int, float)) or not isinstance(fim, (int, float)):
            raise ValueError("os elementos do intervalo devem ser numeros")
        if inicio > fim:
            raise ValueError("inicio nao pode ser maior que fim")

    inicio_a, fim_a = intervalo_a
    inicio_b, fim_b = intervalo_b

    inicio = max(inicio_a, inicio_b)
    fim = min(fim_a, fim_b)

    if inicio > fim:
        return None
    return (inicio, fim)

