def calcular_digito(numero):
    if not isinstance(numero, str) or len(numero) == 0 or not numero.isdigit():
        raise ValueError("numero deve ser uma string não vazia contendo apenas dígitos")
    soma = 0
    reverso = numero[::-1]
    for i, digito in enumerate(reverso):
        d = int(digito)
        if i % 2 == 0:
            d *= 2
            if d > 9:
                d -= 9
        soma += d
    return (10 - (soma % 10)) % 10


def validar_numero(numero):
    if not isinstance(numero, str) or len(numero) == 0 or not numero.isdigit():
        raise ValueError("numero deve ser uma string não vazia contendo apenas dígitos")
    if len(numero) < 2:
        return False
    return calcular_digito(numero[:-1]) == int(numero[-1])

