class Razao:
    def __init__(self, nome):
        self.nome = nome
        self._partidas = []

    def registrar_partida(self, data, descricao, lancamentos):
        if not isinstance(lancamentos, list) or len(lancamentos) == 0:
            raise ValueError('pelo menos um lançamento é necessário')
        total_debito = 0.0
        total_credito = 0.0
        for l in lancamentos:
            debito = l['debito']
            credito = l['credito']
            if not isinstance(debito, (int, float)) or isinstance(debito, bool):
                raise ValueError('debito deve ser número')
            if not isinstance(credito, (int, float)) or isinstance(credito, bool):
                raise ValueError('credito deve ser número')
            if debito < 0 or credito < 0:
                raise ValueError('valores não podem ser negativos')
            total_debito += debito
            total_credito += credito
        if total_debito != total_credito:
            raise ValueError('débitos e créditos devem estar equilibrados')
        self._partidas.append((data, descricao, list(lancamentos)))

    def saldo(self, conta):
        total = 0.0
        for _, _, lancamentos in self._partidas:
            for l in lancamentos:
                if l['conta'] == conta:
                    total += l['debito'] - l['credito']
        return total

    def extrato(self):
        linhas = []
        for data, descricao, lancamentos in self._partidas:
            for l in lancamentos:
                linhas.append(f'{data} - {descricao}: {l["conta"]} {l["debito"]} {l["credito"]}')
        return linhas

