class FilaConfirmacao:
    def __init__(self):
        self._mensagens = {}
        self._ordem = []

    def enfileirar(self, id_mensagem, conteudo):
        if id_mensagem in self._mensagens:
            raise ValueError("id duplicado")
        self._mensagens[id_mensagem] = {"conteudo": conteudo, "confirmada": False}
        self._ordem.append(id_mensagem)

    def confirmar(self, id_mensagem):
        if id_mensagem not in self._mensagens:
            raise KeyError("id nao encontrado")
        self._mensagens[id_mensagem]["confirmada"] = True
        return True

    def limpar_confirmadas(self):
        removidos = 0
        novos_ordem = []
        for id_mensagem in self._ordem:
            if self._mensagens[id_mensagem]["confirmada"]:
                del self._mensagens[id_mensagem]
                removidos += 1
            else:
                novos_ordem.append(id_mensagem)
        self._ordem = novos_ordem
        return removidos

    def listar_pendentes(self):
        return [self._mensagens[i]["conteudo"] for i in self._ordem if not self._mensagens[i]["confirmada"]]

