class FilaEmail:
    def __init__(self, limite_por_destinatario):
        self.limite_por_destinatario = limite_por_destinatario
        self.fila = []
        self.contagem_pendente = {}

    def enfileirar(self, destinatario, assunto):
        pendentes = self.contagem_pendente.get(destinatario, 0)
        if pendentes >= self.limite_por_destinatario:
            raise ValueError("Limite de e-mails pendentes atingido para este destinatário")
        self.fila.append((destinatario, assunto))
        self.contagem_pendente[destinatario] = pendentes + 1

    def processar_proximo(self):
        if not self.fila:
            raise IndexError("Fila vazia")
        destinatario, assunto = self.fila.pop(0)
        self.contagem_pendente[destinatario] -= 1
        if self.contagem_pendente[destinatario] == 0:
            del self.contagem_pendente[destinatario]
        return (destinatario, assunto)

def celsius_para_kelvin(valor):
