def soma_pa(primeiro_termo, razao, quantidade_termos):
    if quantidade_termos < 1:
        raise ValueError("quantidade_termos deve ser pelo menos 1")
    return quantidade_termos * (2 * primeiro_termo + (quantidade_termos - 1) * razao) // 2


def enesimo_pg(primeiro_termo, razao, n):
