        raise ValueError("n deve ser pelo menos 1")
    return primeiro_termo * (razao ** (n - 1))

def cor_para_rgb(hexadecimal):
    if not isinstance(hexadecimal, str) or len(hexadecimal) != 7 or hexadecimal[0] != '#':
        raise ValueError('cor invalida')
    digitos = hexadecimal[1:]
    if not all(c in '0123456789abcdefABCDEF' for c in digitos):
        raise ValueError('cor invalida')
    return (int(digitos[0:2], 16), int(digitos[2:4], 16), int(digitos[4:6], 16))

def converter_massa(valor, unidade_origem, unidade_destino):
    unidades_validas = {"grama", "quilograma", "tonelada"}
    if not isinstance(valor, (int, float)) or isinstance(valor, bool):
        raise ValueError("valor deve ser numérico")
    if unidade_origem not in unidades_validas or unidade_destino not in unidades_validas:
        raise ValueError("unidade inválida")
    para_grama = {"grama": 1, "quilograma": 1000, "tonelada": 1000000}
    gramas = valor * para_grama[unidade_origem]
    resultado = gramas / para_grama[unidade_destino]
    return round(resultado, 2)

def gerar_fibonacci(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n deve ser um inteiro não negativo")
    if n < 0:
        raise ValueError("n deve ser um inteiro não negativo")
    sequencia = []
    a, b = 0, 1
    for _ in range(n):
        sequencia.append(a)
        a, b = b, a + b
    return sequencia


def somar_pares_fibonacci(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n deve ser um inteiro não negativo")
    if n < 0:
        raise ValueError("n deve ser um inteiro não negativo")
    return sum(x for x in gerar_fibonacci(n) if x % 2 == 0)

def converter_hora_12_para_24(hora, minuto, periodo):
