    if not isinstance(minuto, int) or isinstance(minuto, bool) or minuto < 0 or minuto > 59:
        raise ValueError("minuto deve estar entre 0 e 59")
    if periodo not in ("AM", "PM"):
        raise ValueError("periodo deve ser 'AM' ou 'PM'")

    if periodo == "AM":
        hora24 = 0 if hora == 12 else hora
    else:
        hora24 = 12 if hora == 12 else hora + 12

    return (hora24, minuto)

