def converter_temperatura(valor, origem, destino):
    unidades_validas = {'C', 'F', 'K'}
    if origem not in unidades_validas or destino not in unidades_validas:
        raise ValueError("Unidade inválida. Use 'C', 'F' ou 'K'.")
    if origem == 'K' and valor < 0:
        raise ValueError("Temperatura em Kelvin não pode ser negativa.")
    if origem == destino:
        return valor
    if origem == 'C':
        if destino == 'F':
            return valor * 9 / 5 + 32
        if destino == 'K':
            return valor + 273.15
    if origem == 'F':
        if destino == 'C':
            return (valor - 32) * 5 / 9
        if destino == 'K':
            return (valor - 32) * 5 / 9 + 273.15
    if origem == 'K':
        if destino == 'C':
            return valor - 273.15
        if destino == 'F':
            return (valor - 273.15) * 9 / 5 + 32

def converter_celsius_para_fahrenheit(celsius):
