def converter_fahrenheit_para_celsius(fahrenheit):
    if fahrenheit < -459.67:
        raise ValueError("Temperatura abaixo do zero absoluto em Fahrenheit")
    return (fahrenheit - 32) * 5 / 9

def comprimir_intervalos(numeros):
    if not isinstance(numeros, list):
        raise ValueError("A entrada deve ser uma lista.")
    for item in numeros:
        if not isinstance(item, int) or isinstance(item, bool):
            raise ValueError("Todos os elementos devem ser inteiros.")
    if not numeros:
        return []
    ordenados = sorted(numeros)
    intervalos = []
    inicio = ordenados[0]
    fim = ordenados[0]
    for n in ordenados[1:]:
        if n == fim:
            continue
        if n == fim + 1:
            fim = n
        else:
            intervalos.append((inicio, fim))
            inicio = n
            fim = n
    intervalos.append((inicio, fim))
    return intervalos

