class TaxiMeter:
    def __init__(self, bandeira_inicial, preco_por_km, taxa_noturna=0.0, valor_minimo_km=0.0):
        if preco_por_km < 0 or taxa_noturna < 0 or valor_minimo_km < 0:
            raise ValueError("valores nao podem ser negativos")
        self.bandeira_inicial = bandeira_inicial
        self.preco_por_km = preco_por_km
        self.taxa_noturna = taxa_noturna
        self.valor_minimo_km = valor_minimo_km
        self.em_corrida = False
        self.km_percorridos = 0.0
        self.noturna = False

    def iniciar_corrida(self, noturna=False):
        if self.em_corrida:
            raise ValueError("corrida ja em andamento")
        self.em_corrida = True
        self.km_percorridos = 0.0
        self.noturna = noturna

    def adicionar_km(self, km):
        if not self.em_corrida:
            raise ValueError("nenhuma corrida em andamento")
        if km < 0:
            raise ValueError("km nao pode ser negativo")
        self.km_percorridos += km

    def encerrar_corrida(self):
        if not self.em_corrida:
            raise ValueError("nenhuma corrida em andamento")
        total = self.bandeira_inicial + max(self.preco_por_km, self.valor_minimo_km) * self.km_percorridos
        if self.noturna:
            total += self.taxa_noturna
        self.em_corrida = False
        self.km_percorridos = 0.0
        self.noturna = False
        return round(total, 2)

import re


def separar_nomes(texto):
    if not isinstance(texto, str):
        raise TypeError("texto deve ser uma string")

    texto = texto.replace(" ", "_")
    partes = texto.split("_")
    resultado = []

    for parte in partes:
        if parte == "":
            continue

        subpartes = re.findall(r'[A-Z]+(?=[A-Z][a-z]|\d|$)|\d+|[A-Z]?[a-z]+|\d', parte)
        for sub in subpartes:
            resultado.append(sub.lower())

    return resultado

