class Encurtador:
    BASE62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"

    def __init__(self):
        self._url_para_codigo = {}
        self._codigo_para_url = {}
        self._contador = 0

    def _para_base62(self, numero):
        if numero == 0:
            return self.BASE62[0]
        digitos = []
        while numero > 0:
            digitos.append(self.BASE62[numero % 62])
            numero //= 62
        return "".join(reversed(digitos))

    def encurtar(self, url):
        if not isinstance(url, str) or url == "":
            raise ValueError("URL inválida")
        if url in self._url_para_codigo:
            return self._url_para_codigo[url]
        self._contador += 1
        codigo = self._para_base62(self._contador)
        self._url_para_codigo[url] = codigo
        self._codigo_para_url[codigo] = url
        return codigo

    def expandir(self, codigo):
        if not isinstance(codigo, str) or codigo == "":
            raise ValueError("Código inválido")
        if codigo not in self._codigo_para_url:
            raise ValueError("Código não encontrado")
        return self._codigo_para_url[codigo]

def fatorar(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("o argumento deve ser um inteiro")
    if n <= 1:
        raise ValueError("o argumento deve ser maior que 1")
    fatores = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            expoente = 0
            while n % d == 0:
                n //= d
                expoente += 1
            fatores.append((d, expoente))
        d += 1 if d == 2 else 2
    if n > 1:
        fatores.append((n, 1))
    return fatores

class Biblioteca:
    def __init__(self):
        self._emprestimos = {}

    def emprestar(self, titulo, usuario):
        if usuario in self._emprestimos and titulo in self._emprestimos[usuario]:
            raise ValueError("usuario ja possui este livro")
        self._emprestimos.setdefault(usuario, []).append(titulo)

    def devolver(self, titulo, usuario):
        if usuario not in self._emprestimos or titulo not in self._emprestimos[usuario]:
            raise KeyError("usuario nao possui este livro")
        self._emprestimos[usuario].remove(titulo)
        if not self._emprestimos[usuario]:
            del self._emprestimos[usuario]

    def livros_do_usuario(self, usuario):
        return list(self._emprestimos.get(usuario, []))

def normalizar_url(url):
    if not isinstance(url, str) or url == "":
        raise ValueError("url deve ser uma string não vazia")
    texto = url.strip()
    if texto == "":
        raise ValueError("url deve ser uma string não vazia")
    if "://" in texto:
        esquema, resto = texto.split("://", 1)
        esquema = esquema.lower()
    else:
        esquema = "http"
        resto = texto
    fim = len(resto)
    for separador in "/?#":
        posicao = resto.find(separador)
        if posicao != -1 and posicao < fim:
            fim = posicao
    host = resto[:fim]
    restante = resto[fim:]
    ponto = restante.find("?")
    if ponto == -1:
        caminho = restante
        query = ""
    else:
        caminho = restante[:ponto]
        query = restante[ponto:]
    cerquilha = caminho.find("#")
    if cerquilha == -1:
        caminho_final = caminho
        fragmento = ""
    else:
        caminho_final = caminho[:cerquilha]
        fragmento = caminho[cerquilha:]
    if caminho_final == "":
        caminho_final = "/"
    host = host.lower()
    resultado = esquema + "://" + host + caminho_final
    if query != "":
        resultado += query
    if fragmento != "":
        resultado += fragmento
    return resultado


def normalizar_arquivo(caminho):
    if not isinstance(caminho, str) or caminho == "":
        raise ValueError("caminho deve ser uma string não vazia")
    texto = caminho.strip()
    if texto == "":
        raise ValueError("caminho deve ser uma string não vazia")
    absoluto = texto.startswith("/")
    partes = texto.split("/")
    resultado = []
    for parte in partes:
        if parte == "" or parte == ".":
            continue
        if parte == "..":
            if resultado:
                resultado.pop()
            continue
        resultado.append(parte)
    if absoluto:
        normalizado = "/" + "/".join(resultado)
    else:
        normalizado = "/".join(resultado)
    if normalizado == "":
        normalizado = "." if not absoluto else "/"
    if absoluto and normalizado != "/" and normalizado.endswith("/"):
        normalizado = normalizado.rstrip("/")
    return normalizado

