class DivisoresMultiplos:
    def __init__(self, n):
        if not isinstance(n, int) or isinstance(n, bool) or n <= 0:
            raise ValueError("n deve ser um inteiro positivo")
        self.n = n

    def divisores(self):
        resultado = []
        for i in range(1, self.n + 1):
            if self.n % i == 0:
                resultado.append(i)
        return resultado

    def multiplos(self, k):
        if not isinstance(k, int) or isinstance(k, bool) or k <= 0:
            raise ValueError("k deve ser um inteiro positivo")
        return [self.n * i for i in range(1, k + 1)]

