def unir_intervalos(intervalos):
    if not isinstance(intervalos, list) or len(intervalos) == 0:
        raise ValueError("lista de intervalos nao pode ser vazia")
    normalizados = []
    for item in intervalos:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("cada intervalo deve conter exatamente dois limites")
        inicio, fim = item
        if not isinstance(inicio, (int, float)) or not isinstance(fim, (int, float)):
            raise ValueError("limites devem ser numeros")
        if inicio > fim:
            raise ValueError("inicio nao pode ser maior que fim")
        normalizados.append([inicio, fim])
    normalizados.sort(key=lambda x: x[0])
    resultado = [normalizados[0]]
    for inicio, fim in normalizados[1:]:
        ultimo = resultado[-1]
        if inicio <= ultimo[1]:
            if fim > ultimo[1]:
                ultimo[1] = fim
        else:
            resultado.append([inicio, fim])
    return resultado

