from math import gcd

def simplificar_fracao(fracao):
    numerador, denominador = fracao
    if denominador == 0:
        raise ValueError("denominador não pode ser zero")
    divisor = gcd(abs(numerador), abs(denominador))
    num = numerador // divisor
    den = denominador // divisor
    if den < 0:
        num = -num
        den = -den
    return (num, den)

def somar_fracoes(fracao1, fracao2):
    n1, d1 = simplificar_fracao(fracao1)
    n2, d2 = simplificar_fracao(fracao2)
    num = n1 * d2 + n2 * d1
    den = d1 * d2
    return simplificar_fracao((num, den))

import hashlib


def escolher_servidor(servidores, chave):
    if not isinstance(servidores, list) or len(servidores) == 0:
        raise ValueError("servidores deve ser uma lista não vazia")
    for s in servidores:
        if not isinstance(s, str) or s == "":
            raise ValueError("cada servidor deve ser uma string não vazia")
    if not isinstance(chave, str) or chave == "":
        raise ValueError("chave deve ser uma string não vazia")

    def _hash(valor):
        return int(hashlib.md5(valor.encode("utf-8")).hexdigest(), 16)

    hash_chave = _hash(chave)
    pares = sorted((_hash(s), s) for s in servidores)

    for h, s in pares:
        if h >= hash_chave:
            return s
    return pares[0][1]

