import math


class Movimento:
    def calcular_tempo(self, distancia, velocidade, aceleracao):
        if velocidade == 0 and aceleracao == 0:
            return None
        if aceleracao == 0:
            return distancia / velocidade
        discriminante = velocidade ** 2 - 4 * 0.5 * aceleracao * (-distancia)
        if discriminante < 0:
            return None
        raiz = math.sqrt(discriminante)
        t1 = (-velocidade + raiz) / (2 * 0.5 * aceleracao)
        t2 = (-velocidade - raiz) / (2 * 0.5 * aceleracao)
        candidatos = [t for t in (t1, t2) if t >= 0]
        if not candidatos:
            return None
        return min(candidatos)

class VersaoConfig:
    def __init__(self, configuracoes_iniciais, versao_inicial=0):
        self.configuracoes = dict(configuracoes_iniciais)
        self.versao = versao_inicial
        self.historico = []

    def definir(self, nome, valor):
        existia = nome in self.configuracoes
        valor_anterior = self.configuracoes.get(nome)
        self.configuracoes[nome] = valor
        self.historico.append((nome, existia, valor_anterior))
        self.versao += 1

    def obter(self, nome):
        if nome not in self.configuracoes:
            raise KeyError(nome)
        return self.configuracoes[nome]

    def desfazer(self):
        if not self.historico:
            raise IndexError("sem historico para desfazer")
        nome, existia, valor_anterior = self.historico.pop()
        if existia:
            self.configuracoes[nome] = valor_anterior
        else:
            del self.configuracoes[nome]
        self.versao -= 1

    def obter_versao(self):
        return self.versao

