def intercala_ordenadas(lista1, lista2):
    for i in range(1, len(lista1)):
        if lista1[i] < lista1[i - 1]:
            raise ValueError("lista1 nao esta ordenada crescentemente")
    for i in range(1, len(lista2)):
        if lista2[i] < lista2[i - 1]:
            raise ValueError("lista2 nao esta ordenada crescentemente")
    resultado = []
    i = 0
    j = 0
    while i < len(lista1) and j < len(lista2):
        if lista1[i] <= lista2[j]:
            resultado.append(lista1[i])
            i += 1
        else:
            resultado.append(lista2[j])
            j += 1
    while i < len(lista1):
        resultado.append(lista1[i])
        i += 1
    while j < len(lista2):
        resultado.append(lista2[j])
        j += 1
    return resultado

