    for valor in linha:
        if not isinstance(valor, int) or isinstance(valor, bool):
            raise TypeError("todos os elementos devem ser inteiros")
        if valor < 0:
            raise ValueError("todos os elementos devem ser nao negativos")

    compactados = [valor for valor in linha if valor != 0]
    fundidos = []
    pular = False
