class SubsequenciaCrescente:
    def __init__(self):
        self._valores = []

    def adicionar(self, valor):
        if isinstance(valor, bool) or not isinstance(valor, int):
            raise ValueError("valor deve ser inteiro")
        if valor < -1000 or valor > 1000:
            raise ValueError("valor fora do intervalo permitido")
        self._valores.append(valor)

    def _calcular(self):
        n = len(self._valores)
        dp = [1] * n
        prev = [-1] * n
        for i in range(n):
            for j in range(i):
                if self._valores[j] < self._valores[i] and dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
                    prev[i] = j
        return dp, prev

    def tamanho(self):
        if not self._valores:
            raise RuntimeError("nenhum valor adicionado")
        dp, _ = self._calcular()
        return max(dp)

    def reconstruir(self):
        if not self._valores:
            raise RuntimeError("nenhum valor adicionado")
        dp, prev = self._calcular()
        melhor_tamanho = max(dp)
        melhor_fim = min(i for i, v in enumerate(dp) if v == melhor_tamanho)
        seq = []
        i = melhor_fim
        while i != -1:
            seq.append(self._valores[i])
            i = prev[i]
        seq.reverse()
        return seq

