import math


def converter_angulo(valor, unidade_origem, unidade_destino):
    validas = ("graus", "radianos")
    if not isinstance(valor, (int, float)):
        raise TypeError("valor deve ser int ou float")
    if unidade_origem not in validas:
        raise ValueError("unidade_origem invalida")
    if unidade_destino not in validas:
        raise ValueError("unidade_destino invalida")
    if unidade_origem == unidade_destino:
        return valor
    if unidade_origem == "graus":
        return math.radians(valor)
    return math.degrees(valor)

def raiz_inteira(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n deve ser um inteiro")
    if n < 0:
        raise ValueError("n deve ser nao negativo")
    if n < 2:
        return 0
    baixo = 0
    alto = n // 2 + 1
    while baixo <= alto:
        meio = (baixo + alto) // 2
        quadrado = meio * meio
        if quadrado == n:
            return meio
        if quadrado < n:
            baixo = meio + 1
        else:
            alto = meio - 1
    return alto

def hex_para_rgb(cor):
