        raise ValueError("Cor deve ter exatamente 7 caracteres")
    hex_digitos = "0123456789abcdefABCDEF"
    for caractere in cor[1:]:
        if caractere not in hex_digitos:
            raise ValueError("Caracteres inválidos na cor hexadecimal")
    r = int(cor[1:3], 16)
    g = int(cor[3:5], 16)
    b = int(cor[5:7], 16)
    return (r, g, b)

