    if coluna < "a" or coluna > "h" or linha < "1" or linha > "8":
        raise ValueError("Posição inválida")
    x = ord(coluna) - ord("a")
    y = int(linha) - 1
    deslocamentos = [
        (2, 1), (2, -1), (-2, 1), (-2, -1),
        (1, 2), (1, -2), (-1, 2), (-1, -2)
    ]
    resultado = []
    for dx, dy in deslocamentos:
        nx = x + dx
        ny = y + dy
        if 0 <= nx < 8 and 0 <= ny < 8:
            resultado.append(chr(ord("a") + nx) + str(ny + 1))
    return resultado

