class DistanciaPontos:
    def __init__(self, ponto1, ponto2):
        self._validar_ponto(ponto1)
        self._validar_ponto(ponto2)
        self.ponto1 = ponto1
        self.ponto2 = ponto2

    def _validar_ponto(self, ponto):
        if not isinstance(ponto, tuple) or len(ponto) != 2:
            raise ValueError("ponto deve ser uma tupla de dois números")
        if not all(isinstance(coord, (int, float)) for coord in ponto):
            raise ValueError("coordenadas devem ser números")

    def distancia(self):
        x1, y1 = self.ponto1
        x2, y2 = self.ponto2
        dx = x2 - x1
        dy = y2 - y1
        return round((dx * dx + dy * dy) ** 0.5, 2)

def calcula_desconto_progressivo(preco, quantidade):
    if not isinstance(preco, (int, float)) or isinstance(preco, bool) or preco <= 0:
        raise ValueError("preco invalido")
    if not isinstance(quantidade, int) or isinstance(quantidade, bool) or quantidade < 0:
        raise ValueError("quantidade invalida")
    if quantidade >= 50:
        desconto = 0.15
    elif quantidade >= 20:
        desconto = 0.10
    elif quantidade >= 10:
        desconto = 0.05
    else:
        desconto = 0.0
    return preco * quantidade * (1 - desconto)

