class PontoViagem:
    def __init__(self):
        self._x = 0.0
        self._y = 0.0
        self._total = 0.0

    def adicionar_ponto(self, x, y):
        if not isinstance(x, (int, float)) or isinstance(x, bool):
            raise TypeError("x deve ser um número")
        if not isinstance(y, (int, float)) or isinstance(y, bool):
            raise TypeError("y deve ser um número")
        dx = x - self._x
        dy = y - self._y
        self._total += math.hypot(dx, dy)
        self._x = float(x)
        self._y = float(y)

    def distancia_total(self):
        return float(self._total)

    def reset(self):
        self._x = 0.0
        self._y = 0.0
        self._total = 0.0

