class RankingAlunos:
    def __init__(self):
        self._alunos = []
        self._indices = {}

    def adicionar(self, aluno, nota):
        if not isinstance(aluno, str) or aluno == '':
            raise ValueError('aluno invalido')
        if aluno in self._indices:
            raise ValueError('aluno ja existe')
        if not isinstance(nota, (int, float)) or isinstance(nota, bool):
            raise ValueError('nota invalida')
        if nota < 0 or nota > 100:
            raise ValueError('nota fora do intervalo')
        self._indices[aluno] = len(self._alunos)
        self._alunos.append((aluno, nota))

    def listar(self, criterio='nota'):
        if criterio == 'nota':
            ordenados = sorted(self._alunos, key=lambda item: item[1], reverse=True)
        elif criterio == 'nome':
            ordenados = sorted(self._alunos, key=lambda item: item[0])
        elif criterio == 'insercao':
            ordenados = self._alunos
        else:
            raise ValueError('criterio desconhecido')
        return [nome for nome, _ in ordenados]

def tribonacci(n):
    if isinstance(n, bool):
        raise ValueError("n não pode ser booleano")
    if not isinstance(n, int):
        raise TypeError("n deve ser inteiro")
    if n < 0:
        raise ValueError("n não pode ser negativo")
    if n == 0:
        return 0
    if n == 1 or n == 2:
        return 1
    a, b, c = 0, 1, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c

