class TabelaTexto:
    def __init__(self, colunas):
        self.colunas = list(colunas)
        self.linhas = []
        self.larguras = [len(str(c)) for c in self.colunas]

    def adicionar_linha(self, valores):
        if len(valores) != len(self.colunas):
            raise ValueError("número de valores diferente do número de colunas")
        linha = [str(v) for v in valores]
        self.linhas.append(linha)
        for i, celula in enumerate(linha):
            if len(celula) > self.larguras[i]:
                self.larguras[i] = len(celula)

    def renderizar(self):
        partes_cabecalho = [self.colunas[i].ljust(self.larguras[i]) for i in range(len(self.colunas))]
        linhas_saida = ["  ".join(partes_cabecalho)]
        for linha in self.linhas:
            partes = [linha[i].ljust(self.larguras[i]) for i in range(len(linha))]
            linhas_saida.append("  ".join(partes))
        return "\n".join(linhas_saida)

def media_movel(valores, tamanho):
    if not valores:
        raise ValueError("lista nao pode estar vazia")
    if tamanho <= 0:
        raise ValueError("tamanho deve ser positivo")
    if tamanho > len(valores):
        raise ValueError("tamanho nao pode exceder o comprimento da lista")

    resultado = []
    soma = sum(valores[:tamanho])
    resultado.append(soma / tamanho)

    for i in range(tamanho, len(valores)):
        soma += valores[i] - valores[i - tamanho]
        resultado.append(soma / tamanho)

    return resultado

class Completador:
    def __init__(self):
        self._raiz = {}
        self._fim = '#'

    def inserir(self, palavra):
        if not isinstance(palavra, str) or palavra == '':
            raise ValueError('palavra inválida')
        no = self._raiz
        for caractere in palavra:
            no = no.setdefault(caractere, {})
        no[self._fim] = True

    def completar(self, prefixo):
        if not isinstance(prefixo, str) or prefixo == '':
            raise ValueError('prefixo inválido')
        no = self._raiz
        for caractere in prefixo:
            if caractere not in no:
                return []
            no = no[caractere]
        resultados = []
        pilha = [(no, prefixo)]
        while pilha:
            atual, caminho = pilha.pop()
            if self._fim in atual:
                resultados.append(caminho)
            for caractere, filho in atual.items():
                if caractere != self._fim:
                    pilha.append((filho, caminho + caractere))
        return sorted(resultados)[:5]

from math import gcd


def somar_fracoes(a, b):
    if not isinstance(a, tuple) or not isinstance(b, tuple):
        raise ValueError("Ambos os argumentos devem ser tuplas")
    if len(a) != 2 or len(b) != 2:
        raise ValueError("Cada fração deve ter exatamente dois elementos")
    num1, den1 = a
    num2, den2 = b
    if not isinstance(num1, int) or not isinstance(den1, int):
        raise ValueError("Numerador e denominador devem ser inteiros")
    if not isinstance(num2, int) or not isinstance(den2, int):
        raise ValueError("Numerador e denominador devem ser inteiros")
    if den1 == 0 or den2 == 0:
        raise ValueError("Denominador não pode ser zero")

    num = num1 * den2 + num2 * den1
    den = den1 * den2

    if den < 0:
        num = -num
        den = -den

    divisor = gcd(abs(num), abs(den))
    num //= divisor
    den //= divisor

    return (num, den)

