class Potencias:
    def raiz_inteira(self, n):
        if not isinstance(n, int) or isinstance(n, bool) or n < 0:
            raise ValueError("n deve ser um inteiro nao negativo")
        if n == 0:
            return 0
        baixo, alto = 0, n
        while baixo <= alto:
            meio = (baixo + alto) // 2
            quadrado = meio * meio
            if quadrado == n:
                return meio
            elif quadrado < n:
                baixo = meio + 1
            else:
                alto = meio - 1
        return alto

    def potencia(self, base, expoente):
        if not isinstance(base, int) or isinstance(base, bool):
            raise ValueError("base deve ser um inteiro")
        if not isinstance(expoente, int) or isinstance(expoente, bool) or expoente < 0:
            raise ValueError("expoente deve ser um inteiro nao negativo")
        resultado = 1
        for _ in range(expoente):
            resultado *= base
        return resultado

def calcular_irpf(rendimento_anual):
    if rendimento_anual < 0:
        raise ValueError("Rendimento anual não pode ser negativo.")
    if rendimento_anual <= 22847.76:
        return 0.0
    if rendimento_anual <= 33919.80:
        return rendimento_anual * 0.075 - 1713.58
    return rendimento_anual * 0.15 - 4254.35

from datetime import date


def dias_entre_datas(data1, data2):
    """Calcula o número absoluto de dias entre duas datas (ano, mes, dia)."""

    def validar_data(data):
        if not isinstance(data, tuple) or len(data) != 3:
            raise ValueError("A data deve ser uma tupla com exatamente três elementos.")
        ano, mes, dia = data
        if not all(isinstance(x, int) and not isinstance(x, bool) for x in (ano, mes, dia)):
            raise ValueError("Todos os elementos da data devem ser inteiros.")
        try:
            date(ano, mes, dia)
        except ValueError:
            raise ValueError(f"Data inválida: {data}")

    validar_data(data1)
    validar_data(data2)

    d1 = date(*data1)
    d2 = date(*data2)
    return abs((d2 - d1).days)

