class GerenciadorSessoes:
    def agrupar(self, eventos, intervalo_minutos):
        if not isinstance(intervalo_minutos, int) or isinstance(intervalo_minutos, bool):
            raise ValueError("intervalo_minutos deve ser inteiro não negativo")
        if intervalo_minutos < 0:
            raise ValueError("intervalo_minutos deve ser não negativo")
        for e in eventos:
            if not isinstance(e, int) or isinstance(e, bool):
                raise ValueError("todos os eventos devem ser inteiros não negativos")
            if e < 0:
                raise ValueError("todos os eventos devem ser inteiros não negativos")
        if not eventos:
            return []
        ordenados = sorted(eventos)
        sessoes = []
        inicio = ordenados[0]
        fim = ordenados[0]
        for atual in ordenados[1:]:
            if atual - fim < intervalo_minutos:
                fim = atual
            else:
                sessoes.append((inicio, fim))
                inicio = atual
                fim = atual
        sessoes.append((inicio, fim))
        return sessoes

