    timestamp, ip, nivel, mensagem = partes
    if nivel not in ("INFO", "WARNING", "ERROR"):
        raise ValueError("nivel de log invalido")
    return {
        "timestamp": timestamp,
        "ip": ip,
        "nivel": nivel,
        "mensagem": mensagem,
    }


def analyze_logs(entradas):
    contagens = {"INFO": 0, "WARNING": 0, "ERROR": 0}
    erros = []
    for linha in entradas:
        try:
            entrada = parse_log_entry(linha)
        except ValueError:
            continue
        contagens[entrada["nivel"]] += 1
        if entrada["nivel"] == "ERROR":
            erros.append(entrada["mensagem"])
    return {"contagens": contagens, "erros": erros}

