        raise ValueError("palavras_chave deve ser uma lista")
    normalizadas = []
    for palavra in palavras_chave:
        palavra_normalizada = palavra.strip().lower()
        if palavra_normalizada:
            normalizadas.append(palavra_normalizada)
    return normalizadas


