    def __init__(self):
        self._dados = {}

    def colocar(self, chave, valor, ttl_segundos):
        if ttl_segundos <= 0:
            raise ValueError("ttl_segundos deve ser positivo")
        self._dados[chave] = (valor, time.time() + ttl_segundos)

    def obter(self, chave):
        entrada = self._dados.get(chave)
        if entrada is None:
            return None
        valor, expira_em = entrada
        if time.time() > expira_em:
            return None
        return valor

def conversao_base(valor, base_origem, base_destino):
    if not (2 <= base_origem <= 36):
        raise ValueError("base_origem invalida")
    if not (2 <= base_destino <= 36):
        raise ValueError("base_destino invalida")
    try:
        numero = int(valor, base_origem)
    except (ValueError, TypeError):
        raise ValueError("valor invalido para a base origem")
    if numero == 0:
        return "0"
    negativo = numero < 0
    numero = abs(numero)
    digitos = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    resultado = []
    while numero > 0:
        resultado.append(digitos[numero % base_destino])
        numero //= base_destino
    if negativo:
        resultado.append("-")
    return "".join(reversed(resultado))

class PilhaEstatica:
    def __init__(self, capacidade):
        self.capacidade = capacidade
        self.itens = []

    def empilhar(self, item):
        if len(self.itens) >= self.capacidade:
            raise ValueError("Pilha cheia")
        self.itens.append(item)

    def desempilhar(self):
        if len(self.itens) == 0:
            raise IndexError("Pilha vazia")
        return self.itens.pop()

def filtra_produtos(lista, min_preco, max_preco, categoria):
    if min_preco > max_preco:
        raise ValueError("min_preco não pode ser maior que max_preco")
    resultado = []
    for item in lista:
        if item["categoria"] == categoria and min_preco <= item["preco"] <= max_preco:
            resultado.append(item)
    return resultado

class Codificador:
    def __init__(self, chave):
        if not isinstance(chave, int) or isinstance(chave, bool):
            raise ValueError("chave deve ser um inteiro")
        self.chave = chave

    def codificar(self, texto):
        if not isinstance(texto, str):
            raise ValueError("texto deve ser uma string")
        resultado = []
        for caractere in texto:
            if 'a' <= caractere <= 'z':
                deslocado = (ord(caractere) - ord('a') + self.chave) % 26
                resultado.append(chr(ord('a') + deslocado))
            elif 'A' <= caractere <= 'Z':
                deslocado = (ord(caractere) - ord('A') + self.chave) % 26
                resultado.append(chr(ord('A') + deslocado))
            else:
                resultado.append(caractere)
        return ''.join(resultado)

    def decodificar(self, texto):
        if not isinstance(texto, str):
            raise ValueError("texto deve ser uma string")
        resultado = []
        for caractere in texto:
            if 'a' <= caractere <= 'z':
                deslocado = (ord(caractere) - ord('a') - self.chave) % 26
                resultado.append(chr(ord('a') + deslocado))
            elif 'A' <= caractere <= 'Z':
                deslocado = (ord(caractere) - ord('A') - self.chave) % 26
                resultado.append(chr(ord('A') + deslocado))
            else:
                resultado.append(caractere)
        return ''.join(resultado)

def maiores_elementos(lista, n):
