def mapeia_erro_http(erro):
    mapeamento = {
        ValueError: {"status": 400, "mensagem": "Requisição inválida"},
        KeyError: {"status": 404, "mensagem": "Recurso não encontrado"},
        TypeError: {"status": 500, "mensagem": "Erro interno do servidor"},
    }
    tipo = type(erro)
    if tipo not in mapeamento:
