import math


def formata_real(valor):
    if isinstance(valor, bool) or not isinstance(valor, (int, float)):
        raise TypeError("valor deve ser int ou float")
    if not math.isfinite(valor):
        raise ValueError("valor deve ser finito")
    inteiro = int(abs(valor))
    centavos = round((abs(valor) - inteiro) * 100)
    if centavos == 100:
        inteiro += 1
        centavos = 0
    partes = []
    if inteiro == 0:
        partes.append("0")
    else:
        while inteiro > 0:
            partes.append(str(inteiro % 1000).zfill(3) if inteiro >= 1000 else str(inteiro % 1000))
            inteiro //= 1000
    inteiro_formatado = ".".join(reversed(partes))
    sinal = "-" if valor < 0 and (inteiro_formatado != "0" or centavos != 0) else ""
    return f"R$ {sinal}{inteiro_formatado},{centavos:02d}"

def posicoes_empate(valores):
    if not isinstance(valores, list) or len(valores) == 0:
        raise ValueError("lista não pode estar vazia")
    for v in valores:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("todos os elementos devem ser números")

    pares = sorted(enumerate(valores), key=lambda item: item[1], reverse=True)
    resultado = [0] * len(valores)
    posicao = 1
    i = 0
    while i < len(pares):
        j = i
        while j < len(pares) and pares[j][1] == pares[i][1]:
            j += 1
        for k in range(i, j):
            resultado[pares[k][0]] = posicao
        posicao += (j - i)
        i = j
    return resultado


def coloca_na_posicao(valores, alvo):
    posicoes = posicoes_empate(valores)
    dicionario = {}
    for indice, valor in enumerate(valores):
        dicionario[valor] = posicoes[indice]
    if alvo not in dicionario:
        raise ValueError("alvo não encontrado na lista")
    return {"posicoes": dicionario, "posicao_alvo": dicionario[alvo]}

def calcular_preco_venda(custo, margem):
    if not isinstance(custo, (int, float)) or isinstance(custo, bool):
        raise ValueError("O custo deve ser um número válido.")
    if not isinstance(margem, (int, float)) or isinstance(margem, bool):
        raise ValueError("A margem deve ser um número válido.")
    if custo < 0:
        raise ValueError("O custo não pode ser negativo.")
    if margem < 0 or margem > 100:
        raise ValueError("A margem deve estar entre 0% e 100%.")
    return custo * (1 + margem / 100)

class UnionIntervalos:
    def __init__(self):
        self._intervalos = []

    def adicionar(self, ini, fim):
        if not isinstance(ini, int) or not isinstance(fim, int):
            raise TypeError("inicio e fim devem ser inteiros")
        if ini > fim:
            raise ValueError("inicio deve ser menor ou igual a fim")
        novo = [ini, fim]
        resultado = []
        inserido = False
        for inicio, termino in self._intervalos:
            if termino < novo[0] - 1:
                resultado.append([inicio, termino])
            elif novo[1] < inicio - 1:
                if not inserido:
                    resultado.append(novo)
                    inserido = True
                resultado.append([inicio, termino])
            else:
                novo[0] = min(novo[0], inicio)
                novo[1] = max(novo[1], termino)
        if not inserido:
            resultado.append(novo)
        self._intervalos = [tuple(par) for par in resultado]

    def lista_intervalos(self):
        return list(self._intervalos)

    def contem(self, valor):
        if not isinstance(valor, int):
            raise TypeError("valor deve ser inteiro")
        for inicio, termino in self._intervalos:
            if inicio <= valor <= termino:
                return True
        return False

class Primos:
    def __init__(self):
        self._primos = set()

    @staticmethod
    def eh_primo(numero):
        if not isinstance(numero, int) or isinstance(numero, bool):
            raise ValueError("numero deve ser inteiro")
        if numero < 2:
            raise ValueError("numero deve ser maior ou igual a 2")
        if numero == 2:
            return True
        if numero % 2 == 0:
            return False
        limite = int(numero ** 0.5) + 1
        for i in range(3, limite, 2):
            if numero % i == 0:
                return False
        return True

    def adicionar(self, numero):
        if isinstance(numero, bool) or not isinstance(numero, int):
            return
        if self.eh_primo(numero):
            self._primos.add(numero)

    def contar(self):
        return len(self._primos)

    def listar(self):
        return sorted(self._primos)

def ordenar_pessoas(pessoas):
    for pessoa in pessoas:
        if pessoa[1] < 0:
