    return sorted(pessoas, key=lambda p: p[1])

def agrupar_por_inatividade(eventos, limite):
    if not isinstance(eventos, list):
        raise ValueError("eventos deve ser uma lista")
    if not isinstance(limite, int) or isinstance(limite, bool) or limite < 0:
        raise ValueError("limite deve ser um inteiro não negativo")
    for e in eventos:
        if not isinstance(e, int) or isinstance(e, bool):
            raise ValueError("todos os eventos devem ser inteiros")
    if not eventos:
        return []
    sessoes = []
    atual = [eventos[0]]
    for i in range(1, len(eventos)):
        if eventos[i] - eventos[i - 1] <= limite:
            atual.append(eventos[i])
        else:
            sessoes.append(atual)
            atual = [eventos[i]]
    sessoes.append(atual)
    return sessoes

def totais_sessao(sessoes):
    if not isinstance(sessoes, list):
        raise ValueError("sessoes deve ser uma lista")
    resultado = []
    for sessao in sessoes:
        if not isinstance(sessao, list):
            raise ValueError("cada sessão deve ser uma lista")
        for e in sessao:
            if not isinstance(e, int) or isinstance(e, bool):
                raise ValueError("todos os elementos das sessões devem ser inteiros")
        resultado.append(len(sessao))
    return resultado

def comissao_por_faixa(valor):
    if isinstance(valor, bool) or not isinstance(valor, (int, float)):
        raise TypeError("valor deve ser int ou float")
    if valor < 0:
        raise ValueError("valor não pode ser negativo")
    if valor < 1000:
        return valor * 0.05
    if valor <= 5000:
        return valor * 0.07
    return valor * 0.10


def comissao_total(valores):
    if not isinstance(valores, list):
        raise TypeError("valores deve ser uma lista")
    total = 0.0
    for item in valores:
        total += comissao_por_faixa(item)
    return total

def normalizar_intervalo(inicio, fim):
    if not isinstance(inicio, (int, float)) or not isinstance(fim, (int, float)):
        raise ValueError("início e fim devem ser números")
    return (inicio, fim) if inicio <= fim else (fim, inicio)


def intervalos_sobrepostos(intervalo1, intervalo2):
    if (not isinstance(intervalo1, (list, tuple)) or len(intervalo1) != 2 or
            not isinstance(intervalo2, (list, tuple)) or len(intervalo2) != 2):
        raise ValueError("cada intervalo deve conter exatamente dois elementos")
    a_inicio, a_fim = normalizar_intervalo(intervalo1[0], intervalo1[1])
    b_inicio, b_fim = normalizar_intervalo(intervalo2[0], intervalo2[1])
    return a_inicio <= b_fim and b_inicio <= a_fim

class Trie:
    def __init__(self):
        self._raiz = {}
        self._fim = '#'

    def inserir(self, palavra):
        if not isinstance(palavra, str) or palavra == '':
            raise ValueError("palavra invalida")
        no = self._raiz
        for caractere in palavra:
            no = no.setdefault(caractere, {})
        no[self._fim] = True

    def sugerir(self, prefixo):
        if not isinstance(prefixo, str) or prefixo == '':
            raise ValueError("prefixo invalido")
        no = self._raiz
        for caractere in prefixo:
            if caractere not in no:
                return []
            no = no[caractere]
        resultado = []
        pilha = [(no, prefixo)]
        while pilha:
            atual, caminho = pilha.pop()
            if self._fim in atual:
                resultado.append(caminho)
            for caractere in atual:
                if caractere != self._fim:
                    pilha.append((atual[caractere], caminho + caractere))
        resultado.sort()
        return resultado

def iniciais_de_nome(nome):
    if not nome or not nome.strip():
        raise ValueError("nome não pode ser vazio ou conter apenas espaços")
    partes = nome.split()
    return ". ".join(parte[0].upper() for parte in partes) + "."


def abreviar_nome(nome, sobrenome_alvo):
    if not nome or not nome.strip():
        raise ValueError("nome não pode ser vazio ou conter apenas espaços")
    partes = nome.split()
    if sobrenome_alvo not in partes:
        raise ValueError("sobrenome alvo não encontrado no nome")
    indice = partes.index(sobrenome_alvo)
    prefixo = partes[:indice]
    iniciais = ". ".join(parte[0].upper() for parte in prefixo)
    if iniciais:
        return iniciais + ". " + sobrenome_alvo
    return sobrenome_alvo

def posicao_competidor(pontuacoes, valor):
    if valor not in pontuacoes:
        raise ValueError("valor não encontrado na lista")
    maior = 0
    for p in pontuacoes:
        if p > valor:
            maior += 1
    return maior + 1


def posicoes_todos(pontuacoes):
    resultado = {}
    for valor in pontuacoes:
        if valor not in resultado:
            resultado[valor] = posicao_competidor(pontuacoes, valor)
    return resultado

class DetectorPicos:
    def __init__(self, valores):
        self.valores = list(valores)

    def detectar(self, largura_minima):
        if not isinstance(largura_minima, int) or isinstance(largura_minima, bool) or largura_minima <= 0:
            raise ValueError("largura_minima deve ser um inteiro positivo")

        intervalos = []
        inicio = None

        for i, v in enumerate(self.valores):
            if v > 0:
                if inicio is None:
                    inicio = i
            else:
                if inicio is not None:
                    if i - inicio >= largura_minima:
                        intervalos.append((inicio, i - 1))
                    inicio = None

        if inicio is not None and len(self.valores) - inicio >= largura_minima:
            intervalos.append((inicio, len(self.valores) - 1))

        return intervalos

