class JurosSimples:
    def __init__(self, taxa_anual, tempo_anos):
        if taxa_anual < 0:
            raise ValueError("taxa_anual nao pode ser negativa")
        if tempo_anos < 0:
            raise ValueError("tempo_anos nao pode ser negativo")
        self.taxa_anual = taxa_anual
        self.tempo_anos = tempo_anos

    def montante(self, valor):
        if valor < 0:
            raise ValueError("valor nao pode ser negativo")
        juros = valor * self.taxa_anual * self.tempo_anos
        return round(valor + juros, 2)

    def juros(self, valor):
        if valor < 0:
            raise ValueError("valor nao pode ser negativo")
        return round(valor * self.taxa_anual * self.tempo_anos, 2)

class Inversor:
    def __init__(self):
        self.historico = []

    def inverte_palavra(self, texto):
        if not isinstance(texto, str) or texto == "":
            raise ValueError("texto deve ser uma string nao vazia")
        self.historico.append(texto)
        return texto[::-1]

    def inverte_frase(self, frase):
        if not isinstance(frase, str) or frase == "":
            raise ValueError("frase deve ser uma string nao vazia")
        palavras = frase.split(" ")
        for palavra in palavras:
            if not any(caractere.isalnum() for caractere in palavra):
                raise ValueError("todas as palavras devem ter ao menos um caractere alfanumerico")
        palavras_invertidas = [self.inverte_palavra(palavra) for palavra in palavras]
        resultado = " ".join(palavras_invertidas[::-1])
        self.historico.append(frase)
        return resultado

class BuscadorTexto:
    def __init__(self, texto):
        if not isinstance(texto, str):
            raise ValueError("texto deve ser uma string")
        self._palavras = texto.split()

    def buscar(self, palavra):
        if not isinstance(palavra, str) or palavra == "":
            raise ValueError("palavra deve ser uma string não vazia")
        return palavra in self._palavras

    def contar(self, palavra):
        if not isinstance(palavra, str) or palavra == "":
            raise ValueError("palavra deve ser uma string não vazia")
        return self._palavras.count(palavra)

class GeracaoVida:
    def __init__(self, grade):
        if not grade or not all(len(linha) == len(grade[0]) for linha in grade):
            raise ValueError("Grade inválida: deve ser não vazia e retangular")
        self.grade = [linha[:] for linha in grade]
        self.linhas = len(grade)
        self.colunas = len(grade[0])

    def _vizinhos_vivos(self, linha, coluna):
        contagem = 0
        for dl in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dl == 0 and dc == 0:
                    continue
                nl, nc = linha + dl, coluna + dc
                if 0 <= nl < self.linhas and 0 <= nc < self.colunas:
                    contagem += self.grade[nl][nc]
        return contagem

    def proxima_geracao(self):
        nova = [[0] * self.colunas for _ in range(self.linhas)]
        for l in range(self.linhas):
            for c in range(self.colunas):
                vizinhos = self._vizinhos_vivos(l, c)
                if self.grade[l][c] == 1:
                    nova[l][c] = 1 if vizinhos in (2, 3) else 0
                else:
                    nova[l][c] = 1 if vizinhos == 3 else 0
        self.grade = nova
        return self.grade

def somatorio_condicional(valores, limite):
    total = 0
    for valor in valores:
        if not isinstance(valor, (int, float)):
            raise ValueError("todos os elementos devem ser numeros")
        if valor > limite:
            total += valor
    return total

def ordenar_por_varias_chaves(dados, chaves):
    if not isinstance(dados, list):
        raise ValueError("dados deve ser uma lista")
    if not isinstance(chaves, (list, tuple)):
        raise ValueError("chaves deve ser uma lista ou tupla")
    for item in dados:
        if not isinstance(item, dict):
            raise ValueError("cada item deve ser um dicionario")
        for chave in chaves:
            if chave not in item:
                raise ValueError("chave ausente em um item")
    return sorted(dados, key=lambda item: tuple(item[chave] for chave in chaves))

def vizinhos_pares(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n deve ser um inteiro")
    if n % 2 == 0:
        return (n, n)
    return (n - 1, n + 1)

def eh_primo(x):
    if x < 2:
        return False
    if x % 2 == 0:
        return x == 2
    i = 3
    while i * i <= x:
        if x % i == 0:
            return False
        i += 2
    return True

def soma_primos_ate(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n deve ser um inteiro")
    if n < 0:
        raise ValueError("n nao pode ser negativo")
    total = 0
    for x in range(2, n + 1):
        if eh_primo(x):
            total += x
    return total

def agrupa_por_chave(lista_de_pares):
    grupos = {}
    for item in lista_de_pares:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError("cada item deve ser uma tupla de dois elementos")
        chave, valor = item
        grupos.setdefault(chave, []).append(valor)
    return grupos

def maximos_por_grupo(lista_de_pares):
    if not lista_de_pares:
        raise ValueError("lista não pode estar vazia")
    grupos = agrupa_por_chave(lista_de_pares)
    return {chave: max(valores) for chave, valores in grupos.items()}

