def eh_valida(data):
    if not isinstance(data, tuple) or len(data) != 3:
        raise ValueError("data deve ser uma tupla de três inteiros")
    dia, mes, ano = data
    if not all(isinstance(x, int) for x in (dia, mes, ano)):
        raise ValueError("dia, mes e ano devem ser inteiros")
    if not (1 <= dia <= 31 and 1 <= mes <= 12 and 1 <= ano <= 9999):
        raise ValueError("valores fora do intervalo permitido")
    dias_por_mes = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if mes == 2 and _eh_bissexto(ano):
        limite = 29
    else:
        limite = dias_por_mes[mes - 1]
    return dia <= limite


def _eh_bissexto(ano):
    return ano % 4 == 0 and (ano % 100 != 0 or ano % 400 == 0)


def _ordinal(data):
    dia, mes, ano = data
    dias_por_mes = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    total = dia
    for m in range(1, mes):
        if m == 2 and _eh_bissexto(ano):
            total += 29
        else:
            total += dias_por_mes[m - 1]
    anos_antes = ano - 1
    total += anos_antes * 365 + anos_antes // 4 - anos_antes // 100 + anos_antes // 400
    return total


def dias_entre(data1, data2):
    if not eh_valida(data1) or not eh_valida(data2):
        raise ValueError("ambas as datas devem ser válidas")
    return abs(_ordinal(data1) - _ordinal(data2))

