NOTAS = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]


def _parse_nota(nota):
    if not isinstance(nota, str) or len(nota) < 2:
        raise ValueError("Nota inválida")
    nome = nota[:-1]
    oitava_str = nota[-1]
    if nome not in NOTAS:
        raise ValueError("Nota inválida")
    if not oitava_str.isdigit():
        raise ValueError("Nota inválida")
    oitava = int(oitava_str)
    return nome, oitava


def nota_para_frequencia(nota):
    nome, oitava = _parse_nota(nota)
    semitons = oitava * 12 + NOTAS.index(nome) - 4 * 12 - 9
    return 440.0 * (2.0 ** (semitons / 12.0))


def frequencia_para_nota(frequencia):
    if not isinstance(frequencia, (int, float)) or isinstance(frequencia, bool):
        raise ValueError("Frequência inválida")
    if frequencia <= 0:
        raise ValueError("Frequência inválida")
    semitons = round(12.0 * __import__("math").log2(frequencia / 440.0))
    indice_som = (semitons + 4 * 12 + 9) % 12
    oitava = (semitons + 4 * 12 + 9) // 12
    return NOTAS[indice_som] + str(oitava)

class InterpretadorCSV:
    def __init__(self, texto_csv):
        linhas = texto_csv.splitlines()
        self.cabecalho = linhas[0].split(",") if linhas else []
        self.linhas_dados = [linha.split(",") for linha in linhas[1:]]

    def linha_para_dicionario(self, indice):
        if not isinstance(indice, int) or isinstance(indice, bool):
            raise ValueError("Índice inválido")
        if indice < 0 or indice >= len(self.linhas_dados):
            raise ValueError("Índice fora do intervalo de linhas de dados")
        return dict(zip(self.cabecalho, self.linhas_dados[indice]))

    def coluna_para_lista(self, nome_coluna):
        if nome_coluna not in self.cabecalho:
            raise ValueError("Coluna não encontrada no cabeçalho")
        indice_coluna = self.cabecalho.index(nome_coluna)
        return [linha[indice_coluna] for linha in self.linhas_dados]

    def filtrar_linhas(self, predicado):
        if not callable(predicado):
            raise TypeError("O predicado deve ser chamável")
        return [linha for linha in self.linhas_dados if predicado(dict(zip(self.cabecalho, linha)))]

