class DuracaoHM:
    def __init__(self, horas, minutos):
        if not isinstance(horas, int) or not isinstance(minutos, int):
            raise TypeError("horas e minutos devem ser inteiros")
        total = horas * 60 + minutos
        self.horas = total // 60
        self.minutos = total % 60

    def somar(self, outra):
        if not isinstance(outra, DuracaoHM):
            raise TypeError("somar requer uma DuracaoHM")
        total = self.horas * 60 + self.minutos + outra.horas * 60 + outra.minutos
        return DuracaoHM(total // 60, total % 60)

    def subtrair(self, outra):
        if not isinstance(outra, DuracaoHM):
            raise TypeError("subtrair requer uma DuracaoHM")
        total = self.horas * 60 + self.minutos - (outra.horas * 60 + outra.minutos)
        return DuracaoHM(total // 60, total % 60)

    def str_formatada(self):
        return f"{self.horas}h {self.minutos:02d}m"

def detectar_picos(requisicoes, limiar, janela):
    if not isinstance(limiar, int):
        raise ValueError("limiar deve ser inteiro")
    if janela < 1:
        raise ValueError("janela deve ser pelo menos 1")
    picos = []
    n = len(requisicoes)
    for i in range(n):
        if requisicoes[i] <= limiar:
            continue
        if i - janela >= 0 and requisicoes[i] <= requisicoes[i - janela]:
            continue
        if i + janela < n and requisicoes[i] <= requisicoes[i + janela]:
            continue
        picos.append(i)
    return picos

