def termo_variado(n, a, b, k):
    if not isinstance(a, int) or not isinstance(b, int):
        raise ValueError("a e b devem ser inteiros")
    if n < 1:
        raise ValueError("n deve ser maior ou igual a 1")
    if k <= 0:
        raise ValueError("k deve ser maior que 0")
    if n == 1:
        return a
    if n == 2:
        return b
    t_prev2 = a
    t_prev1 = b
    for _ in range(3, n + 1):
        t_atual = t_prev1 + k * t_prev2
        t_prev2 = t_prev1
        t_prev1 = t_atual
    return t_prev1

class Frequencias:
