def soma_quadrados_digitos(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 0:
        raise ValueError("n deve ser um inteiro não negativo")
    soma = 0
    while n > 0:
        digito = n % 10
        soma += digito * digito
        n //= 10
    return soma

def eh_feliz(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 0:
        raise ValueError("n deve ser um inteiro não negativo")
    visto = set()
    atual = n
    while atual != 1 and atual not in visto:
        visto.add(atual)
        atual = soma_quadrados_digitos(atual)
    return atual == 1

