NOTAS_VALIDAS = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]


class Afinador:
    def __init__(self, nota_inicial, referencia_a4=440.0):
        self.referencia_a4 = float(referencia_a4)
        self.nota = self._validar_nota(nota_inicial)

    def _validar_nota(self, nota):
        if nota not in NOTAS_VALIDAS:
            raise ValueError("nota invalida")
        return nota

    def _indice_da_nota(self, nota):
        return NOTAS_VALIDAS.index(nota)

    def frequencia_da_nota(self, nota):
        indice = self._indice_da_nota(nota)
        indice_a4 = NOTAS_VALIDAS.index("A")
        oitava_nota = 4
        oitava_a4 = 4
        semitons_relativo_a4 = (indice - indice_a4) + (oitava_nota - oitava_a4) * 12
        return round(self.referencia_a4 * (2 ** (semitons_relativo_a4 / 12)), 2)

    def ajustar(self, nova_nota):
        self.nota = self._validar_nota(nova_nota)
        return self.frequencia_da_nota(self.nota)

    def transpor(self, semitons):
        if not isinstance(semitons, int) or isinstance(semitons, bool):
            raise ValueError("semitons deve ser inteiro")
        indice_atual = self._indice_da_nota(self.nota)
        novo_indice = indice_atual + semitons
        if novo_indice < 0 or novo_indice >= len(NOTAS_VALIDAS):
            raise ValueError("transposicao fora do intervalo valido")
        self.nota = NOTAS_VALIDAS[novo_indice]
        return self.frequencia_da_nota(self.nota)

