class JustificadorTexto:
    def __init__(self, largura):
        if not isinstance(largura, int):
            raise TypeError("largura deve ser int")
        if largura <= 0:
            raise ValueError("largura deve ser maior que zero")
        self.largura = largura

    def justificar(self, texto):
        if not isinstance(texto, str):
            raise TypeError("texto deve ser str")
        if texto == "":
            return " " * self.largura
        palavras = texto.split()
        n = len(palavras)
        if n == 1:
            return palavras[0].rjust(self.largura)
        total_letras = sum(len(p) for p in palavras)
        total_espacos = self.largura - total_letras
        espacos_entre = total_espacos // (n - 1)
        resto = total_espacos % (n - 1)
        partes = []
        for i, p in enumerate(palavras):
            partes.append(p)
            if i < n - 1:
                qtd = espacos_entre + (1 if i < resto else 0)
                partes.append(" " * qtd)
        return "".join(partes)

def interpola(x0, y0, x1, y1, x):
    if x0 == x1:
        raise ValueError("x0 e x1 devem ser distintos")
    if x < min(x0, x1) or x > max(x0, x1):
        raise ValueError("x deve estar entre x0 e x1")
    return y0 + (y1 - y0) * (x - x0) / (x1 - x0)

class PedidoRestaurante:
