        if itens is not None:
            for nome, preco, quantidade in itens:
                self.adicionar_item(nome, preco, quantidade)

    def adicionar_item(self, nome, preco, quantidade):
        if preco <= 0:
            raise ValueError("preço deve ser positivo")
        if quantidade <= 0:
            raise ValueError("quantidade deve ser positiva")
        for item in self.itens:
            if item[0] == nome:
                item[2] += quantidade
                return
        self.itens.append([nome, preco, quantidade])

    def listar_itens(self):
        return [tuple(item) for item in self.itens]

    def calcular_total(self):
        total = sum(preco * quantidade for _, preco, quantidade in self.itens)
        return total * (1 - self.desconto / 100)

    def aplicar_desconto(self, percentual):
        if not (0 <= percentual <= 100):
            raise ValueError("desconto deve estar entre 0 e 100")
        self.desconto = percentual

import math

_NOTAS_CROMATICA = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]
_BEMOL_PARA_SUstenido = {"Db": "C#", "Eb": "D#", "Gb": "F#", "Ab": "G#", "Bb": "A#"}
_A4_MIDI = 69
_A4_FREQUENCIA = 440.0


def nota_para_frequencia(nota):
    """Converte uma nota musical (ex: 'A4', 'C#4', 'Bb3') em frequência em Hz."""
    if not isinstance(nota, str):
        raise ValueError("nota deve ser uma string")

    nota = nota.strip()
    if not nota:
        raise ValueError("nota vazia")

    oitava = 4
    if nota[-1].isdigit():
        nome = nota[:-1]
        oitava = int(nota[-1])
    else:
        nome = nota

    nome = nome.upper()
    if nome in _BEMOL_PARA_SUstenido:
        nome = _BEMOL_PARA_SUstenido[nome]

    if len(nome) == 1:
        base = nome
        alteracao = ""
    elif len(nome) == 2 and nome[1] in ("#", "b"):
        base = nome[0]
        alteracao = nome[1]
        if alteracao == "b":
            if base in _BEMOL_PARA_SUstenido.values():
                raise ValueError(f"nota inválida: {nota}")
            # Converte bemol para sustenido da nota anterior quando possível
            indice_base = _NOTAS_CROMATICA.index(base)
            anterior = _NOTAS_CROMATICA[(indice_base - 1) % 12]
            nome = anterior + "#"
            base = nome[0]
            alteracao = nome[1]
    else:
        raise ValueError(f"nota inválida: {nota}")

    if base not in _NOTAS_CROMATICA[::2] and base not in [n[0] for n in _NOTAS_CROMATICA]:
        raise ValueError(f"nota inválida: {nota}")

    if nome not in _NOTAS_CROMATICA:
        raise ValueError(f"nota inválida: {nota}")

    semitom_relativo = _NOTAS_CROMATICA.index(nome)
    midi = 12 * (oitava + 1) + semitom_relativo
    return _A4_FREQUENCIA * (2 ** ((midi - _A4_MIDI) / 12))


def frequencia_para_nota(frequencia):
    """Converte uma frequência em Hz para o nome da nota mais próxima."""
    if not isinstance(frequencia, (int, float)) or isinstance(frequencia, bool):
        raise ValueError("frequencia deve ser um número")
    if frequencia <= 0:
        raise ValueError("frequencia deve ser positiva")

    midi = round(12 * math.log2(frequencia / _A4_FREQUENCIA) + _A4_MIDI)
    oitava = midi // 12 - 1
    semitom = midi % 12
    return _NOTAS_CROMATICA[semitom] + str(oitava)

