def percentil(latencias, p):
    if not latencias:
        raise ValueError("lista de latencias nao pode estar vazia")
    if p < 0 or p > 100:
        raise ValueError("p deve estar entre 0 e 100")
    dados = sorted(latencias)
    n = len(dados)
    k = (n - 1) * p / 100
    f = int(k)
    c = f + 1
    if c >= n:
        return dados[f]
    return dados[f] + (dados[c] - dados[f]) * (k - f)

