def escalonar(processos, quantum):
    if not processos:
        raise ValueError("A lista de processos não pode estar vazia")
    if quantum <= 0:
        raise ValueError("O quantum deve ser maior que zero")
    for tempo in processos:
        if tempo <= 0:
            raise ValueError("Os tempos dos processos devem ser maiores que zero")

    restante = list(processos)
    ordem = []
    idx = 0
    n = len(restante)

    while any(t > 0 for t in restante):
        if restante[idx] > 0:
            ordem.append(idx)
            restante[idx] = max(0, restante[idx] - quantum)
        idx = (idx + 1) % n

    return ordem

