def digito_luhn(numero):
    if not numero or not numero.isdigit():
        raise ValueError("numero invalido")
    digitos = [int(d) for d in numero]
    processados = []
    for i, d in enumerate(reversed(digitos)):
        if i % 2 == 0:
            d *= 2
            if d > 9:
                d -= 9
        processados.append(d)
    soma = sum(processados)
    return (10 - (soma % 10)) % 10

import re


def gerar_indice(texto):
    if not isinstance(texto, str):
        raise TypeError("texto deve ser uma string")
    if texto == "":
        raise ValueError("texto nao pode ser vazio")

    indice = {}
    for match in re.finditer(r"[A-Za-z0-9_]+", texto):
        palavra = match.group().lower()
        posicao = match.start()
        indice.setdefault(palavra, []).append(posicao)
    return indice

