        if not isinstance(texto, str):
            raise TypeError("texto deve ser uma string")
        self.texto = self.texto + texto

    def formatar(self):
        if self.texto == "":
            raise ValueError("texto vazio")
        if self.texto.strip() == "":
            return "VAZIO"
        tem_digito = False
        resultado = []
        for caractere in self.texto:
            if caractere.isdigit():
                tem_digito = True
                resultado.append("#")
            else:
                resultado.append(caractere)
        texto_processado = "".join(resultado).upper()
