def divisores_comuns(n1, n2):
    if n1 <= 0 or n2 <= 0:
        raise ValueError("Os números devem ser inteiros positivos")

    divisores1 = set()
    for i in range(1, int(n1 ** 0.5) + 1):
        if n1 % i == 0:
            divisores1.add(i)
            divisores1.add(n1 // i)

    divisores2 = set()
    for i in range(1, int(n2 ** 0.5) + 1):
        if n2 % i == 0:
            divisores2.add(i)
            divisores2.add(n2 // i)

    return sorted(divisores1 & divisores2)

class FilaTarefas:
    def __init__(self):
        self._tarefas = []
        self._contador = 0

    def adicionar(self, tarefa, prioridade):
        if prioridade < 1:
            raise ValueError("prioridade deve ser maior ou igual a 1")
        self._contador += 1
        self._tarefas.append([prioridade, self._contador, tarefa, 0])

    def atender(self):
        if not self._tarefas:
            raise IndexError("fila vazia")
        melhor = min(self._tarefas, key=lambda t: (-t[0], t[1]))
        self._tarefas.remove(melhor)
        melhor[3] += 1
        if melhor[3] > 3:
            raise RuntimeError("tarefa excedeu o numero maximo de tentativas")
        return melhor[2]

    def tamanho(self):
        return len(self._tarefas)

