def troco_minimo(valor, moedas):
    if valor < 0:
        raise ValueError("valor nao pode ser negativo")
    if not moedas:
        raise ValueError("lista de moedas nao pode estar vazia")
    for m in moedas:
        if m <= 0:
            raise ValueError("moedas devem ser maiores que zero")

    infinito = float('inf')
    dp = [infinito] * (valor + 1)
    dp[0] = 0
    for i in range(1, valor + 1):
        for m in moedas:
            if m <= i and dp[i - m] + 1 < dp[i]:
                dp[i] = dp[i - m] + 1
    return -1 if dp[valor] == infinito else dp[valor]

