def compara_versoes(v1, v2):
    def parse(versao):
        partes = versao.split(".")
        if len(partes) != 3:
            raise ValueError("Versão inválida: deve conter exatamente três partes")
        valores = []
        for parte in partes:
            if not parte.isdigit():
                raise ValueError("Versão inválida: partes devem ser números inteiros não negativos")
            valores.append(int(parte))
        return valores

    p1 = parse(v1)
    p2 = parse(v2)

    for a, b in zip(p1, p2):
        if a < b:
            return -1
        if a > b:
            return 1
    return 0

import datetime


def diferenca_dias(data1, data2):
    def validar(data):
        if type(data) is not tuple or len(data) != 3:
            raise ValueError("A data deve ser uma tupla de três inteiros")
        ano, mes, dia = data
        for valor in (ano, mes, dia):
            if type(valor) is not int:
                raise ValueError("Os componentes da data devem ser inteiros")
        if not 1 <= ano <= 9999:
            raise ValueError("Ano fora do intervalo permitido")
        if not 1 <= mes <= 12:
            raise ValueError("Mês fora do intervalo permitido")
        dias_por_mes = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if mes == 2 and (ano % 4 == 0 and (ano % 100 != 0 or ano % 400 == 0)):
            limite = 29
        else:
            limite = dias_por_mes[mes - 1]
        if not 1 <= dia <= limite:
            raise ValueError("Dia fora do intervalo permitido para o mês")
        return datetime.date(ano, mes, dia)

    d1 = validar(data1)
    d2 = validar(data2)
    return abs((d2 - d1).days)

import re


class NomeSeparador:
    def separar(self, nome):
        if not isinstance(nome, str):
            raise ValueError("Nome inválido")
        if nome == "":
            raise ValueError("Nome vazio")
        if not re.fullmatch(r"[A-Za-z0-9_]+", nome):
            raise ValueError("Nome contém caracteres inválidos")

        partes = re.split(r"_+", nome)
        resultado = []
        for parte in partes:
            if parte == "":
                continue
            subpartes = re.findall(r"[A-Z]?[a-z0-9]+|[A-Z]+(?=[A-Z]|$)|[A-Z]", parte)
            for sub in subpartes:
                resultado.append(sub.lower())
        return resultado

