        raise ValueError("Ambos os argumentos devem ser inteiros.")
    if a <= 0 or b <= 0:
        raise ValueError("Ambos os argumentos devem ser inteiros positivos.")
    x, y = a, b
    while y != 0:
        x, y = y, x % y
    mdc = x
    mmc = a * b // mdc
    return (mdc, mmc)

