def cifrar_cesar(texto, deslocamento):
    if not isinstance(deslocamento, int) or isinstance(deslocamento, bool):
        raise TypeError("deslocamento deve ser um inteiro")
    resultado = []
    for caractere in texto:
        if 'a' <= caractere <= 'z':
            base = ord('a')
            resultado.append(chr((ord(caractere) - base + deslocamento) % 26 + base))
        elif 'A' <= caractere <= 'Z':
            base = ord('A')
            resultado.append(chr((ord(caractere) - base + deslocamento) % 26 + base))
        else:
            resultado.append(caractere)
    return "".join(resultado)

class DeslocamentoFuso:
    def __init__(self, deslocamento_horas):
        self.deslocamento_horas = deslocamento_horas

    def converter(self, hora, minuto):
        if not isinstance(hora, int) or not isinstance(minuto, int):
            raise ValueError("hora e minuto devem ser inteiros")
        if hora < 0 or hora > 23:
            raise ValueError("hora deve estar entre 0 e 23")
        if minuto < 0 or minuto > 59:
            raise ValueError("minuto deve estar entre 0 e 59")

        total_minutos = hora * 60 + minuto
        total_minutos += self.deslocamento_horas * 60
        total_minutos %= 24 * 60

        nova_hora = total_minutos // 60
        novo_minuto = total_minutos % 60
        return (nova_hora, novo_minuto)

