    def set(self, path, valor):
        partes = path.split(".")
        atual = self._dados
        for parte in partes[:-1]:
            if parte in atual:
                if not isinstance(atual[parte], dict):
                    raise ValueError("caminho intermediario nao e dicionario")
                atual = atual[parte]
            else:
                novo = {}
                atual[parte] = novo
                atual = novo
        atual[partes[-1]] = valor

    def get(self, path):
        partes = path.split(".")
        atual = self._dados
        for parte in partes:
            if not isinstance(atual, dict) or parte not in atual:
                raise KeyError(path)
            atual = atual[parte]
        return atual

    def to_dict(self):
        return self._dados

