class LRUCache:
    def __init__(self, capacidade):
        if not isinstance(capacidade, int) or capacidade <= 0:
            raise ValueError("capacidade deve ser um inteiro positivo")
        self.capacidade = capacidade
        self.dados = OrderedDict()

    def get(self, chave):
        if chave not in self.dados:
            return None
        self.dados.move_to_end(chave)
        return self.dados[chave]

    def put(self, chave, valor):
        if chave in self.dados:
            self.dados.move_to_end(chave)
        self.dados[chave] = valor
        if len(self.dados) > self.capacidade:
            self.dados.popitem(last=False)

def extrair_minuto(timestamp):
    if not isinstance(timestamp, str):
        raise ValueError("timestamp invalido")
    partes = timestamp.split(" ")
    if len(partes) != 2:
        raise ValueError("timestamp invalido")
    data, hora = partes
    data_partes = data.split("-")
    hora_partes = hora.split(":")
    if len(data_partes) != 3 or len(hora_partes) != 3:
        raise ValueError("timestamp invalido")
    ano, mes, dia = data_partes
    hh, mm, ss = hora_partes
    if not (ano.isdigit() and mes.isdigit() and dia.isdigit() and hh.isdigit() and mm.isdigit() and ss.isdigit()):
        raise ValueError("timestamp invalido")
    if len(ano) != 4 or len(mes) != 2 or len(dia) != 2 or len(hh) != 2 or len(mm) != 2 or len(ss) != 2:
        raise ValueError("timestamp invalido")
    mes_i = int(mes)
    dia_i = int(dia)
    hh_i = int(hh)
    mm_i = int(mm)
    ss_i = int(ss)
    if mes_i < 1 or mes_i > 12:
        raise ValueError("timestamp invalido")
    if dia_i < 1 or dia_i > 31:
        raise ValueError("timestamp invalido")
    if hh_i < 0 or hh_i > 23:
        raise ValueError("timestamp invalido")
    if mm_i < 0 or mm_i > 59:
        raise ValueError("timestamp invalido")
    if ss_i != 0:
        raise ValueError("segundos devem ser zero")
    return f"{ano}-{mes}-{dia} {hh}:{mm}"


def agrupar_por_minuto(registros):
