class CarrinhoDesconto:
    CUPOM_VALIDOS = {
        "DESCONTO10": 0.10,
        "DESCONTO20": 0.20,
        "DESCONTO30": 0.30,
    }

    def aplicar_cupom(self, codigo):
        if not isinstance(codigo, str):
            raise ValueError("codigo deve ser uma string")
        if codigo not in self.CUPOM_VALIDOS:
            raise ValueError("cupom invalido")
        return self.CUPOM_VALIDOS[codigo]

    def aplicar_desconto_quantidade(self, valor_total, quantidade):
        if not isinstance(valor_total, (int, float)) or isinstance(valor_total, bool):
            raise ValueError("valor_total deve ser um numero")
        if not isinstance(quantidade, (int, float)) or isinstance(quantidade, bool):
            raise ValueError("quantidade deve ser um numero")
        if valor_total < 0 or quantidade < 0:
            raise ValueError("valores nao podem ser negativos")
        if quantidade > 5:
            return valor_total * 0.90
        return valor_total

    def calcular_total(self, itens, codigo_cupom, quantidade):
        if not isinstance(itens, list):
            raise ValueError("itens deve ser uma lista")
        for item in itens:
            if not isinstance(item, (int, float)) or isinstance(item, bool):
                raise ValueError("todos os itens devem ser numeros")
            if item < 0:
                raise ValueError("itens nao podem ser negativos")
        if codigo_cupom is not None and not isinstance(codigo_cupom, str):
            raise ValueError("codigo_cupom deve ser string ou None")
        if not isinstance(quantidade, int) or isinstance(quantidade, bool) or quantidade < 0:
            raise ValueError("quantidade deve ser um inteiro nao negativo")

        total = sum(itens)
        if codigo_cupom is not None:
            desconto = self.aplicar_cupom(codigo_cupom)
            total = total * (1 - desconto)
        total = self.aplicar_desconto_quantidade(total, quantidade)
        return total

