class LimpezaTexto:
    def __init__(self, linhas):
        if not isinstance(linhas, list):
            raise TypeError("linhas deve ser uma lista")
        for item in linhas:
            if not isinstance(item, str):
                raise TypeError("todos os elementos devem ser strings")
        self._linhas = list(linhas)

    def limpar(self):
        resultado = []
        visto = set()
        for linha in self._linhas:
            if linha.strip() == "":
                continue
            if linha in visto:
                continue
            visto.add(linha)
            resultado.append(linha)
        return resultado

def resumo_texto(texto, limite_palavras):
    if not isinstance(texto, str):
        raise TypeError("texto deve ser uma string")
    if not isinstance(limite_palavras, int):
        raise TypeError("limite_palavras deve ser um inteiro")
    if limite_palavras < 0:
        raise ValueError("limite_palavras não pode ser negativo")
    if texto == "":
        return ""
    palavras = texto.split()
    return " ".join(palavras[:limite_palavras])

