class LoginAttempts:
    def __init__(self):
        self._tentativas_consecutivas = {}
        self._bloqueados = set()

    def _validar_usuario(self, usuario):
        if not isinstance(usuario, str) or usuario == "":
            raise ValueError("usuario deve ser uma string nao vazia")

    def registrar_tentativa(self, usuario, sucesso):
        self._validar_usuario(usuario)
        if usuario in self._bloqueados:
            return
        if sucesso:
            self._tentativas_consecutivas[usuario] = 0
            self._bloqueados.discard(usuario)
        else:
            self._tentativas_consecutivas[usuario] = self._tentativas_consecutivas.get(usuario, 0) + 1
            if self._tentativas_consecutivas[usuario] >= 3:
                self._bloqueados.add(usuario)

    def bloqueado_por(self, usuario):
        self._validar_usuario(usuario)
        return usuario in self._bloqueados

class ContadorHistorico:
    def __init__(self):
        self._valores = []

    def adicionar_metrica(self, valor):
        self._valores.append(valor)

    def total(self):
        return sum(self._valores)

    def media(self):
        if not self._valores:
            return None
        return sum(self._valores) / len(self._valores)

    def histograma(self, tamanho_bin):
        if tamanho_bin <= 0:
            raise ValueError("tamanho_bin deve ser maior que zero")
        if not self._valores:
            raise ValueError("não há métricas adicionadas")
        bins = {}
        for valor in self._valores:
            chave = (valor // tamanho_bin) * tamanho_bin
            bins[chave] = bins.get(chave, 0) + 1
        return bins

