def classificar_participantes(participantes):
    obrigatorias = {"nome", "pontos", "vitorias"}
    for participante in participantes:
        if not obrigatorias.issubset(participante.keys()):
            raise ValueError("participante faltando chaves obrigatórias")
    ordenados = sorted(
