    return [p["nome"] for p in ordenados]

class Loja:
    def __init__(self):
        self._itens = {}

    def adicionar_item(self, nome, quantidade):
        if not isinstance(quantidade, int) or isinstance(quantidade, bool) or quantidade <= 0:
            raise ValueError("quantidade deve ser um inteiro positivo")
        if nome in self._itens:
            self._itens[nome] += quantidade
        else:
            self._itens[nome] = quantidade

    def remover_item(self, nome, quantidade):
        if not isinstance(quantidade, int) or isinstance(quantidade, bool) or quantidade <= 0:
            raise ValueError("quantidade deve ser um inteiro positivo")
        if nome not in self._itens:
            raise ValueError("item nao encontrado")
        if self._itens[nome] < quantidade:
            raise ValueError("estoque insuficiente")
        self._itens[nome] -= quantidade

    def estoque(self, nome):
        return self._itens.get(nome, 0)

import math


def comprimento_segmento(x1, y1, x2, y2):
    if not all(isinstance(v, (int, float)) for v in (x1, y1, x2, y2)):
        raise ValueError("todas as coordenadas devem ser numericas")
    return math.hypot(x2 - x1, y2 - y1)

def boletim_aprovacao(notas, pesos):
    if not isinstance(notas, list) or not isinstance(pesos, list):
        raise ValueError("notas e pesos devem ser listas")
    if len(notas) == 0 or len(pesos) == 0:
        raise ValueError("listas não podem ser vazias")
    if len(notas) != len(pesos):
        raise ValueError("notas e pesos devem ter o mesmo tamanho")
    for p in pesos:
        if not isinstance(p, (int, float)) or isinstance(p, bool) or p <= 0:
            raise ValueError("pesos devem ser números estritamente positivos")
    soma_ponderada = 0.0
    soma_pesos = 0.0
    for n, p in zip(notas, pesos):
        soma_ponderada += n * p
        soma_pesos += p
    media = soma_ponderada / soma_pesos
    return (media, media >= 7.0)

def expandir_chaves(dados):
    if not isinstance(dados, dict):
        raise TypeError("o argumento deve ser um dicionário")

    resultado = {}

    def percorrer(atual, prefixo):
        for chave, valor in atual.items():
            if not isinstance(chave, str):
                raise ValueError("todas as chaves devem ser strings")
            nova_chave = f"{prefixo}.{chave}" if prefixo else chave
            if isinstance(valor, dict):
                percorrer(valor, nova_chave)
            else:
                if nova_chave in resultado:
                    raise ValueError("colisão de chaves ao achatar")
                resultado[nova_chave] = valor

    percorrer(dados, "")
    return resultado

def imposto_renda(renda):
    if renda < 0:
        raise ValueError("renda não pode ser negativa")
    if renda <= 2000:
        return 0.0
    if renda <= 3000:
        return (renda - 2000) * 0.075
    if renda <= 4500:
        return 75 + (renda - 3000) * 0.15
    if renda <= 6000:
        return 300 + (renda - 4500) * 0.225
    return 637.5 + (renda - 6000) * 0.275

import hashlib
import hmac


def assinar_requisicoes(cabecalhos, chave, corpo):
    if not chave:
        raise ValueError("chave secreta não pode ser vazia")
    assinatura = hmac.new(chave.encode("utf-8"), corpo, hashlib.sha256).hexdigest()
    cabecalhos["X-Signature"] = assinatura
    return cabecalhos


def verificar_assinatura(cabecalhos, chave, corpo):
    if not chave:
        raise ValueError("chave secreta não pode ser vazia")
    assinatura_esperada = cabecalhos.get("X-Signature")
    if assinatura_esperada is None:
        return False
    assinatura_calculada = hmac.new(chave.encode("utf-8"), corpo, hashlib.sha256).hexdigest()
    return hmac.compare_digest(assinatura_calculada, assinatura_esperada)

def ordenar_por_distancia_origem(lista):
    if not isinstance(lista, list):
        raise ValueError("lista deve ser uma lista")
    def chave(ponto):
        if (not isinstance(ponto, tuple) or len(ponto) != 2 or
                not isinstance(ponto[0], (int, float)) or
                not isinstance(ponto[1], (int, float))):
            raise ValueError("elemento invalido: ponto deve ser tupla de dois numeros")
        x, y = ponto
        return (x * x + y * y, x, y)
    return sorted(lista, key=chave)

