def comparar_versoes(v1, v2):
    def parse(versao):
        if not isinstance(versao, str):
            raise ValueError("versão deve ser uma string")
        if versao == "":
            raise ValueError("versão não pode ser vazia")
        partes = versao.split(".")
        numeros = []
        for parte in partes:
            if parte == "":
                raise ValueError("segmento vazio na versão")
            if not parte.isdigit():
                raise ValueError("segmento inválido na versão")
            numeros.append(int(parte))
        return numeros

    n1 = parse(v1)
    n2 = parse(v2)
    tamanho = max(len(n1), len(n2))
    for i in range(tamanho):
        a = n1[i] if i < len(n1) else 0
        b = n2[i] if i < len(n2) else 0
        if a < b:
            return -1
        if a > b:
            return 1
    return 0

