def cifrar_texto(texto, deslocamento):
    if not isinstance(texto, str):
        raise TypeError("texto deve ser uma string")
    if isinstance(deslocamento, bool) or not isinstance(deslocamento, int):
        raise TypeError("deslocamento deve ser um inteiro")
    if deslocamento < -1000 or deslocamento > 1000:
        raise ValueError("deslocamento deve estar entre -1000 e 1000")

    resultado = []
    for caractere in texto:
        if 'a' <= caractere <= 'z':
            base = ord('a')
            resultado.append(chr((ord(caractere) - base + deslocamento) % 26 + base))
        elif 'A' <= caractere <= 'Z':
            base = ord('A')
            resultado.append(chr((ord(caractere) - base + deslocamento) % 26 + base))
        else:
            resultado.append(caractere)
    return ''.join(resultado)

