import math


def formata_moeda(valor):
    if isinstance(valor, bool) or not isinstance(valor, (int, float)):
        raise TypeError("valor deve ser um número int ou float")
    if not math.isfinite(valor):
        raise ValueError("valor deve ser finito")
    return "R$ {:,.2f}".format(valor).replace(",", "X").replace(".", ",").replace("X", ".")

def pares_com_soma_alvo(numeros, alvo):
    if not isinstance(numeros, list):
        raise ValueError("numeros deve ser uma lista")
    if not isinstance(alvo, int):
        raise ValueError("alvo deve ser um inteiro")
    for n in numeros:
        if not isinstance(n, int):
            raise ValueError("todos os elementos de numeros devem ser inteiros")

    disponiveis = sorted(numeros)
    pares = []
    i = 0
    j = len(disponiveis) - 1
    while i < j:
        s = disponiveis[i] + disponiveis[j]
        if s == alvo:
            pares.append((disponiveis[i], disponiveis[j]))
            i += 1
            j -= 1
        elif s < alvo:
            i += 1
        else:
            j -= 1
    return pares

def compara_carta(a, b):
    validos = list(range(2, 11)) + ['J', 'Q', 'K', 'A']
    if a not in validos or b not in validos:
        raise ValueError('carta invalida')
    ordem = {v: i for i, v in enumerate(validos)}
    if ordem[a] < ordem[b]:
        return -1
    if ordem[a] > ordem[b]:
        return 1
    return 0

class RegistroNumeros:
    def __init__(self):
        self._numeros = []

    def adicionar(self, numero):
        if isinstance(numero, bool):
            raise ValueError("booleano não é um número válido")
        if isinstance(numero, int):
            self._numeros.append(numero)
        elif isinstance(numero, float):
            if numero.is_integer():
                self._numeros.append(int(numero))
            else:
                raise ValueError("float não inteiro não é permitido")
        else:
            raise ValueError("tipo inválido")

    def maior(self):
        if not self._numeros:
            return None
        return max(self._numeros)

    def menor(self):
        if not self._numeros:
            return None
        return min(self._numeros)

    def soma(self):
        return sum(self._numeros)

    def media(self):
        if not self._numeros:
            return None
        return sum(self._numeros) / len(self._numeros)

    def remover(self, numero):
        if numero not in self._numeros:
            raise ValueError("número não presente")
        self._numeros.remove(numero)

    def ocorrencias(self, numero):
        return self._numeros.count(numero)

    def listar(self):
        return sorted(self._numeros)

def encontrar_extremos(sequencia):
    if len(sequencia) == 0:
        raise ValueError("sequencia nao pode estar vazia")
    menor = None
    maior = None
    for item in sequencia:
        if not isinstance(item, (int, float)):
            raise TypeError("todos os elementos devem ser numeros")
        if menor is None or item < menor:
            menor = item
        if maior is None or item > maior:
            maior = item
    return (menor, maior)

