import hashlib

class AnelServidores:
    def __init__(self, servidores):
        self.servidores = list(servidores)

    def adicionar(self, servidor):
        if not self.servidores:
            raise ValueError("Não é possível adicionar servidor a um anel vazio")
        self.servidores.append(servidor)

    def escolher(self, chave):
        if not self.servidores:
            raise ValueError("Não há servidores cadastrados")
        hashes = []
        for servidor in self.servidores:
            digest = hashlib.md5(servidor.encode()).hexdigest()
            hashes.append((int(digest, 16), servidor))
        hashes.sort(key=lambda item: item[0])
        chave_hash = int(hashlib.md5(chave.encode()).hexdigest(), 16)
        for h, servidor in hashes:
            if chave_hash <= h:
                return servidor
