class ComparadorCartas:
    def __init__(self, naipes_ordem, valores_ordem):
        if len(naipes_ordem) != len(set(naipes_ordem)):
            raise ValueError("naipes duplicados")
        if len(valores_ordem) != len(set(valores_ordem)):
            raise ValueError("valores duplicados")
        self.naipes_ordem = list(naipes_ordem)
        self.valores_ordem = list(valores_ordem)
        self._indice_naipe = {naipe: i for i, naipe in enumerate(self.naipes_ordem)}
        self._indice_valor = {valor: i for i, valor in enumerate(self.valores_ordem)}

    def compara(self, carta1, carta2):
        for carta in (carta1, carta2):
            if len(carta) != 2:
                raise ValueError("carta invalida")
            valor, naipe = carta
            if valor not in self._indice_valor:
                raise ValueError("valor invalido")
            if naipe not in self._indice_naipe:
                raise ValueError("naipe invalido")
        v1, n1 = carta1
        v2, n2 = carta2
        i1 = self._indice_valor[v1]
        i2 = self._indice_valor[v2]
        if i1 != i2:
            return 1 if i1 > i2 else -1
        j1 = self._indice_naipe[n1]
        j2 = self._indice_naipe[n2]
        if j1 != j2:
            return 1 if j1 > j2 else -1
        return 0

