        self.itens = []

    def adicionar(self, nome, preco):
        self.itens.append({"nome": nome, "preco": preco})

    def filtrar_ordenar(self, ordem="asc", min_preco=None, max_preco=None):
        if ordem not in ("asc", "desc"):
            raise ValueError("ordem invalida")
        if min_preco is not None and min_preco < 0:
            raise ValueError("min_preco nao pode ser negativo")
        if max_preco is not None and max_preco < 0:
            raise ValueError("max_preco nao pode ser negativo")
        if min_preco is not None and max_preco is not None and min_preco > max_preco:
            raise ValueError("min_preco nao pode ser maior que max_preco")

        filtrados = self.itens
        if min_preco is not None:
            filtrados = [item for item in filtrados if item["preco"] >= min_preco]
        if max_preco is not None:
            filtrados = [item for item in filtrados if item["preco"] <= max_preco]

