def faixa_imposto(renda_anual):
    if isinstance(renda_anual, bool) or not isinstance(renda_anual, (int, float)):
        raise ValueError("renda_anual deve ser um número")
    if renda_anual < 0:
        raise ValueError("renda_anual não pode ser negativa")
    if renda_anual <= 22847.76:
        return 0
    if renda_anual <= 33919.80:
        return 7.5
    if renda_anual <= 45012.60:
        return 15.0
    if renda_anual <= 55976.16:
        return 22.5
    return 27.5


def calcula_imposto(renda_anual):
    if isinstance(renda_anual, bool) or not isinstance(renda_anual, (int, float)):
        raise ValueError("renda_anual deve ser um número")
    if renda_anual < 0:
        raise ValueError("renda_anual não pode ser negativa")

    faixas = [
        (22847.76, 0.0),
        (33919.80, 0.075),
        (45012.60, 0.15),
        (55976.16, 0.225),
        (float("inf"), 0.275),
    ]

    imposto = 0.0
    limite_anterior = 0.0
    for limite, aliquota in faixas:
        if renda_anual <= limite:
            imposto += (renda_anual - limite_anterior) * aliquota
            break
        imposto += (limite - limite_anterior) * aliquota
        limite_anterior = limite

    return imposto

class BuscadorPalavras:
