NOTAS = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]

def frequencia_da_nota(nota):
    if not isinstance(nota, str):
        raise ValueError("nota deve ser uma string")

    if len(nota) < 2:
        raise ValueError("formato de nota inválido")

    if nota[1] == "#":
        nome = nota[0:2]
        oitava_str = nota[2:]
    else:
        nome = nota[0]
        oitava_str = nota[1:]

    if nome not in NOTAS:
        raise ValueError("nome de nota inválido")

    try:
        oitava = int(oitava_str)
    except ValueError:
        raise ValueError("oitava inválida")

    if oitava < 0 or oitava > 8:
        raise ValueError("oitava fora do intervalo permitido")

    semitons = NOTAS.index(nome) - NOTAS.index("A") + (oitava - 4) * 12
    return 440.0 * (2 ** (semitons / 12))

