        raise ValueError("capacidade, taxa e custo devem ser nao negativos")
    if tokens < 0 or tokens > capacidade:
        raise ValueError("tokens deve estar entre 0 e capacidade")
    return tokens >= custo


def consumir(capacidade, taxa, tokens, tempo_atual, custo=1):
    if capacidade < 0 or taxa < 0 or custo < 0:
        raise ValueError("capacidade, taxa e custo devem ser nao negativos")
    if tokens < 0 or tokens > capacidade:
        raise ValueError("tokens deve estar entre 0 e capacidade")
    if pode_consumir(capacidade, taxa, tokens, tempo_atual, custo):
        return True, tokens - custo
    return False, tokens

