class DataTupla:
    def __init__(self, data):
        if not isinstance(data, tuple) or len(data) != 3:
            raise ValueError("Data deve ser uma tupla (dia, mes, ano)")
        dia, mes, ano = data
        if not all(isinstance(x, int) for x in (dia, mes, ano)):
            raise ValueError("Dia, mes e ano devem ser inteiros")
        if mes < 1 or mes > 12:
            raise ValueError("Mes invalido")
        if ano < 1:
            raise ValueError("Ano invalido")
        dias_por_mes = [31, 29 if self._eh_bissexto(ano) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if dia < 1 or dia > dias_por_mes[mes - 1]:
            raise ValueError("Dia invalido")
        self.dia = dia
        self.mes = mes
        self.ano = ano

    @staticmethod
    def _eh_bissexto(ano):
        return ano % 4 == 0 and (ano % 100 != 0 or ano % 400 == 0)

    @staticmethod
    def _dias_no_mes(mes, ano):
        if mes == 2:
            return 29 if DataTupla._eh_bissexto(ano) else 28
        return [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mes - 1]

    def somar_dias(self, n):
        if not isinstance(n, int) or isinstance(n, bool):
            raise TypeError("Quantidade de dias deve ser um inteiro")
        if n < 0:
            raise ValueError("Quantidade de dias nao pode ser negativa")
        dia = self.dia
        mes = self.mes
        ano = self.ano
        while n > 0:
            restante = DataTupla._dias_no_mes(mes, ano) - dia + 1
            if n < restante:
                dia += n
                n = 0
            else:
                n -= restante
                dia = 1
                mes += 1
                if mes > 12:
                    mes = 1
                    ano += 1
        return (dia, mes, ano)

