def fib_var(n, a, b):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n deve ser um inteiro")
    if not isinstance(a, int) or isinstance(a, bool):
        raise ValueError("a deve ser um inteiro")
    if not isinstance(b, int) or isinstance(b, bool):
        raise ValueError("b deve ser um inteiro")
    if n < 0:
        raise ValueError("n não pode ser negativo")
    if n == 0:
        return a
    if n == 1:
        return b
    anterior, atual = a, b
    for _ in range(2, n + 1):
        anterior, atual = atual, anterior + atual
    return atual

class EstoqueMinimo:
    def __init__(self):
        self._estoques = {}
        self._minimos = {}

    def _checa_int(self, valor):
        if not isinstance(valor, int) or isinstance(valor, bool):
            raise ValueError("quantidade deve ser int")

    def registrar_entrada(self, nome, quantidade):
        self._checa_int(quantidade)
        atual = self._estoques.get(nome, 0)
        novo = atual + quantidade
        if novo < 0:
            raise ValueError("estoque não pode ficar negativo")
        self._estoques[nome] = novo

    def registrar_saida(self, nome, quantidade):
        self._checa_int(quantidade)
        atual = self._estoques.get(nome, 0)
        novo = atual - quantidade
        if novo < 0:
            raise ValueError("estoque não pode ficar negativo")
        self._estoques[nome] = novo

    def definir_minimo(self, nome, minimo):
        self._checa_int(minimo)
        if minimo < 0:
            raise ValueError("mínimo não pode ser negativo")
        self._minimos[nome] = minimo

    def consultar_disponivel(self, nome):
        estoque = self._estoques.get(nome, 0)
        minimo = self._minimos.get(nome, 0)
        return max(0, estoque - minimo)

