def obter_ranking():
    estatisticas = {}
    for partida in _partidas:
        vencedor = partida["vencedor"]
        perdedor = partida["perdedor"]
        pontos_vencedor = partida["pontos_vencedor"]
        pontos_perdedor = partida["pontos_perdedor"]

        if vencedor not in estatisticas:
            estatisticas[vencedor] = {"pontos": 0, "vitorias": 0}
        if perdedor not in estatisticas:
            estatisticas[perdedor] = {"pontos": 0, "vitorias": 0}

        estatisticas[vencedor]["pontos"] += pontos_vencedor
        estatisticas[vencedor]["vitorias"] += 1
        estatisticas[perdedor]["pontos"] += pontos_perdedor

    ranking = [
        {"jogador": nome, "pontos": dados["pontos"], "vitorias": dados["vitorias"]}
        for nome, dados in estatisticas.items()
    ]
