def mover_robo(posicao, comandos):
    if not isinstance(posicao, tuple) or len(posicao) != 2:
        raise ValueError("posicao deve ser uma tupla de dois inteiros")
    if not all(isinstance(c, int) for c in posicao):
        raise ValueError("posicao deve ser uma tupla de dois inteiros")
    x, y = posicao
    for comando in comandos:
        if comando == 'N':
            y += 1
        elif comando == 'S':
            y -= 1
        elif comando == 'L':
            x += 1
        elif comando == 'O':
            x -= 1
        else:
            raise ValueError("comando invalido: " + comando)
    return (x, y)

