def compress_linha(linha):
    blocos = [valor for valor in linha if valor != 0]
    fundidos = []
    pular = False
    for i in range(len(blocos)):
        if pular:
            pular = False
            continue
        if i + 1 < len(blocos) and blocos[i] == blocos[i + 1]:
            fundidos.append(blocos[i] * 2)
            pular = True
        else:
            fundidos.append(blocos[i])
    return fundidos + [0] * (len(linha) - len(fundidos))


def mova_linha(linha):
