def variacao_fibonacci(seed_a, seed_b, n):
    if not isinstance(seed_a, int) or not isinstance(seed_b, int):
        raise ValueError("seed_a e seed_b devem ser inteiros")
    if n < 0:
        raise ValueError("n não pode ser negativo")
    if n == 0:
        return seed_a
    if n == 1:
        return seed_b
    a, b = seed_a, seed_b
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

