        raise ValueError("matriz vazia")
    n = len(matriz)
    for linha in matriz:
        if len(linha) != n:
            raise ValueError("matriz nao quadrada")
    soma = 0
    for i in range(n):
        soma += matriz[i][i]
    return soma

def mediana(valores):
    if not isinstance(valores, list):
        raise TypeError("valores deve ser uma lista")
    for v in valores:
        if not isinstance(v, (int, float)):
            raise ValueError("todos os elementos devem ser int ou float")
    if not valores:
        return None
    ordenados = sorted(valores)
    n = len(ordenados)
    meio = n // 2
    if n % 2 == 1:
        return ordenados[meio]
    return (ordenados[meio - 1] + ordenados[meio]) / 2


def moda(valores):
    if not isinstance(valores, list):
        raise TypeError("valores deve ser uma lista")
    for v in valores:
        if not isinstance(v, (int, float)):
            raise ValueError("todos os elementos devem ser int ou float")
    if not valores:
        return None
    frequencias = {}
    for v in valores:
        frequencias[v] = frequencias.get(v, 0) + 1
    maxima = max(frequencias.values())
    if maxima == 1:
        return None
    mais_frequentes = [valor for valor, conta in frequencias.items() if conta == maxima]
    if len(mais_frequentes) != 1:
        return None
    return mais_frequentes[0]

