def calcular_larguras_colunas(tabela):
    if not tabela:
        return []
    numero_colunas = len(tabela[0])
    for linha in tabela:
        if len(linha) != numero_colunas:
            raise ValueError("linhas com quantidade diferente de colunas")
    larguras = [0] * numero_colunas
    for linha in tabela:
        for indice, celula in enumerate(linha):
            tamanho = len(celula)
            if tamanho > larguras[indice]:
                larguras[indice] = tamanho
    return larguras


def alinhar_tabela(tabela, alinhamento):
    if alinhamento not in ("esquerda", "centro", "direita"):
        raise ValueError("alinhamento invalido")
    larguras = calcular_larguras_colunas(tabela)
    linhas_saida = []
    for linha in tabela:
        celulas_ajustadas = []
        for indice, celula in enumerate(linha):
            largura = larguras[indice]
            if alinhamento == "esquerda":
                ajuste = celula.ljust(largura)
            elif alinhamento == "centro":
                ajuste = celula.center(largura)
            else:
                ajuste = celula.rjust(largura)
            celulas_ajustadas.append(ajuste)
        linhas_saida.append(" | ".join(celulas_ajustadas))
    return "\n".join(linhas_saida)

