from datetime import date


def semanas_entre(data_inicial, data_final):
    partes_inicial = data_inicial.split("-")
    partes_final = data_final.split("-")
    if len(partes_inicial) != 3 or len(partes_final) != 3:
        raise ValueError("Formato de data inválido. Use AAAA-MM-DD.")
    try:
        ano_inicial, mes_inicial, dia_inicial = (int(p) for p in partes_inicial)
        ano_final, mes_final, dia_final = (int(p) for p in partes_final)
    except ValueError:
        raise ValueError("Componentes da data devem ser números inteiros.")
    try:
        inicio = date(ano_inicial, mes_inicial, dia_inicial)
        fim = date(ano_final, mes_final, dia_final)
    except ValueError:
        raise ValueError("Data inválida.")
    if fim < inicio:
        return 0
    return (fim - inicio).days // 7

def calcular_orçamento(categorias):
    if not categorias:
        raise ValueError("O dicionário de categorias não pode estar vazio.")
    total = 0
    for valor in categorias.values():
        if isinstance(valor, bool) or not isinstance(valor, (int, float)):
            raise ValueError("Todos os valores devem ser numéricos.")
        if valor < 0:
            raise ValueError("Os valores não podem ser negativos.")
        total += valor
    resultado = {"total": total}
    for categoria, valor in categorias.items():
        resultado[categoria] = (valor / total) * 100
    return resultado

def converter_base(numero: str, base_origem: int, base_destino: int) -> str:
    if not isinstance(numero, str):
        raise ValueError("numero deve ser string")
    if not (2 <= base_origem <= 36):
        raise ValueError("base_origem deve estar entre 2 e 36")
    if not (2 <= base_destino <= 36):
        raise ValueError("base_destino deve estar entre 2 e 36")
    if numero == "":
        raise ValueError("numero não pode ser vazio")

    digitos = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    numero_upper = numero.upper()

    for ch in numero_upper:
        if ch not in digitos[:base_origem]:
            raise ValueError(f"caractere inválido '{ch}' para base {base_origem}")

    valor = 0
    for ch in numero_upper:
        valor = valor * base_origem + digitos.index(ch)

    if valor == 0:
        return "0"

    resultado = []
    while valor > 0:
        resultado.append(digitos[valor % base_destino])
        valor //= base_destino

    return "".join(reversed(resultado))

