        raise ValueError("caminho vazio")
    ultima_barra = caminho.rfind("/")
    if ultima_barra == -1:
        diretorio = ""
        nome = caminho
    else:
        diretorio = caminho[:ultima_barra]
        nome = caminho[ultima_barra + 1:]
    ponto = nome.rfind(".")
    if ponto == -1:
        extensao = ""
        arquivo = nome
    else:
        arquivo = nome[:ponto]
        extensao = nome[ponto + 1:]
    return {"diretorio": diretorio, "arquivo": arquivo, "extensao": extensao}

