    resultado.extend(agenda_a[i:])
    resultado.extend(agenda_b[j:])
    return resultado

class CicloPomodoro:
    def __init__(self, trabalho, pausa):
        if trabalho <= 0 or pausa <= 0:
            raise ValueError("duracoes devem ser positivas")
        self.trabalho = trabalho
        self.pausa = pausa
        self._fase = "trabalho"
        self._restante = trabalho

    def fase(self):
        return self._fase

    def restante(self):
        return self._restante

    def avancar(self, segundos):
        if segundos < 0:
            raise ValueError("segundos nao podem ser negativos")
        pausas_concluidas = 0
        while segundos > 0:
            passo = min(segundos, self._restante)
            self._restante -= passo
            segundos -= passo
            if self._restante == 0:
                if self._fase == "trabalho":
                    self._fase = "pausa"
                    self._restante = self.pausa
                else:
                    self._fase = "trabalho"
                    self._restante = self.trabalho
                    pausas_concluidas += 1
        return pausas_concluidas

def ajuste_linear(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("tamanhos diferentes")
    if len(xs) < 2:
        raise ValueError("poucos pontos")
    n = len(xs)
    media_x = sum(xs) / n
    media_y = sum(ys) / n
    numerador = sum((x - media_x) * (y - media_y) for x, y in zip(xs, ys))
    denominador = sum((x - media_x) ** 2 for x in xs)
    if denominador == 0:
        raise ValueError("todos os x iguais")
    a = numerador / denominador
    b = media_y - a * media_x
    return (a, b)

def movimentos_hanoi(n, origem, destino, auxiliar):
