    if len({origem, destino, auxiliar}) != 3:
        raise ValueError("os pinos devem ser diferentes")
    if n == 1:
        return [(origem, destino)]
    return (
        movimentos_hanoi(n - 1, origem, auxiliar, destino)
        + [(origem, destino)]
        + movimentos_hanoi(n - 1, auxiliar, destino, origem)
    )

class TabelaEncadeada:
    def __init__(self, capacidade=4):
        if capacidade < 1:
            raise ValueError("capacidade deve ser >= 1")
        self.capacidade = capacidade
        self._baldes = [[] for _ in range(capacidade)]
        self._tamanho = 0

    def _indice(self, chave):
        return hash(chave) % self.capacidade

    def inserir(self, chave, valor):
        i = self._indice(chave)
        balde = self._baldes[i]
        for par in balde:
            if par[0] == chave:
                par[1] = valor
                return
        balde.append([chave, valor])
        self._tamanho += 1

    def buscar(self, chave):
        i = self._indice(chave)
        for par in self._baldes[i]:
            if par[0] == chave:
                return par[1]
        raise KeyError(chave)

    def remover(self, chave):
        i = self._indice(chave)
        balde = self._baldes[i]
        for idx, par in enumerate(balde):
            if par[0] == chave:
                balde.pop(idx)
                self._tamanho -= 1
                return par[1]
        raise KeyError(chave)

    def itens(self):
        resultado = []
        for balde in self._baldes:
            for par in balde:
                resultado.append((par[0], par[1]))
        return resultado

