    soma = list(piramide[-1])
    for i in range(len(piramide) - 2, -1, -1):
        for j in range(len(piramide[i])):
            soma[j] = piramide[i][j] + min(soma[j], soma[j + 1])
    return soma[0]

def contar_vizinhas(tabuleiro, linha, coluna):
    linhas = len(tabuleiro)
    colunas = len(tabuleiro[0])
    if not (0 <= linha < linhas) or not (0 <= coluna < colunas):
        raise ValueError("posicao fora do tabuleiro")
    total = 0
    for dl in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dl == 0 and dc == 0:
                continue
            l, c = linha + dl, coluna + dc
            if 0 <= l < linhas and 0 <= c < colunas:
                if tabuleiro[l][c] == 1:
                    total += 1
    return total


