class ResumoQuartis:
    def __init__(self, dados):
        if not dados:
            raise ValueError("lista vazia")
        self.dados = list(dados)

    def ordenados(self):
        return sorted(self.dados)

    @staticmethod
    def _mediana(lista):
        n = len(lista)
        meio = n // 2
        if n % 2 == 1:
            return float(lista[meio])
        return (lista[meio - 1] + lista[meio]) / 2.0

    def mediana(self):
        return self._mediana(self.ordenados())

    def _metades(self):
        lista = self.ordenados()
        n = len(lista)
        meio = n // 2
        if n % 2 == 1:
            return lista[:meio], lista[meio + 1:]
        return lista[:meio], lista[meio:]

    def q1(self):
        baixo, _ = self._metades()
        return self._mediana(baixo)

    def q3(self):
        _, alto = self._metades()
        return self._mediana(alto)

    def amplitude_interquartil(self):
        return self.q3() - self.q1()

    def resumo(self):
        return {
            "mediana": self.mediana(),
            "q1": self.q1(),
            "q3": self.q3(),
            "iqr": self.amplitude_interquartil(),
        }

