def distancia_edicao(a, b):
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("a e b devem ser strings")
    n, m = len(a), len(b)
    anterior = list(range(m + 1))
    for i in range(1, n + 1):
        atual = [i] + [0] * m
        for j in range(1, m + 1):
            custo = 0 if a[i - 1] == b[j - 1] else 1
            atual[j] = min(anterior[j] + 1, atual[j - 1] + 1, anterior[j - 1] + custo)
        anterior = atual
    return anterior[m]

class ContadorCombinacoes:
    def __init__(self):
        self.historico = []

    @staticmethod
    def _fat(n):
        resultado = 1
        for i in range(2, n + 1):
            resultado *= i
        return resultado

    def fatorial(self, n):
        if n < 0:
            raise ValueError("n nao pode ser negativo")
        resultado = self._fat(n)
        self.historico.append(("fatorial", n, None, resultado))
        return resultado

    def combinacoes(self, n, k):
        if n < 0 or k < 0 or k > n:
            raise ValueError("argumentos invalidos")
        resultado = self._fat(n) // (self._fat(k) * self._fat(n - k))
        self.historico.append(("combinacoes", n, k, resultado))
        return resultado

    def permutacoes(self, n, k):
        if n < 0 or k < 0 or k > n:
            raise ValueError("argumentos invalidos")
        resultado = self._fat(n) // self._fat(n - k)
        self.historico.append(("permutacoes", n, k, resultado))
        return resultado

    def total_calculado(self):
        return sum(item[3] for item in self.historico)

def classificar_numero(n):
