import math


def para_polar(x, y):
    for v in (x, y):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("coordenada invalida")
    if x == 0 and y == 0:
        return (0.0, 0.0)
    raio = math.hypot(x, y)
    angulo = math.degrees(math.atan2(y, x))
    if angulo < 0:
        angulo += 360.0
    return (round(raio, 4), round(angulo, 4))

def subsequencia_comum(a, b):
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("a e b devem ser strings")
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return 0
    anterior = [0] * (m + 1)
    for i in range(1, n + 1):
        atual = [0] * (m + 1)
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                atual[j] = anterior[j - 1] + 1
            else:
                atual[j] = max(anterior[j], atual[j - 1])
        anterior = atual
    return anterior[m]

def avaliar_expressao(texto):
    if not isinstance(texto, str):
        raise ValueError("expressão inválida")
    tokens = []
    i = 0
    while i < len(texto):
        c = texto[i]
        if c == " ":
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < len(texto) and texto[j].isdigit():
                j += 1
            tokens.append(("num", int(texto[i:j])))
            i = j
            continue
        if c in "+-*/()":
            tokens.append(("op", c))
            i += 1
            continue
        raise ValueError("caractere inválido: " + c)
    if not tokens:
        raise ValueError("expressão vazia")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def parse_expr():
        nonlocal pos
        valor = parse_termo()
        while True:
            tipo, val = peek()
            if tipo == "op" and val in "+-":
                pos += 1
                direito = parse_termo()
                if val == "+":
                    valor += direito
                else:
                    valor -= direito
            else:
                return valor

    def parse_termo():
        nonlocal pos
        valor = parse_fator()
        while True:
            tipo, val = peek()
            if tipo == "op" and val in "*/":
                pos += 1
                direito = parse_fator()
                if val == "*":
                    valor *= direito
                else:
                    if direito == 0:
                        raise ValueError("divisão por zero")
                    valor //= direito
            else:
                return valor

    def parse_fator():
        nonlocal pos
        tipo, val = peek()
        if tipo == "num":
            pos += 1
            return val
        if tipo == "op" and val == "(":
            pos += 1
            valor = parse_expr()
            tipo2, val2 = peek()
            if tipo2 != "op" or val2 != ")":
                raise ValueError("parêntese não fechado")
            pos += 1
            return valor
        if tipo == "op" and val == "-":
            pos += 1
            return -parse_fator()
        raise ValueError("expressão inválida")

    resultado = parse_expr()
    if pos != len(tokens):
        raise ValueError("tokens sobrando")
    return resultado

class GeradorTriplas:
    def __init__(self, limite):
        if limite < 1:
            raise ValueError("limite deve ser pelo menos 1")
        self.limite = limite

    def triplas(self):
        resultado = []
        for c in range(1, self.limite + 1):
            for a in range(1, c):
                for b in range(a + 1, c):
                    if a * a + b * b == c * c:
                        resultado.append((a, b, c))
        return resultado

    def quantidade(self):
        return len(self.triplas())

    def maior_hipotenusa(self):
        triplas = self.triplas()
        if not triplas:
            return None
        return max(t[2] for t in triplas)

