class MapaAssentos:
    def __init__(self, filas, colunas):
        if filas <= 0 or colunas <= 0:
            raise ValueError("dimensoes invalidas")
        self.filas = filas
        self.colunas = colunas
        self._grade = [[False] * colunas for _ in range(filas)]

    def _valida(self, fila, coluna):
        if not (0 <= fila < self.filas) or not (0 <= coluna < self.colunas):
            raise ValueError("posicao invalida")

    def reservar(self, fila, coluna):
        self._valida(fila, coluna)
        if self._grade[fila][coluna]:
            raise ValueError("assento ocupado")
        self._grade[fila][coluna] = True
        return True

    def liberar(self, fila, coluna):
        self._valida(fila, coluna)
        if not self._grade[fila][coluna]:
            raise ValueError("assento livre")
        self._grade[fila][coluna] = False
        return True

    def livres(self):
        return sum(1 for linha in self._grade for ocupado in linha if not ocupado)

    def ocupados(self):
        return sum(1 for linha in self._grade for ocupado in linha if ocupado)

def busca_matriz(matriz, alvo):
    if not matriz:
        raise ValueError("matriz vazia")
    for linha in matriz:
        if not linha:
            raise ValueError("linha vazia")
    n_linhas = len(matriz)
    n_colunas = len(matriz[0])
    i, j = 0, n_colunas - 1
    while i < n_linhas and j >= 0:
        valor = matriz[i][j]
        if valor == alvo:
            return (i, j)
        if valor > alvo:
            j -= 1
        else:
            i += 1
    return None

def decompor_saque(valor):
    if valor < 5 or valor % 5 != 0:
        raise ValueError("valor invalido")
    cedulas = [100, 50, 20, 10, 5]
