class FormulaMolar:
    def __init__(self, massas):
        self.massas = dict(massas)

    def _parse(self, formula):
        if not isinstance(formula, str) or not formula:
            raise ValueError("formula vazia")
        pilha = [{}]
        i = 0
        n = len(formula)
        while i < n:
            c = formula[i]
            if c == "(":
                pilha.append({})
                i += 1
            elif c == ")":
                if len(pilha) == 1:
                    raise ValueError("parenteses desbalanceados")
                grupo = pilha.pop()
                i += 1
                j = i
                while j < n and formula[j].isdigit():
                    j += 1
                mult = int(formula[i:j]) if j > i else 1
                if mult == 0:
                    raise ValueError("indice invalido")
                for s, q in grupo.items():
                    pilha[-1][s] = pilha[-1].get(s, 0) + q * mult
                i = j
            elif c.isupper():
                j = i + 1
                while j < n and formula[j].islower():
                    j += 1
                simbolo = formula[i:j]
                if simbolo not in self.massas:
                    raise ValueError("elemento desconhecido: " + simbolo)
                i = j
                k = i
                while k < n and formula[k].isdigit():
                    k += 1
                qtd = int(formula[i:k]) if k > i else 1
                if qtd == 0:
                    raise ValueError("indice invalido")
                pilha[-1][simbolo] = pilha[-1].get(simbolo, 0) + qtd
                i = k
            else:
                raise ValueError("caractere invalido")
        if len(pilha) != 1:
            raise ValueError("parenteses desbalanceados")
        return pilha[0]

    def contar_elementos(self, formula):
        return self._parse(formula)

    def massa(self, formula):
        contagem = self._parse(formula)
        total = 0.0
        for simbolo, qtd in contagem.items():
            total += self.massas[simbolo] * qtd
        return total

class ComplexoTupla:
    def __init__(self, real=0.0, imag=0.0):
        self.partes = (real, imag)

    def _checar(self, outro):
        if not isinstance(outro, ComplexoTupla):
            raise TypeError("esperado ComplexoTupla")

    def soma(self, outro):
        self._checar(outro)
        return ComplexoTupla(self.partes[0] + outro.partes[0],
                             self.partes[1] + outro.partes[1])

    def multiplica(self, outro):
        self._checar(outro)
        a, b = self.partes
        c, d = outro.partes
        return ComplexoTupla(a * c - b * d, a * d + b * c)

    def conjugado(self):
        return ComplexoTupla(self.partes[0], -self.partes[1])

    def modulo(self):
        a, b = self.partes
        return (a * a + b * b) ** 0.5

    def __str__(self):
        a, b = self.partes
        sinal = "+" if b >= 0 else "-"
        return f"{a}{sinal}{abs(b)}i"

class FarolSemaforo:
