        raise TypeError("palavra deve ser um texto não vazio")
    if not isinstance(letras_acertadas, list):
        raise TypeError("letras_acertadas deve ser uma lista")
    acertos = set()
    for letra in letras_acertadas:
        if not isinstance(letra, str) or len(letra) != 1:
            raise ValueError("cada acerto deve ser uma letra")
