class JogoMemoria:
    def __init__(self, cartas):
        if len(cartas) != 4:
            raise ValueError("precisa de 4 cartas")
        contagem = {}
        for c in cartas:
            contagem[c] = contagem.get(c, 0) + 1
        if any(v != 2 for v in contagem.values()):
            raise ValueError("cada valor deve aparecer duas vezes")
        self.cartas = list(cartas)
        self.viradas = []
        self.encontrados = set()

    def virar(self, indice):
        if indice < 0 or indice > 3:
            raise ValueError("indice invalido")
        if indice in self.viradas or indice in self.encontrados:
            raise ValueError("carta ja visivel")
        if len(self.viradas) == 2:
            self.limpar_turno()
        self.viradas.append(indice)
        if len(self.viradas) == 1:
            return "primeira"
        a, b = self.viradas
        if self.cartas[a] == self.cartas[b]:
            return "par"
        return "nao_par"

    def limpar_turno(self):
        if len(self.viradas) == 2:
            a, b = self.viradas
            if self.cartas[a] == self.cartas[b]:
                self.encontrados.add(a)
                self.encontrados.add(b)
            self.viradas = []

    def resolvidas(self):
        return len(self.encontrados) // 2

