class FilaDuasPilhas:
    def __init__(self):
        self._entrada = []
        self._saida = []

    def enfileirar(self, item):
        self._entrada.append(item)

    def _transferir(self):
        if not self._saida:
            while self._entrada:
                self._saida.append(self._entrada.pop())

    def desenfileirar(self):
        self._transferir()
        if not self._saida:
            raise IndexError("fila vazia")
        return self._saida.pop()

    def frente(self):
        self._transferir()
        if not self._saida:
            raise IndexError("fila vazia")
        return self._saida[-1]

    def tamanho(self):
        return len(self._entrada) + len(self._saida)

def converter_para_posfixa(expressao):
    precedencia = {'+': 1, '-': 1, '*': 2, '/': 2}
    saida = []
    operadores = []
    tokens = expressao.split()
    if not tokens:
        raise ValueError("expressao vazia")
    for token in tokens:
        if token.isdigit():
            saida.append(token)
        elif token in precedencia:
            while (operadores and operadores[-1] in precedencia
                   and precedencia[operadores[-1]] >= precedencia[token]):
                saida.append(operadores.pop())
            operadores.append(token)
        elif token == '(':
            operadores.append(token)
        elif token == ')':
            while operadores and operadores[-1] != '(':
                saida.append(operadores.pop())
            if not operadores:
                raise ValueError("parenteses desbalanceados")
            operadores.pop()
        else:
            raise ValueError("token invalido")
    while operadores:
        op = operadores.pop()
        if op == '(':
            raise ValueError("parenteses desbalanceados")
        saida.append(op)
    return ' '.join(saida)

def chaves_em_comum(a, b):
