def _validar(pesos, valores, capacidade):
    if len(pesos) != len(valores):
        raise ValueError("tamanhos diferentes")
    for p in pesos:
        if p < 0:
            raise ValueError("peso negativo")
    for v in valores:
        if v < 0:
            raise ValueError("valor negativo")
    if capacidade < 0:
        raise ValueError("capacidade negativa")


def melhor_valor(pesos, valores, capacidade):
    _validar(pesos, valores, capacidade)
    n = len(pesos)
    tabela = [[0] * (capacidade + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        p = pesos[i - 1]
        v = valores[i - 1]
        for c in range(capacidade + 1):
            tabela[i][c] = tabela[i - 1][c]
            if p <= c:
                alt = tabela[i - 1][c - p] + v
                if alt > tabela[i][c]:
                    tabela[i][c] = alt
    return tabela[n][capacidade]


def itens_escolhidos(pesos, valores, capacidade):
    _validar(pesos, valores, capacidade)
    n = len(pesos)
    tabela = [[0] * (capacidade + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        p = pesos[i - 1]
        v = valores[i - 1]
        for c in range(capacidade + 1):
            tabela[i][c] = tabela[i - 1][c]
            if p <= c:
                alt = tabela[i - 1][c - p] + v
                if alt > tabela[i][c]:
                    tabela[i][c] = alt
    escolhidos = []
    c = capacidade
    for i in range(n, 0, -1):
        if tabela[i][c] != tabela[i - 1][c]:
            escolhidos.append(i - 1)
            c -= pesos[i - 1]
    escolhidos.reverse()
    return escolhidos

def pares_invertidos(lista):
    if not isinstance(lista, list):
        raise ValueError("entrada deve ser uma lista")
    pares = []
    for i in range(len(lista)):
        for j in range(i + 1, len(lista)):
            if lista[i] > lista[j]:
                pares.append((i, j))
    return pares


def contar_inversoes(lista):
    return len(pares_invertidos(lista))

def valor_com_abatimento(preco, percentual):
    if preco < 0:
        raise ValueError("preco nao pode ser negativo")
    if percentual < 0 or percentual > 100:
        raise ValueError("percentual deve estar entre 0 e 100")
    return preco - preco * percentual / 100

class ConfigParser:
