        self._ordem = []
        if texto.strip() == "":
            return
        for trecho in texto.split(";"):
            if "=" not in trecho:
                raise ValueError("trecho sem '=': %r" % trecho)
            chave, valor = trecho.split("=", 1)
            chave = chave.strip()
            valor = valor.strip()
            if chave not in self._dados:
