        return self._dados.get(chave, padrao)

    def chaves(self):
        return list(self._ordem)

import heapq


def menor_custo(grafo, origem, destino):
    if origem not in grafo or destino not in grafo:
        raise ValueError("no inexistente")
    dist = {origem: 0}
    fila = [(0, origem)]
    while fila:
        custo, no = heapq.heappop(fila)
        if no == destino:
            return custo
        if custo > dist.get(no, float("inf")):
            continue
        for vizinho, peso in grafo[no]:
            novo = custo + peso
            if novo < dist.get(vizinho, float("inf")):
                dist[vizinho] = novo
                heapq.heappush(fila, (novo, vizinho))
    return None


def nos_alcancaveis(grafo, origem):
    if origem not in grafo:
        raise ValueError("no inexistente")
    vistos = {origem}
    pilha = [origem]
    while pilha:
        no = pilha.pop()
        for vizinho, _peso in grafo[no]:
            if vizinho not in vistos:
                vistos.add(vizinho)
                pilha.append(vizinho)
    return sorted(vistos)

class CifraColunas:
    def __init__(self, colunas):
        if not isinstance(colunas, int) or isinstance(colunas, bool) or colunas <= 0:
            raise ValueError("colunas deve ser inteiro positivo")
        self.colunas = colunas

    def cifrar(self, texto):
        if not texto:
            return ""
        linhas = [texto[i:i + self.colunas] for i in range(0, len(texto), self.colunas)]
        resultado = []
        for c in range(self.colunas):
            for linha in linhas:
                if c < len(linha):
                    resultado.append(linha[c])
        return "".join(resultado)

    def decifrar(self, texto_cifrado):
        n = len(texto_cifrado)
        if n == 0:
            return ""
        linhas = (n + self.colunas - 1) // self.colunas
        completa = n % self.colunas
        if completa == 0:
            tamanhos = [linhas] * self.colunas
        else:
            tamanhos = [linhas] * completa + [linhas - 1] * (self.colunas - completa)
        colunas_texto = []
        pos = 0
        for t in tamanhos:
            colunas_texto.append(texto_cifrado[pos:pos + t])
            pos += t
        resultado = []
        for l in range(linhas):
            for col in colunas_texto:
                if l < len(col):
                    resultado.append(col[l])
        return "".join(resultado)

class SubsequenciaComum:
    def __init__(self, a, b):
        if not isinstance(a, str) or not isinstance(b, str):
            raise ValueError("palavras devem ser texto")
        self.a = a
        self.b = b

    def tabela(self):
        n, m = len(self.a), len(self.b)
        t = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if self.a[i - 1] == self.b[j - 1]:
                    t[i][j] = t[i - 1][j - 1] + 1
                else:
                    t[i][j] = max(t[i - 1][j], t[i][j - 1])
        return t

    def comprimento(self):
        return self.tabela()[len(self.a)][len(self.b)]

    def obter(self):
        t = self.tabela()
        i, j = len(self.a), len(self.b)
        partes = []
        while i > 0 and j > 0:
            if self.a[i - 1] == self.b[j - 1]:
                partes.append(self.a[i - 1])
                i -= 1
                j -= 1
            elif t[i - 1][j] >= t[i][j - 1]:
                i -= 1
            else:
                j -= 1
        return "".join(reversed(partes))

def cifrar_vigenere(texto, chave):
    if not chave or not all('A' <= c <= 'Z' for c in chave):
        raise ValueError("chave inválida")
    deslocamentos = [ord(c) - ord('A') for c in chave]
    resultado = []
    i = 0
    for c in texto:
        if 'A' <= c <= 'Z':
            d = deslocamentos[i % len(deslocamentos)]
            resultado.append(chr((ord(c) - ord('A') + d) % 26 + ord('A')))
            i += 1
        else:
            resultado.append(c)
    return ''.join(resultado)

def pontuar_frame(rolagens):
    if len(rolagens) > 2:
        raise ValueError("frame com rolagens demais")
    for r in rolagens:
        if r < 0 or r > 10:
            raise ValueError("pinos fora do intervalo")
    return sum(rolagens)


def placar_total(rolagens):
    for r in rolagens:
        if r < 0 or r > 10:
            raise ValueError("pinos fora do intervalo")
    total = 0
    i = 0
    n = len(rolagens)
    while i < n:
        if rolagens[i] == 10:
            if i + 2 < n:
                total += 10 + rolagens[i + 1] + rolagens[i + 2]
            i += 1
        elif i + 1 < n and rolagens[i] + rolagens[i + 1] == 10:
            if i + 2 < n:
                total += 10 + rolagens[i + 2]
            i += 2
        else:
            total += rolagens[i]
            if i + 1 < n:
                total += rolagens[i + 1]
            i += 2
    return total

def falta_ingrediente(estoque, necessario):
    for qtd in list(estoque.values()) + list(necessario.values()):
        if qtd < 0:
            raise ValueError("quantidade negativa")
    faltando = []
    for nome, qtd_necessaria in necessario.items():
        if estoque.get(nome, 0) < qtd_necessaria:
            faltando.append(nome)
    return sorted(faltando)


def pode_cozinhar(estoque, necessario):
    return falta_ingrediente(estoque, necessario) == []

def contar_trocados(valor, moedas):
    if valor < 0:
        raise ValueError("valor negativo")
    if not moedas:
        raise ValueError("lista de moedas vazia")
    for m in moedas:
        if not isinstance(m, int) or isinstance(m, bool) or m <= 0:
            raise ValueError("moeda invalida")
    ways = [0] * (valor + 1)
    ways[0] = 1
    for m in moedas:
        for v in range(m, valor + 1):
            ways[v] += ways[v - m]
    return ways[valor]

def todos_presentes(base, consulta):
