    for item in consulta:
        if item not in base and item not in resultado:
            resultado.append(item)
    return resultado

class MultaBiblioteca:
    FAIXAS = [(3, 0.50), (7, 1.00), (None, 2.00)]

    def __init__(self, devolucoes):
        self._multas = {}
        self._ordem = []
        for titulo, dias in devolucoes:
            if dias < 0:
                raise ValueError("dias de atraso negativos")
            self._multas[titulo] = self._calcular(dias)
            self._ordem.append(titulo)

    def _calcular(self, dias):
        total = 0.0
        restante = dias
        anterior = 0
        for limite, valor in self.FAIXAS:
            if limite is None:
                total += restante * valor
                break
            faixa = min(restante, limite - anterior)
            if faixa > 0:
                total += faixa * valor
            restante -= faixa
            anterior = limite
            if restante <= 0:
                break
        return total

    def multa_item(self, titulo):
        return self._multas.get(titulo)

    def total(self):
        return sum(self._multas.values())

    def titulos_acima_de(self, valor):
        return [t for t in self._ordem if self._multas[t] > valor]

import math


class Trajetoria:
    def __init__(self):
        self._pontos = []

    def adicionar(self, x, y):
        for valor in (x, y):
            if isinstance(valor, bool) or not isinstance(valor, (int, float)):
                raise ValueError("coordenada invalida")
        self._pontos.append((x, y))

    def quantidade(self):
        return len(self._pontos)

    def polar(self, indice):
        if not isinstance(indice, int) or isinstance(indice, bool):
            raise IndexError("indice invalido")
        if indice < 0 or indice >= len(self._pontos):
            raise IndexError("indice fora do intervalo")
        x, y = self._pontos[indice]
        r = math.hypot(x, y)
        angulo = math.degrees(math.atan2(y, x))
        if angulo < 0:
            angulo += 360
        return (r, angulo)

    def limpar(self):
        self._pontos = []

def avaliar(coeficientes, x):
    if not coeficientes:
        raise ValueError("lista de coeficientes vazia")
    resultado = 0
    for c in coeficientes:
        resultado = resultado * x + c
    return resultado


def derivada(coeficientes):
    if not coeficientes:
        raise ValueError("lista de coeficientes vazia")
    if len(coeficientes) == 1:
        return [0]
    return [c * (len(coeficientes) - 1 - i) for i, c in enumerate(coeficientes[:-1])]

def contagens_letras(texto):
    if not isinstance(texto, str):
        raise TypeError("texto deve ser uma string")
    contagens = {}
    for letra in texto.lower():
        if letra.isalpha():
            contagens[letra] = contagens.get(letra, 0) + 1
    return contagens


def primeira_solta(texto):
    contagens = contagens_letras(texto)
    for letra in texto.lower():
        if letra.isalpha() and contagens[letra] == 1:
            return letra
    return None

def _soma_divisores_proprios(n):
    soma = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            soma += d
            outro = n // d
            if outro != d:
                soma += outro
        d += 1
    return soma


def _eh_perfeito(n):
    if n < 2:
        return False
    return _soma_divisores_proprios(n) == n


def menor_perfeito_acima(limite):
    if isinstance(limite, bool) or not isinstance(limite, int):
        raise ValueError("limite deve ser um inteiro")
    if limite < 0:
        raise ValueError("limite nao pode ser negativo")
    candidato = limite + 1
    if candidato < 6:
        candidato = 6
    while not _eh_perfeito(candidato):
        candidato += 1
    return candidato

class AnalisadorFrase:
