class ColecaoPontos:
    def __init__(self):
        self._pontos = []

    def adicionar(self, ponto):
        if (not isinstance(ponto, tuple) or len(ponto) != 2
                or not all(isinstance(c, (int, float)) and not isinstance(c, bool) for c in ponto)):
            raise ValueError("ponto invalido")
        self._pontos.append(ponto)

    def quantidade(self):
        return len(self._pontos)

    def ponto_medio(self):
        if not self._pontos:
            return None
        n = len(self._pontos)
        sx = sum(p[0] for p in self._pontos)
        sy = sum(p[1] for p in self._pontos)
        return (sx / n, sy / n)

    def baricentro(self, indices):
        if not indices:
            raise ValueError("indices vazios")
        n = len(self._pontos)
        for i in indices:
            if not isinstance(i, int) or isinstance(i, bool) or i < 0 or i >= n:
                raise ValueError("indice invalido")
        sx = sum(self._pontos[i][0] for i in indices)
        sy = sum(self._pontos[i][1] for i in indices)
        k = len(indices)
        return (sx / k, sy / k)

def somar_posicoes(itens):
    if not isinstance(itens, (list, tuple)):
        raise ValueError("esperado lista ou tupla")
    soma_pares = 0
    soma_impares = 0
    for indice, valor in enumerate(itens):
        if isinstance(valor, bool) or not isinstance(valor, (int, float)):
            raise ValueError("elemento não numérico")
        if indice % 2 == 0:
            soma_pares += valor
        else:
            soma_impares += valor
    return (soma_pares, soma_impares)

def componentes(arestas):
    adjacencia = {}
    for u, v in arestas:
        adjacencia.setdefault(u, set()).add(v)
        adjacencia.setdefault(v, set()).add(u)
    vistos = set()
    resultado = []
    for inicio in sorted(adjacencia):
        if inicio in vistos:
            continue
        pilha = [inicio]
        vistos.add(inicio)
        grupo = []
        while pilha:
            atual = pilha.pop()
            grupo.append(atual)
            for vizinho in adjacencia[atual]:
                if vizinho not in vistos:
                    vistos.add(vizinho)
                    pilha.append(vizinho)
        resultado.append(sorted(grupo))
    return resultado


def mesmo_componente(arestas, a, b):
    vertices = set()
    for u, v in arestas:
        vertices.add(u)
        vertices.add(v)
    if a not in vertices:
        raise ValueError("vertice inexistente: %r" % (a,))
    if b not in vertices:
        raise ValueError("vertice inexistente: %r" % (b,))
    for grupo in componentes(arestas):
        if a in grupo and b in grupo:
            return True
    return False
